window.COURSE_META={"version":"3.0.0","title":"Seacon 航运学院","basis":"《主流船型必须搞懂的知识白皮书》v2.1","authorship":"LLM 逐题综合白皮书知识点、真实误区与实务场景后编写；构建期静态打包，离线不调用外部 API。","unitCount":16,"lessonCount":80,"questionCount":448};
window.COURSE=[{"id":"u01","t":"航运世界地图","s":"先认人，再看一条船怎样运转","c":"#16a085","i":"🧭","guide":"航运不是‘船东把船开出去’这么简单。先把货、船、钱、责任四条线拆开，再把角色放回一条船的生命周期。","outcomes":["说清船东、船管、租家和经纪人的边界","区分所有权、经营权与技术管理","沿生命周期追踪现金流和风险"],"L":[{"t":"三个起点","goal":"建立货、船、钱三张最小地图","intro":"任何航运项目都可以先问三件事：谁有货、谁控制船、谁承担成本。角色名称会变，三条线不会变。","keys":["货物流不等于合同流","控制船不等于拥有船","收入必须和对应成本放在一起"],"trap":"看到公司名字就凭印象判断角色，而不看合同和成本责任。","source":"白皮书 0.1—0.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"一票铁矿石要从巴西运到中国。最先应确认哪一项？","o":["船东办公室在哪","船龄是否为偶数","船身涂什么颜色","谁拥有货运需求及装卸港约束"],"a":"谁拥有货运需求及装卸港约束","w":"货物、港口和时间窗口决定需要什么运输能力；在此之前讨论具体船舶往往过早。","pre":"","id":"u01-l01-q01","source":"白皮书 0.1—0.3"},{"k":"mc","q":"某公司持有船舶产权，却把船光租给另一家公司十年。哪句话最准确？","o":["产权公司一定支付燃油费","产权公司一定负责日常营运","承租方在租期内取得高度经营控制","光租等于出售"],"a":"承租方在租期内取得高度经营控制","w":"光船租赁转移的是长期占有和经营控制，不转移法律所有权；成本责任仍需以合同为准。","pre":"","id":"u01-l01-q02","source":"白皮书 0.1—0.3"},{"k":"tf","q":"登记船东只说明产权身份；谁收运费、谁付油钱仍需查看租约。","o":["正确","错误"],"a":"正确","w":"登记所有权只能回答产权身份，不能替代租约。运费收入和燃油责任要看 TC、VC、BBC 等合同结构。","pre":"","id":"u01-l01-q03","source":"白皮书 0.1—0.3"},{"k":"multi","q":"给一个陌生航运项目做初筛，哪些问题应进入第一轮？","o":["谁控制船舶使用","主要收入合同是什么","董事长喜欢哪种船模","货是什么、从哪到哪"],"a":["货是什么、从哪到哪","谁控制船舶使用","主要收入合同是什么"],"w":"前三问分别抓住需求、控制权和现金流。偏好类信息不能替代项目事实。","pre":"","id":"u01-l01-q04","source":"白皮书 0.1—0.3"},{"k":"prod","q":"用一句话解释为什么航运分析要把‘船’和‘公司’分开。","model":"同一条船的产权、技术管理、商业运营和承租安排可能由不同公司承担，只有逐层识别合同角色，才能判断收入、成本和风险落在谁身上。","a":"同一条船的产权、技术管理、商业运营和承租安排可能由不同公司承担，只有逐层识别合同角色，才能判断收入、成本和风险落在谁身上。","w":"这句话的关键不是背角色，而是说明一船多主体以及责任由合同分配。","pre":"","id":"u01-l01-q05","source":"白皮书 0.1—0.3"}]},{"t":"一条船背后的人","goal":"识别核心参与者及其交付物","intro":"船东提供资产，租家购买运力，船管保证适航与合规，经纪人促成交易，船级社与旗国维持技术和法定框架。","keys":["商业管理与技术管理分开看","经纪人通常不是合同本金方","船级社不替代船东责任"],"trap":"把提供意见或认证的第三方，当成承担经营结果的本金方。","source":"白皮书 0.4—0.7","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"主机计划检修、船员配备和安全管理体系通常首先落在哪类职能？","o":["货运代理","大宗商品交易","港口海关","技术船舶管理"],"a":"技术船舶管理","w":"技术管理围绕船员、维修、备件、安全和证书，目标是让船持续适航、合规并可营运。","pre":"","id":"u01-l02-q01","source":"白皮书 0.4—0.7"},{"k":"mc","q":"经纪人在一笔期租交易中的典型价值是什么？","o":["连接信息、传递报价并协助形成条款","签发船级证书","决定港口是否封航","替船东承担全部违约责任"],"a":"连接信息、传递报价并协助形成条款","w":"经纪人提高信息与谈判效率，但通常不是租约的本金方，也不自动担保双方履约。","pre":"","id":"u01-l02-q02","source":"白皮书 0.4—0.7"},{"k":"tf","q":"有效船级证书是技术状态证据，但不会免除船东持续维护和适航责任。","o":["正确","错误"],"a":"正确","w":"船级证书是技术状态的重要证据，却不是经营责任豁免。船东仍需维护、配员并满足合同和法定要求。","pre":"","id":"u01-l02-q03","source":"白皮书 0.4—0.7"},{"k":"multi","q":"哪些主体可能直接影响一条船能否合法、持续营运？","o":["旗国主管机关","船级社","技术船管","社交媒体粉丝"],"a":["旗国主管机关","船级社","技术船管"],"w":"法定证书、船级状态和技术管理共同决定船是否能持续营运；热度不构成营运资格。","pre":"","id":"u01-l02-q04","source":"白皮书 0.4—0.7"},{"k":"prod","q":"客户问‘谁在管船’，请给出一个不会误导的追问。","model":"您问的是技术管理、商业运营还是租约下的实际使用控制？这三项可能由不同主体承担，需要结合管理协议和租约确认。","a":"您问的是技术管理、商业运营还是租约下的实际使用控制？这三项可能由不同主体承担，需要结合管理协议和租约确认。","w":"好追问会把模糊的‘管’拆成技术、商业与使用控制三层。","pre":"","id":"u01-l02-q05","source":"白皮书 0.4—0.7"}]},{"t":"所有权与控制权","goal":"分清法律产权、商业经营和实际使用","intro":"船舶可以由单船公司持有，由集团管理，再出租给第三方。分析时应沿登记—管理协议—租约逐层穿透。","keys":["SPV 可隔离单船风险","最终受益人不等于登记船东","租期和条款决定控制强弱"],"trap":"把集团品牌当成合同主体，忽略单船公司和担保链。","source":"白皮书 0.8、3.2","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"为什么航运集团常为每条船设立单船公司 SPV？","o":["让船航速更快","便于资产持有、融资和风险隔离","免除一切税费","替代船级社"],"a":"便于资产持有、融资和风险隔离","w":"SPV 让产权、贷款和现金流可单独识别；但隔离效果取决于担保、交叉违约和实际安排。","pre":"","id":"u01-l03-q01","source":"白皮书 0.8、3.2"},{"k":"mc","q":"合同抬头是 Ship Alpha Ltd.，集团宣传页写的是 Ocean Group。签约前最重要的动作是？","o":["只看集团 Logo","要求更换船名","直接把两者当成同一主体","核对注册、授权、所有权和担保关系"],"a":"核对注册、授权、所有权和担保关系","w":"品牌不能替代法律主体审查。要确认谁签字、是否获授权、是否有资产或有效担保支持履约。","pre":"","id":"u01-l03-q02","source":"白皮书 0.8、3.2"},{"k":"tf","q":"最终受益所有人、登记船东和商业运营人可以是三个不同主体。","o":["正确","错误"],"a":"正确","w":"这正是航运结构常态。穿透三层有助于判断制裁、信用、现金流和追索路径。","pre":"","id":"u01-l03-q03","source":"白皮书 0.8、3.2"},{"k":"multi","q":"判断一家公司是否真正控制船舶使用，应查看哪些材料？","o":["船舶登记摘要","办公楼装修照片","租约及其补充协议","管理协议"],"a":["租约及其补充协议","管理协议","船舶登记摘要"],"w":"登记材料说明产权，管理协议说明受托管理，租约说明商业或实际使用控制，三者需交叉验证。","pre":"","id":"u01-l03-q04","source":"白皮书 0.8、3.2"},{"k":"prod","q":"解释‘拥有一条船’为什么至少有两层含义。","model":"法律上可以指持有船舶产权；商业上也可能指在一段时间内拥有调度和收益控制。前者看登记，后者看租约及管理安排，二者不能混用。","a":"法律上可以指持有船舶产权；商业上也可能指在一段时间内拥有调度和收益控制。前者看登记，后者看租约及管理安排，二者不能混用。","w":"完整答案必须同时落到产权和经营控制，并指出证据不同。","pre":"","id":"u01-l03-q05","source":"白皮书 0.8、3.2"}]},{"t":"生命周期与钱流","goal":"把建造、运营、交易、退出串成一条线","intro":"一条船经历订造、建造、交付、营运、修理改造、买卖和拆解。不同阶段的付款节点、文件和风险完全不同。","keys":["里程碑付款对应建造风险","营运现金流受租约与停航共同影响","残值是退出端的重要假设"],"trap":"只盯买入价，不画后续资本开支、营运现金流和退出情景。","source":"白皮书 0.9、3.1、7.1","kind":"skill","difficulty":1,"q":[{"k":"order","q":"把新造船进入营运的主要阶段按先后排列。","o":["签订建造合同并生效","按里程碑建造和付款","海试及技术验收","交付、登记并投入营运"],"a":["签订建造合同并生效","按里程碑建造和付款","海试及技术验收","交付、登记并投入营运"],"w":"合同先锁定规格和责任，建造期间按节点付款，海试验证性能，交付后才进入登记与营运阶段。","pre":"","id":"u01-l04-q01","source":"白皮书 0.9、3.1、7.1"},{"k":"mc","q":"评估一条老龄船的持有收益时，最容易漏掉哪类现金流？","o":["船名中字母数量","办公室房租","经纪人生日","未来坞修、特检和环保改造支出"],"a":"未来坞修、特检和环保改造支出","w":"老龄船可能很便宜，却临近集中资本开支。只看购买价会高估真实收益。","pre":"","id":"u01-l04-q02","source":"白皮书 0.9、3.1、7.1"},{"k":"tf","q":"船舶出售并收款后，仍需完成权属、抵押注销、交接和存续义务的收尾。","o":["正确","错误"],"a":"正确","w":"仍要确认所有权转移、抵押注销、船舶交接、文件归档、税费和存续保证等事项是否完成。","pre":"","id":"u01-l04-q03","source":"白皮书 0.9、3.1、7.1"},{"k":"multi","q":"画项目全周期现金流时，哪些项目通常应被纳入？","o":["租金或运费收入","OPEX 与坞修","出售或拆船残值","购买或建造付款"],"a":["购买或建造付款","租金或运费收入","OPEX 与坞修","出售或拆船残值"],"w":"四项分别覆盖进入、持有、维护和退出，缺一项都可能扭曲 IRR 和偿债判断。","pre":"","id":"u01-l04-q04","source":"白皮书 0.9、3.1、7.1"},{"k":"prod","q":"用‘进入—持有—退出’框架概括一条船的投资分析。","model":"进入端看船价、付款和融资；持有端看租约收入、OPEX、停航与资本开支；退出端看出售时点、残值和交易成本，并对关键假设做压力测试。","a":"进入端看船价、付款和融资；持有端看租约收入、OPEX、停航与资本开支；退出端看出售时点、残值和交易成本，并对关键假设做压力测试。","w":"这是后续财务、市场和交易章节共同使用的骨架。","pre":"","id":"u01-l04-q05","source":"白皮书 0.9、3.1、7.1"}]},{"t":"单元闯关：看懂一条船","goal":"综合辨认角色、控制权与生命周期","intro":"这一关不再给单一概念，而是把主体、合同和现金流放进同一情景。先找证据，再下结论。","keys":["先识别合同主体","再定位成本与控制","最后检查阶段性风险"],"trap":"根据公司品牌或单一证书直接跳到结论。","source":"白皮书第 0 章综合","kind":"checkpoint","difficulty":2,"q":[{"k":"mc","q":"SPV 持船、集团船管、贸易商期租。谁最可能决定日常装什么货和跑哪条航线？","o":["贸易商，但受租约和安全限制","船级社","登记处","造船厂"],"a":"贸易商，但受租约和安全限制","w":"期租下租家通常发出商业航次指示，船东仍负责航海安全、适航和合同边界。","pre":"","id":"u01-l05-q01","source":"白皮书第 0 章综合"},{"k":"mc","q":"同一情景下，谁最可能组织主机维修和船员管理？","o":["贸易商采购员","港口引航员","货主保险人","集团技术船管"],"a":"集团技术船管","w":"维修和配员属于技术管理；即使租家控制商业使用，也不当然接管技术职责。","pre":"","id":"u01-l05-q02","source":"白皮书第 0 章综合"},{"k":"tf","q":"只要集团提供母公司担保，单船公司审查就没有必要。","o":["正确","错误"],"a":"错误","w":"仍需确认借款人或合同方自身义务、担保范围、授权、适用法和可执行性。担保是加固，不是替代。","pre":"","id":"u01-l05-q03","source":"白皮书第 0 章综合"},{"k":"multi","q":"一艘船临近特检又计划出售，买方应同时关注哪些线索？","o":["检验到期日","预计修理清单","当前租约能否转让","卖方宣传视频播放量"],"a":["检验到期日","预计修理清单","当前租约能否转让"],"w":"技术资本开支与合同可转移性会共同影响估值和交割安排。","pre":"","id":"u01-l05-q04","source":"白皮书第 0 章综合"},{"k":"order","q":"按一套稳健的项目初筛顺序排列。","o":["确认货流与商业目的","识别产权、管理和租约主体","拆分收入与成本责任","检查全周期风险和退出路径"],"a":["确认货流与商业目的","识别产权、管理和租约主体","拆分收入与成本责任","检查全周期风险和退出路径"],"w":"从需求出发，再看主体和合同，之后量化现金流，最后审视风险与退出，可以避免先有结论后找材料。","pre":"","id":"u01-l05-q05","source":"白皮书第 0 章综合"},{"k":"mc","q":"某人说‘船东每天都收运费，所以油价上涨一定由船东承担’。问题在哪？","o":["没有先确认租约类型与成本分配","运费永远不变","油价与航运无关","船东不能拥有船"],"a":"没有先确认租约类型与成本分配","w":"VC、TC、BBC 的收入形式和燃油责任不同。任何成本判断都应先落到具体租约。","pre":"","id":"u01-l05-q06","source":"白皮书第 0 章综合"},{"k":"prod","q":"收到一页只有船名、船龄、船价的项目简介，你会补问哪五类信息？","model":"至少补问：货流或用途、产权与控制主体、现有或目标租约、技术与合规状态、全周期现金流及退出安排；再索取能支持这些说法的合同和证书。","a":"至少补问：货流或用途、产权与控制主体、现有或目标租约、技术与合规状态、全周期现金流及退出安排；再索取能支持这些说法的合同和证书。","w":"问题要覆盖需求、主体、合同、资产和经济性，而不是继续堆孤立参数。","pre":"","id":"u01-l05-q07","source":"白皮书第 0 章综合"},{"k":"mc","q":"下列哪句话最能代表本单元的方法？","o":["先看合同和证据，再判断角色与钱流","船名能说明一切","所有船东责任相同","证书有效就没有风险"],"a":"先看合同和证据，再判断角色与钱流","w":"航运结构复杂但并不神秘：把合同主体、控制权、成本和生命周期逐层核对即可。","pre":"","id":"u01-l05-q08","source":"白皮书第 0 章综合"}]}]},{"id":"u02","t":"船型与货物","s":"不是背船名，而是理解货物怎样塑造船","c":"#2d7dd2","i":"🚢","guide":"船型是货物物理性质、港口条件和运输方式共同作用的结果。先问货物怕什么、怎么装卸，再理解船为什么长成那样。","outcomes":["按货物和装卸方式辨认八大船型族","理解常见尺度名背后的贸易逻辑","避免把尺度等级当成精确规格"],"L":[{"t":"八大船型族","goal":"用货物—舱型—装卸方式建立分类","intro":"干散货、集装箱、油轮、化学品船、气体船、滚装船、客船和海工船解决的是不同运输问题。","keys":["固体散货重视舱容和港口","液体货重视分舱、泵和涂层","气体货重视温度或压力"],"trap":"只按外形猜船型，不看舱内系统和货物状态。","source":"白皮书 1.1—1.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"运输铁矿石、煤炭和粮食的主力船型是？","o":["干散货船","LNG 船","集装箱船","滚装船"],"a":"干散货船","w":"这些是无需包装、直接装入货舱的固体散装货。舱口、货舱和抓斗等装卸条件决定效率。","pre":"","id":"u02-l01-q01","source":"白皮书 1.1—1.3"},{"k":"mc","q":"下列哪组‘货物—船型’匹配最合理？","o":["原油—油轮","液化天然气—普通散货船","汽车—原油轮","集装箱—平台供应船"],"a":"原油—油轮","w":"原油需要液货舱、管线和泵系；其他三组忽略了货物状态与装卸系统。","pre":"","id":"u02-l01-q02","source":"白皮书 1.1—1.3"},{"k":"tf","q":"化学品的腐蚀、污染和相容性风险，会让其分舱、涂层与清洗要求区别于普通原油运输。","o":["正确","错误"],"a":"正确","w":"化学品可能腐蚀、污染或互不相容，通常需要更多分舱、专用涂层和更复杂的清洗隔离。","pre":"","id":"u02-l01-q03","source":"白皮书 1.1—1.3"},{"k":"multi","q":"哪些因素会直接塑造船型设计？","o":["装卸方式","航线港口限制","公司宣传口号","货物物理状态"],"a":["货物物理状态","装卸方式","航线港口限制"],"w":"固液气状态决定储运系统，装卸方式决定舱口泵管，港口尺度决定吃水和尺度。","pre":"","id":"u02-l01-q04","source":"白皮书 1.1—1.3"},{"k":"prod","q":"不用背定义，解释为什么集装箱船有规整的舱格。","model":"集装箱尺寸标准化，船舶需要用舱格导轨和甲板系固把箱位固定，才能快速装卸、控制堆叠并保持稳性，所以内部布局高度规则化。","a":"集装箱尺寸标准化，船舶需要用舱格导轨和甲板系固把箱位固定，才能快速装卸、控制堆叠并保持稳性，所以内部布局高度规则化。","w":"解释应从标准化货物和高周转装卸反推结构。","pre":"","id":"u02-l01-q05","source":"白皮书 1.1—1.3"}]},{"t":"干散货尺度","goal":"理解 Handy 到 Newcastlemax 的业务语境","intro":"干散货尺度名不是全球唯一边界，而是对运力、港口适配和典型货流的行业速记。","keys":["Handysize 灵活","Panamax/Kamsarmax 受港口尺度塑造","Capesize 典型跑长距离大宗货"],"trap":"把尺度名称当成精确且永久不变的载重吨区间。","source":"白皮书 1.4、术语表","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"一条吃水受限、装卸设施一般的小港航线，更可能偏好哪类特征？","o":["较小尺度且自带装卸设备","最大尺度且无吊杆","只看最高航速","必须是 LNG 船"],"a":"较小尺度且自带装卸设备","w":"港口水深和岸机能力有限时，较小吃水及船吊能提高可达性和独立装卸能力。","pre":"","id":"u02-l02-q01","source":"白皮书 1.4、术语表"},{"k":"mc","q":"Capesize 名称最初反映了什么贸易直觉？","o":["船必须在海岬建造","只能运集装箱","船长一定等于 100 米","大型船历史上难通过部分运河，常绕好望角等航路"],"a":"大型船历史上难通过部分运河，常绕好望角等航路","w":"名称是航线和尺度约束形成的行业语言，不是逐船都必须绕行的法律定义。","pre":"","id":"u02-l02-q02","source":"白皮书 1.4、术语表"},{"k":"tf","q":"两份市场报告给 Kamsarmax 的载重吨边界略有不同，必然有一份错误。","o":["正确","错误"],"a":"错误","w":"尺度名常是市场约定，边界会因机构和年代略有差异。分析时应写明口径并查看具体参数。","pre":"","id":"u02-l02-q03","source":"白皮书 1.4、术语表"},{"k":"multi","q":"判断某干散货船能否服务目标港口，应核对哪些具体参数？","o":["港口水深和泊位限制","尺度昵称是否好听","满载吃水","总长与型宽"],"a":["满载吃水","总长与型宽","港口水深和泊位限制"],"w":"可达性由实际船舶参数与港口限制匹配决定，昵称只能用于初筛。","pre":"","id":"u02-l02-q04","source":"白皮书 1.4、术语表"},{"k":"prod","q":"向小白解释 Handysize 的‘小’为什么不等于‘差’。","model":"它牺牲部分单船规模经济，换来更浅吃水、更广港口覆盖和常见的自装卸能力；在小批量、多港口或基础设施较弱的贸易中，这种灵活性本身有价值。","a":"它牺牲部分单船规模经济，换来更浅吃水、更广港口覆盖和常见的自装卸能力；在小批量、多港口或基础设施较弱的贸易中，这种灵活性本身有价值。","w":"评价船型必须回到任务场景，不能单按吨位排序。","pre":"","id":"u02-l02-q05","source":"白皮书 1.4、术语表"}]},{"t":"集装箱与滚装","goal":"区分箱位经济和滚进滚出逻辑","intro":"集装箱船追求标准箱位和港口周转；滚装船通过坡道装卸有轮货物。两者都重视高效装卸，但货物流组织不同。","keys":["TEU 是箱位口径","Ro-Ro 依赖坡道与甲板","PCTC 专为汽车运输优化"],"trap":"把 TEU 当成重量，或把所有汽车运输都归为普通集装箱。","source":"白皮书 1.5—1.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"TEU 最主要衡量什么？","o":["以 20 英尺标准箱折算的载箱能力","主机功率","船舶总重量","船员人数"],"a":"以 20 英尺标准箱折算的载箱能力","w":"TEU 是标准箱位的容量口径，不直接表示实际货重；装多少重箱还受稳性、吃水等限制。","pre":"","id":"u02-l03-q01","source":"白皮书 1.5—1.6"},{"k":"mc","q":"PCTC 的核心装卸特征是？","o":["汽车经艉门或舷门坡道滚进滚出","原油经泵管输送","矿石经大舱口抓斗装卸","LNG 低温液货舱"],"a":"汽车经艉门或舷门坡道滚进滚出","w":"多层车辆甲板与坡道系统使车辆能自行或被牵引装卸，减少吊装。","pre":"","id":"u02-l03-q02","source":"白皮书 1.5—1.6"},{"k":"tf","q":"一艘标称 10,000 TEU 的船在每次航行中都一定装有 10,000 个箱子。","o":["正确","错误"],"a":"错误","w":"标称容量不是实际装载量。实际箱量和重量受货源、空箱、配载、港口与吃水限制影响。","pre":"","id":"u02-l03-q03","source":"白皮书 1.5—1.6"},{"k":"multi","q":"评估集装箱船实际装载能力时，还应考虑哪些约束？","o":["危险品隔离","只看船名","重量与稳性","冷藏插座数量"],"a":["重量与稳性","冷藏插座数量","危险品隔离"],"w":"名义箱位只是起点；箱重、冷藏箱供电和危险品规则都会让可用箱位与标称容量不同。","pre":"","id":"u02-l03-q04","source":"白皮书 1.5—1.6"},{"k":"prod","q":"比较集装箱船与滚装船的装卸逻辑。","model":"集装箱船依赖标准箱、岸桥和垂直吊装，按箱位组织；滚装船依赖坡道和多层甲板，让车辆水平移动。二者都追求周转，但设备、配载和货损风险不同。","a":"集装箱船依赖标准箱、岸桥和垂直吊装，按箱位组织；滚装船依赖坡道和多层甲板，让车辆水平移动。二者都追求周转，但设备、配载和货损风险不同。","w":"比较题需要同时给出相同目标与不同实现方式。","pre":"","id":"u02-l03-q05","source":"白皮书 1.5—1.6"}]},{"t":"油、化学品与气体","goal":"从温度、压力、腐蚀和污染理解液货船","intro":"原油/成品油、化学品、LPG 和 LNG 看似都装在舱内，技术边界却由货物危险性和储存条件决定。","keys":["油轮靠泵管系统","化学品重视分舱与相容性","LPG/LNG 以压力或低温保持液态"],"trap":"把所有液货船看成同一类油罐。","source":"白皮书 1.7—1.9","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"化学品船常设置较多独立小舱，主要为了什么？","o":["替代主机","分隔不同货物并降低污染与相容性风险","让船看起来更长","增加客房"],"a":"分隔不同货物并降低污染与相容性风险","w":"多分舱配合独立管线和涂层，可同时载运多票货并避免危险反应或交叉污染。","pre":"","id":"u02-l04-q01","source":"白皮书 1.7—1.9"},{"k":"mc","q":"LNG 海运需要特别重视哪一物理条件？","o":["用抓斗卸货","箱位导轨","车辆坡道","极低温储存及蒸发气管理"],"a":"极低温储存及蒸发气管理","w":"天然气通常在约零下 162℃液化，围护系统、绝热和蒸发气处理成为核心。","pre":"","id":"u02-l04-q02","source":"白皮书 1.7—1.9"},{"k":"tf","q":"LPG 船和 LNG 船都运输液化气，因此围护系统、温度和压力设计必然相同。","o":["正确","错误"],"a":"错误","w":"不同气体的液化条件不同，船舶可能采用加压、半冷半压或全冷式等方案，不能只凭‘气体船’归一。","pre":"","id":"u02-l04-q03","source":"白皮书 1.7—1.9"},{"k":"multi","q":"化学品船换货前需要重点检查哪些问题？","o":["舱壁涂层相容性","清洗与检验要求","船员制服颜色","前载货残留"],"a":["前载货残留","舱壁涂层相容性","清洗与检验要求"],"w":"前载货、材料和清洁标准共同决定能否接载，忽略任何一项都可能造成污染或索赔。","pre":"","id":"u02-l04-q04","source":"白皮书 1.7—1.9"},{"k":"prod","q":"用一个因果链解释气体船为什么技术门槛高。","model":"货物需在低温或压力下保持液态，因此需要专用围护、绝热、管路和安全系统；这些系统又提高建造、操作、检验和船员能力要求。","a":"货物需在低温或压力下保持液态，因此需要专用围护、绝热、管路和安全系统；这些系统又提高建造、操作、检验和船员能力要求。","w":"从货物物性推到系统，再推到成本和运营门槛，才是完整机制。","pre":"","id":"u02-l04-q05","source":"白皮书 1.7—1.9"}]},{"t":"单元闯关：货物塑造船","goal":"综合判断船型与尺度适配","intro":"不要凭船名作答。先抓货物状态、批量、港口和装卸，再选船型。","keys":["先判断货物物性","再看港口与设备","最后用具体参数校验"],"trap":"用‘越大越好’替代场景匹配。","source":"白皮书第 1 章综合","kind":"checkpoint","difficulty":2,"q":[{"k":"mc","q":"小批量袋装和散装农产品需要挂靠多个设施较弱港口，首选思路是？","o":["选 LNG 船","只比较最高航速","评估带船吊的小型干散货船","直接选最大矿砂船"],"a":"评估带船吊的小型干散货船","w":"货种属于干货，多港与弱设施强调吃水和自装卸灵活性。","pre":"","id":"u02-l05-q01","source":"白皮书第 1 章综合"},{"k":"mc","q":"同时承运多种高价值液体化学品，最关键的船舶能力是？","o":["开放式货舱","独立分舱、专用管线和相容涂层","最大集装箱舱格","车辆坡道"],"a":"独立分舱、专用管线和相容涂层","w":"不同货物必须隔离，材料相容和清洗能力直接关系安全与货损。","pre":"","id":"u02-l05-q02","source":"白皮书第 1 章综合"},{"k":"tf","q":"船型尺度名足以替代 Q88 或规格表中的实际数据。","o":["正确","错误"],"a":"错误","w":"尺度名只做行业速记。交易、港口适配和收益测算必须落到 DWT、吃水、舱容、设备和性能等具体参数。","pre":"","id":"u02-l05-q03","source":"白皮书第 1 章综合"},{"k":"multi","q":"从‘货物’反推船型时，应连续追问哪些问题？","o":["如何装卸及港口有什么限制","哪种图标最漂亮","是固体、液体还是气体","是否怕污染、温度或压力"],"a":["是固体、液体还是气体","是否怕污染、温度或压力","如何装卸及港口有什么限制"],"w":"这三问分别确定大类、特殊系统和实际可操作性。","pre":"","id":"u02-l05-q04","source":"白皮书第 1 章综合"},{"k":"order","q":"判断目标船舶是否适航某贸易的分析顺序。","o":["识别货物性质与批量","确认装卸方法和港口约束","筛选候选船型与尺度","用实际规格和法规逐项校验"],"a":["识别货物性质与批量","确认装卸方法和港口约束","筛选候选船型与尺度","用实际规格和法规逐项校验"],"w":"由需求到船型、再到逐船核验，可避免让市场昵称替代工程和运营事实。","pre":"","id":"u02-l05-q05","source":"白皮书第 1 章综合"},{"k":"mc","q":"一艘船有很大立方舱容，却未必能多装铁矿石，最可能因为？","o":["重货先触及载重吨或吃水限制","铁矿石没有重量","舱容一定造假","主机无法启动"],"a":"重货先触及载重吨或吃水限制","w":"重货常‘压舱不满舱’，载重和吃水先成为瓶颈；轻货则可能‘满舱不满载’。","pre":"","id":"u02-l05-q06","source":"白皮书第 1 章综合"},{"k":"prod","q":"客户只说‘我要一条大船’，你会怎样把需求变成可选船型？","model":"先问货种及物性、单票批量、装卸港与水深、航线法规、装卸设备和交付时间，再用载重吨、舱容、吃水、设备及性能筛选，而不是直接按船价或尺度名排序。","a":"先问货种及物性、单票批量、装卸港与水深、航线法规、装卸设备和交付时间，再用载重吨、舱容、吃水、设备及性能筛选，而不是直接按船价或尺度名排序。","w":"好的需求澄清要把形容词‘大’改写成可核验约束。","pre":"","id":"u02-l05-q07","source":"白皮书第 1 章综合"},{"k":"mc","q":"本单元最重要的迁移规则是？","o":["外形相似就能互换","船型是货物与运营约束的答案","船型只由船厂命名","吨位越大适合所有贸易"],"a":"船型是货物与运营约束的答案","w":"理解货物、装卸和港口约束后，船型结构不再是孤立记忆，而是因果结果。","pre":"","id":"u02-l05-q08","source":"白皮书第 1 章综合"}]}]},{"id":"u03","t":"船体与海工","s":"剖开船体，也看懂近海作业能力","c":"#3973c6","i":"⚓","guide":"船体结构服务于载货、强度、稳性和作业。海工船更要按任务能力分类，不能只看外观和马力。","outcomes":["辨认主要船体部位及其功能","从舱室系统解释不同货船","按作业任务区分 OSV 与 DP 能力"],"L":[{"t":"散货与集装箱剖面","goal":"理解舱口、货舱、双层底和舱格的作用","intro":"散货船需要承受重货和抓斗作业；集装箱船用导轨和系固把标准箱组织成可快速周转的箱位。","keys":["舱口决定装卸通道","双层底参与强度与压载","舱格导轨约束箱位"],"trap":"看见空舱就只谈容积，忽略局部强度、稳性和装卸载荷。","source":"白皮书 1.10 船体剖面","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"散货船的大舱口最直接服务于什么？","o":["增加船员房间","让抓斗或装船机高效接近货舱","让主机散热","存放救生艇"],"a":"让抓斗或装船机高效接近货舱","w":"散货需要大批量垂直装卸，大舱口提高作业面，但也使舱口围板和甲板强度设计更重要。","pre":"","id":"u03-l01-q01","source":"白皮书 1.10 船体剖面"},{"k":"mc","q":"双层底除了提供部分压载空间，还承担什么作用？","o":["降低卫星通信费","增强船底结构并隔离货舱与外板","替代驾驶台","固定集装箱舱盖"],"a":"增强船底结构并隔离货舱与外板","w":"双层底形成结构梁系并提供缓冲；具体舱柜用途仍需看总布置图。","pre":"","id":"u03-l01-q02","source":"白皮书 1.10 船体剖面"},{"k":"tf","q":"集装箱即使放在宽大甲板上，也必须依靠导轨、扭锁或绑扎系统控制移动。","o":["正确","错误"],"a":"正确","w":"船舶会横摇纵摇，箱体需要由导轨、扭锁、绑扎桥等系统限制移动并传递载荷。","pre":"","id":"u03-l01-q03","source":"白皮书 1.10 船体剖面"},{"k":"multi","q":"散货船配载重货时，除了总重量还要检查什么？","o":["剪力和弯矩","吃水与稳性","公司网站字体","舱段允许载荷"],"a":["舱段允许载荷","剪力和弯矩","吃水与稳性"],"w":"总载重合格不代表局部结构安全，重货分布可能让舱底载荷或船体纵向强度超限。","pre":"","id":"u03-l01-q04","source":"白皮书 1.10 船体剖面"},{"k":"prod","q":"解释‘满舱不满载’与‘满载不满舱’。","model":"轻而蓬松的货物可能先占满舱容却未用完载重吨，叫满舱不满载；铁矿石等重货可能先达到载重或吃水限制而舱容仍有剩余，叫满载不满舱。","a":"轻而蓬松的货物可能先占满舱容却未用完载重吨，叫满舱不满载；铁矿石等重货可能先达到载重或吃水限制而舱容仍有剩余，叫满载不满舱。","w":"需要同时理解容积和重量是两种不同约束。","pre":"","id":"u03-l01-q05","source":"白皮书 1.10 船体剖面"}]},{"t":"油轮与化学品结构","goal":"看懂液货舱、泵舱、管路与涂层","intro":"液货不是简单灌进空舱。分舱、管线、泵、惰性气体和材料相容性共同控制装卸和风险。","keys":["液货靠封闭管泵系统","分舱限制自由液面并隔离货物","材料和涂层必须相容"],"trap":"认为舱容相同就能互换货种。","source":"白皮书 1.10、5.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"油轮货泵的核心任务是？","o":["驱动船舶螺旋桨","吊装集装箱","为船员供水","在装卸和洗舱时输送液货或相关介质"],"a":"在装卸和洗舱时输送液货或相关介质","w":"货泵与货管系统决定液货装卸效率和隔离能力，主推进由主机与推进系统承担。","pre":"","id":"u03-l02-q01","source":"白皮书 1.10、5.4"},{"k":"mc","q":"自由液面对稳性不利，原因是？","o":["液体会固定重心","只影响船速不影响稳性","舱内液体随船倾斜移动，降低有效稳性","液体没有重量"],"a":"舱内液体随船倾斜移动，降低有效稳性","w":"未满舱液体的横向移动产生自由液面修正，因此分舱、装载计划和操作程序很重要。","pre":"","id":"u03-l02-q02","source":"白皮书 1.10、5.4"},{"k":"tf","q":"不锈钢舱或特殊涂层的价值之一，是扩大可安全承运的化学品范围。","o":["正确","错误"],"a":"正确","w":"不同化学品对材料腐蚀和吸附不同，合适的舱壁材料能提高相容性，但仍需逐货种核验。","pre":"","id":"u03-l02-q03","source":"白皮书 1.10、5.4"},{"k":"multi","q":"化学品船货物隔离通常依靠哪些设计或操作？","o":["独立舱柜和管线","阀门隔离","清洗与置换程序","把所有货混在一起"],"a":["独立舱柜和管线","阀门隔离","清洗与置换程序"],"w":"硬件隔离与操作控制共同防止交叉污染和危险反应，任何单项都不是万能屏障。","pre":"","id":"u03-l02-q04","source":"白皮书 1.10、5.4"},{"k":"prod","q":"为什么液货船的‘上一票货’会影响下一票货？","model":"残留物可能污染下一票货、与其发生反应或损伤涂层，所以接货前要核对前载货历史、清洗标准、舱检结果和材料相容性。","a":"残留物可能污染下一票货、与其发生反应或损伤涂层，所以接货前要核对前载货历史、清洗标准、舱检结果和材料相容性。","w":"完整回答应从残留污染和反应风险继续推导到文件核查与操作证据。","pre":"","id":"u03-l02-q05","source":"白皮书 1.10、5.4"}]},{"t":"OSV 任务地图","goal":"按任务区分 PSV、AHTS、潜水和风电支持船","intro":"海工支持船的价值来自作业能力：补给、拖带抛锚、人员转运、海底施工或运维。船型名称要与任务包对应。","keys":["PSV 重甲板与液舱补给","AHTS 重拖带和锚作业","专用船重视设备接口"],"trap":"只比较总吨或航速，不问船要完成什么作业。","source":"白皮书 1.11 OSV","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"海上平台需要运输钻井泥浆、燃油、淡水和甲板货，最典型的船型是？","o":["PSV 平台供应船","超大型油轮","客滚船","矿砂船"],"a":"PSV 平台供应船","w":"PSV 以大开敞甲板和多种专用液舱为平台提供物流补给。","pre":"","id":"u03-l03-q01","source":"白皮书 1.11 OSV"},{"k":"mc","q":"需要拖带海上设施并布放、回收大型锚具时，更应关注？","o":["客舱床位","粮食舱容","AHTS 的系柱拉力、绞车和后甲板设备","集装箱冷藏插座"],"a":"AHTS 的系柱拉力、绞车和后甲板设备","w":"锚作业的瓶颈是拖力、绞车能力、甲板布置和安全控制，不是普通运输吨位。","pre":"","id":"u03-l03-q02","source":"白皮书 1.11 OSV"},{"k":"tf","q":"OSV 作业能力是多维的，必须按任务核对 DP、甲板、起重、拖力及专用系统。","o":["正确","错误"],"a":"正确","w":"海工能力是多维的。DP 等级、甲板、起重、绞车、系柱拉力、人员与专用系统必须按任务逐项匹配。","pre":"","id":"u03-l03-q03","source":"白皮书 1.11 OSV"},{"k":"multi","q":"为海上风电运维选船时，可能要重点核对哪些能力？","o":["起重或步桥接口","是否能装原油百万吨","人员安全转运","动态定位"],"a":["人员安全转运","动态定位","起重或步桥接口"],"w":"风电运维围绕人员、备件和靠近固定设施的安全作业，能力组合比单一吨位重要。","pre":"","id":"u03-l03-q04","source":"白皮书 1.11 OSV"},{"k":"prod","q":"客户说‘找一条海工船’，请列出四个必要追问。","model":"至少问：具体作业包是什么、作业海域和海况、需要的 DP/拖力/起重等能力、人员与甲板或舱容需求；再问法规、工期和接口标准。","a":"至少问：具体作业包是什么、作业海域和海况、需要的 DP/拖力/起重等能力、人员与甲板或舱容需求；再问法规、工期和接口标准。","w":"OSV 选型必须从任务包倒推能力矩阵。","pre":"","id":"u03-l03-q05","source":"白皮书 1.11 OSV"}]},{"t":"DP 与系柱拉力","goal":"理解动态定位冗余和拖带能力的边界","intro":"DP 用传感器、控制器、推进器和电力系统保持位置；系柱拉力衡量持续拖力。两者描述不同能力。","keys":["DP 等级关注单点故障后能否维持位置","Bollard Pull 是拖力不是航速","环境包络决定实际能力"],"trap":"看见 DP2 就认为任何海况都绝对不会失位。","source":"白皮书 1.11、术语表","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"DP2 相比 DP1 最核心的思路是？","o":["船一定更长","无需船员","航速翻倍","通过冗余避免单一故障立即导致失位"],"a":"通过冗余避免单一故障立即导致失位","w":"DP2 的系统分隔和冗余目标是单一故障后维持位置，但实际能力仍受故障模式和环境条件约束。","pre":"","id":"u03-l04-q01","source":"白皮书 1.11、术语表"},{"k":"mc","q":"系柱拉力 120 吨主要说明什么？","o":["航速为 120 节","船在规定测试条件下可持续施加的拖力水平","船可装 120 吨货","船总吨为 120"],"a":"船在规定测试条件下可持续施加的拖力水平","w":"Bollard Pull 是拖船和 AHTS 的关键作业指标，不是载货量、登记吨位或速度。","pre":"","id":"u03-l04-q02","source":"白皮书 1.11、术语表"},{"k":"tf","q":"两条船都是 DP2，因此在同一海况下的持位能力必然相同。","o":["正确","错误"],"a":"错误","w":"推进器配置、电力余度、受风面积、传感器和作业吃水等不同，会形成不同的 DP 能力包络。","pre":"","id":"u03-l04-q03","source":"白皮书 1.11、术语表"},{"k":"multi","q":"评估 DP 作业风险时应同时查看哪些信息？","o":["FMEA 与试验记录","推进和电力冗余","天气海况限制","只看证书封面"],"a":["FMEA 与试验记录","推进和电力冗余","天气海况限制"],"w":"等级证书是入口，故障模式、设备状态和环境限制才决定具体任务能否安全完成。","pre":"","id":"u03-l04-q04","source":"白皮书 1.11、术语表"},{"k":"prod","q":"向客户解释为什么 DP 等级和系柱拉力不能互相替代。","model":"DP 描述船舶在环境力下主动保持位置的系统与冗余；系柱拉力描述持续拖带输出。一个是定位控制能力，一个是拖力，任务、设备和测试口径不同。","a":"DP 描述船舶在环境力下主动保持位置的系统与冗余；系柱拉力描述持续拖带输出。一个是定位控制能力，一个是拖力，任务、设备和测试口径不同。","w":"回答要抓住‘持位’与‘拖带’的功能差异。","pre":"","id":"u03-l04-q05","source":"白皮书 1.11、术语表"}]},{"t":"单元闯关：结构服务任务","goal":"用结构与能力解释船的适用边界","intro":"从任务出发，指出结构为什么存在、参数为什么重要，并识别证书与实际能力之间的距离。","keys":["货物决定舱室","任务决定设备","证书之后仍要核验状态与边界"],"trap":"用单一标签替代能力矩阵。","source":"白皮书第 1 章结构与海工综合","kind":"checkpoint","difficulty":2,"q":[{"k":"mc","q":"同样是运输液体，化学品船比普通油轮更常见哪项设计？","o":["更多独立小舱和专用隔离","更大的集装箱导轨","车辆坡道","开放货舱"],"a":"更多独立小舱和专用隔离","w":"多票、敏感或危险货要求更精细的相容性和污染控制。","pre":"","id":"u03-l05-q01","source":"白皮书第 1 章结构与海工综合"},{"k":"mc","q":"矿石装载总吨位未超 DWT，却导致某货舱舱底超载。说明什么？","o":["DWT 没有意义","矿石没有密度","船必须改名","总量合格不代表局部结构载荷合格"],"a":"总量合格不代表局部结构载荷合格","w":"配载还必须满足舱段载荷和船体纵向强度限制。","pre":"","id":"u03-l05-q02","source":"白皮书第 1 章结构与海工综合"},{"k":"tf","q":"OSV 的船型标签只能用于初筛，最终还应做任务—能力逐项匹配。","o":["正确","错误"],"a":"正确","w":"同类 OSV 的设备和等级差异很大，只有能力矩阵能支持具体作业判断。","pre":"","id":"u03-l05-q03","source":"白皮书第 1 章结构与海工综合"},{"k":"multi","q":"一项近平台 DP 作业的 Go/No-Go 判断应纳入哪些层面？","o":["系统证书和维护状态","FMEA 对应故障模式","天气与作业限制","船长和作业团队程序"],"a":["系统证书和维护状态","FMEA 对应故障模式","天气与作业限制","船长和作业团队程序"],"w":"技术、环境和人员程序共同形成安全屏障，单张证书不能覆盖全部。","pre":"","id":"u03-l05-q04","source":"白皮书第 1 章结构与海工综合"},{"k":"order","q":"把 OSV 选型步骤排成合理顺序。","o":["定义具体作业和环境","把任务拆成能力指标","筛船并核对证书与设备","评估状态、人员和实际作业边界"],"a":["定义具体作业和环境","把任务拆成能力指标","筛船并核对证书与设备","评估状态、人员和实际作业边界"],"w":"先定义任务，再量化能力，之后筛船和做现场层面的适用性审查。","pre":"","id":"u03-l05-q05","source":"白皮书第 1 章结构与海工综合"},{"k":"mc","q":"一艘 DP2 船证书有效，但一台关键推进器长期停用。最稳健结论是？","o":["证书有效所以无影响","直接按 DP3 使用","只降低租金即可","重新核验冗余、能力包络和任务可行性"],"a":"重新核验冗余、能力包络和任务可行性","w":"设备不可用可能改变故障后果和持位能力，必须回到实际配置与任务条件。","pre":"","id":"u03-l05-q06","source":"白皮书第 1 章结构与海工综合"},{"k":"prod","q":"用一个共同框架解释货船和海工船的选型。","model":"先定义货物或作业任务，再识别环境与港口约束，把需求翻译成舱室、设备、性能和合规指标，最后用具体船舶状态逐项核验。","a":"先定义货物或作业任务，再识别环境与港口约束，把需求翻译成舱室、设备、性能和合规指标，最后用具体船舶状态逐项核验。","w":"共同方法是从需求反推能力，而非从船名正推用途。","pre":"","id":"u03-l05-q07","source":"白皮书第 1 章结构与海工综合"},{"k":"mc","q":"本单元判断结构的核心问题是？","o":["它有多少照片","它是否由知名船厂建造","它在解决哪一种货物或作业风险","它看起来是否复杂"],"a":"它在解决哪一种货物或作业风险","w":"结构和设备不是装饰；把它们对应到载荷、污染、稳性、持位或拖带风险，才能真正理解。","pre":"","id":"u03-l05-q08","source":"白皮书第 1 章结构与海工综合"}]}]},{"id":"u04","t":"参数与吨位","s":"把规格表翻译成收入、成本和限制","c":"#ef7d32","i":"📐","guide":"同一个‘吨’可能是重量、容量或计费口径。参数分析必须先确认定义，再问它影响装货、港口、成本还是合规。","outcomes":["区分尺寸、吃水和六类吨位口径","把参数连接到经济性与港口适配","发现规格表中的口径陷阱"],"L":[{"t":"尺寸与吃水","goal":"理解 LOA、LBP、型宽、型深和吃水","intro":"船长宽深描述几何边界，吃水描述船体浸水深度。港口、运河、船闸和装载状态会把这些参数变成硬约束。","keys":["LOA 用于泊位与操纵","型宽影响船闸和稳性","吃水随装载和水密度变化"],"trap":"把型深当成吃水，或用设计吃水替代任何港口状态。","source":"白皮书 2.1","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"港口公布最大允许吃水 13.0 米，船舶到港预计吃水 13.3 米。首先意味着？","o":["需要减载、等潮或另做可行安排","船长一定超限","总吨会自动下降","无需处理"],"a":"需要减载、等潮或另做可行安排","w":"吃水是水下深度约束，超限可能触底；应结合潮汐、水密度、富余水深和港规评估。","pre":"","id":"u04-l01-q01","source":"白皮书 2.1"},{"k":"mc","q":"LOA 对哪项判断最直接？","o":["泊位长度和靠离泊空间是否足够","货物化学相容性","船员证书","贷款利率"],"a":"泊位长度和靠离泊空间是否足够","w":"总长是船首到船尾最大长度，常用于泊位、船闸和操纵空间校验。","pre":"","id":"u04-l01-q02","source":"白皮书 2.1"},{"k":"tf","q":"同一艘船承载相同重量时，在淡水中的吃水通常比海水更深。","o":["正确","错误"],"a":"正确","w":"淡水密度较低，船需排开更大体积才能产生同等浮力，因此通常吃水更深。","pre":"","id":"u04-l01-q03","source":"白皮书 2.1"},{"k":"multi","q":"做港口适配时，除吃水外还常需核对？","o":["水面以上高度或气隙","船名字符数","总长","型宽"],"a":["总长","型宽","水面以上高度或气隙"],"w":"泊位、航道、船闸与桥梁分别可能限制长、宽、吃水和气隙。","pre":"","id":"u04-l01-q04","source":"白皮书 2.1"},{"k":"prod","q":"解释为什么‘设计吃水’不是每次航次的固定值。","model":"吃水随货物、燃油、淡水、压载和水密度变化；设计吃水是设计或性能口径，不等于某一时刻的实测吃水，航次判断要看装载计算和港口条件。","a":"吃水随货物、燃油、淡水、压载和水密度变化；设计吃水是设计或性能口径，不等于某一时刻的实测吃水，航次判断要看装载计算和港口条件。","w":"答案必须区分设计参数和实时运营状态，并指出装载与水密度会改变实测值。","pre":"","id":"u04-l01-q05","source":"白皮书 2.1"}]},{"t":"DWT 与排水量","goal":"分清船能带多少和船加船上全部重量","intro":"排水量等于船在该状态下排开水的重量；DWT 是从轻载到规定载重状态可承载的货物、燃油、淡水、备品和人员等总和。","keys":["Displacement 包含船本身","DWT 不是纯货量","轻载排水量影响载重能力"],"trap":"把 DWT 直接当成每航次可装货吨数。","source":"白皮书 2.2","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"一艘 50,000 DWT 船的 DWT 最准确表示？","o":["年运量","规定状态下可承载的货物及消耗品等总重量能力","船体钢材重量","内部容积"],"a":"规定状态下可承载的货物及消耗品等总重量能力","w":"DWT 包含货物、燃油、淡水、备品和人员等，实际货量要扣除非货载荷并满足吃水。","pre":"","id":"u04-l02-q01","source":"白皮书 2.2"},{"k":"mc","q":"同一装载状态下，排水量包含什么？","o":["只含船员","空船重量与船上全部载荷","只含货物","只含燃油"],"a":"空船重量与船上全部载荷","w":"阿基米德原理使排水重量等于船舶该时刻总重量。","pre":"","id":"u04-l02-q02","source":"白皮书 2.2"},{"k":"tf","q":"两艘船 DWT 相同，实际可装货量和经济性就一定相同。","o":["正确","错误"],"a":"错误","w":"轻载重量、舱容、吃水、油耗、航速、设备和港口适配仍可能显著不同。","pre":"","id":"u04-l02-q03","source":"白皮书 2.2"},{"k":"multi","q":"从 DWT 推实际货量时，通常要扣除哪些非货重量？","o":["公司注册资本","燃油和润滑油","淡水和备品","船员及行李"],"a":["燃油和润滑油","淡水和备品","船员及行李"],"w":"这些都占用载重能力；航次长度和补给策略会改变可留给货物的重量。","pre":"","id":"u04-l02-q04","source":"白皮书 2.2"},{"k":"num","q":"某船 DWT 为 40,000 吨，预计燃油、淡水、备品等合计 2,200 吨。暂不考虑其他限制，货物重量上限约为？","o":["40,000 吨","42,200 吨","2,200 吨","37,800 吨"],"a":"37,800 吨","w":"教学简化计算为 40,000－2,200＝37,800 吨；实际还需考虑吃水、稳性、舱容和安全余量。","pre":"","id":"u04-l02-q05","source":"白皮书 2.2"}]},{"t":"GT、NT 与运河口径","goal":"识别容积型登记和收费吨位","intro":"GT/NT 是按公约公式由封闭空间推导的无量纲登记数；苏伊士、巴拿马等可能采用自己的计费容积口径。","keys":["GT 不是重量","NT 近似反映营运空间但不是货重","收费前要确认具体口径"],"trap":"看到‘吨’字就把所有数相加或互相换算。","source":"白皮书 2.3—2.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"总吨 GT 最接近哪类概念？","o":["由船舶封闭容积按规则计算的登记尺度","船舶实际重量","最大载货重量","主机马力"],"a":"由船舶封闭容积按规则计算的登记尺度","w":"GT 是无量纲数，常用于法规、配员和收费分级，不是重量吨。","pre":"","id":"u04-l03-q01","source":"白皮书 2.3—2.4"},{"k":"mc","q":"为什么过运河成本不能只拿 GT 乘一个通用费率？","o":["运河不收费","船价决定全部费用","运河可能有专用吨位口径和附加收费规则","GT 永远为零"],"a":"运河可能有专用吨位口径和附加收费规则","w":"SCNT、PC/UMS 等口径及预约、安保、拥堵等规则会影响账单，应按当期官方规则测算。","pre":"","id":"u04-l03-q02","source":"白皮书 2.3—2.4"},{"k":"tf","q":"GT 是基于封闭容积计算的登记尺度，不应写成公吨重量。","o":["正确","错误"],"a":"正确","w":"GT 名称虽含 tonnage，却是基于容积的登记数，没有公吨单位。","pre":"","id":"u04-l03-q03","source":"白皮书 2.3—2.4"},{"k":"multi","q":"哪些业务可能直接引用 GT 或 NT？","o":["港口或登记收费","安全法规适用门槛","配员与证书分级","确定铁矿石密度"],"a":["港口或登记收费","安全法规适用门槛","配员与证书分级"],"w":"登记吨位常用于行政与收费门槛，不用于描述货物材料性质。","pre":"","id":"u04-l03-q04","source":"白皮书 2.3—2.4"},{"k":"prod","q":"用一句不带公式的话区分 DWT 与 GT。","model":"DWT 问船在规定状态下还能带多少重量，GT 问船有多大的封闭空间登记尺度；前者连接装载，后者更多连接法规和收费。","a":"DWT 问船在规定状态下还能带多少重量，GT 问船有多大的封闭空间登记尺度；前者连接装载，后者更多连接法规和收费。","w":"关键是把重量承载能力和容积登记尺度分成两个维度，并分别连接装载与收费。","pre":"","id":"u04-l03-q05","source":"白皮书 2.3—2.4"}]},{"t":"性能、船龄与状态","goal":"把航速油耗、船级和 CII 放进同一判断","intro":"规格表是理想或约定口径，真实表现受吃水、天气、污底、维护和操作影响。船龄也必须与状态、检验和改造一起看。","keys":["航速油耗必须成对并写条件","船龄不是技术状态的替代变量","CII 是运营碳强度信号"],"trap":"用单一海试数字外推所有航次，或认为年轻船必然更优。","source":"白皮书 2.5—2.7、5.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"比较两艘船油耗时，最重要的前提是？","o":["尽量统一航速、吃水、天气和计量口径","只看数值谁小","忽略辅机","只比较船名"],"a":"尽量统一航速、吃水、天气和计量口径","w":"油耗与航速、载况和环境高度相关，口径不同的数字无法直接排序。","pre":"","id":"u04-l04-q01","source":"白皮书 2.5—2.7、5.6"},{"k":"mc","q":"一艘老船仍可能具有投资价值，前提更接近？","o":["无需坞修","保险一定更便宜","价格充分反映状态，且检验、维修和合规支出可控","船龄越大航速越快"],"a":"价格充分反映状态，且检验、维修和合规支出可控","w":"年龄影响风险概率，但决策要把技术状态、未来资本开支、租约和残值共同量化。","pre":"","id":"u04-l04-q02","source":"白皮书 2.5—2.7、5.6"},{"k":"tf","q":"CII 评级只由船舶设计决定，与实际航行和运输工作量无关。","o":["正确","错误"],"a":"错误","w":"CII 是年度运营碳强度指标，会受燃油消耗、航程、运量和运营方式影响。","pre":"","id":"u04-l04-q03","source":"白皮书 2.5—2.7、5.6"},{"k":"multi","q":"判断船舶当前技术健康度可查看哪些证据？","o":["近期维修和故障记录","坞检/测厚报告","单张宣传海报","船级状态与检验到期"],"a":["船级状态与检验到期","近期维修和故障记录","坞检/测厚报告"],"w":"证书、历史和实船检验需要互相印证，单一展示材料不够。","pre":"","id":"u04-l04-q04","source":"白皮书 2.5—2.7、5.6"},{"k":"prod","q":"解释为什么‘14 节、每天 25 吨’不是完整性能承诺。","model":"还要写明载况、天气海况、燃油品质、主辅机范围、容差、测量周期和良好天气定义；否则无法判断何时构成性能不足或如何索赔。","a":"还要写明载况、天气海况、燃油品质、主辅机范围、容差、测量周期和良好天气定义；否则无法判断何时构成性能不足或如何索赔。","w":"性能数字只有放进明确的适用条件、测量方法和违约救济后，才成为可执行承诺。","pre":"","id":"u04-l04-q05","source":"白皮书 2.5—2.7、5.6"}]},{"t":"单元闯关：数字就是限制","goal":"综合翻译规格表和识别口径错误","intro":"每见一个数字先问：单位是什么、状态是什么、数据从哪来、它会影响哪条现金流或约束。","keys":["定义先于计算","参数要与状态绑定","同口径才可比较"],"trap":"对数字有精确感，却没有定义感。","source":"白皮书第 2 章综合","kind":"checkpoint","difficulty":2,"q":[{"k":"mc","q":"报告称‘该船吨位 30,000’，最专业的第一反应是？","o":["追问是 DWT、GT、排水量还是其他口径","直接认定载货 30,000 吨","直接认定总重","把它除以航速"],"a":"追问是 DWT、GT、排水量还是其他口径","w":"‘吨位’在航运中高度歧义，任何计算前都要锁定定义和状态。","pre":"","id":"u04-l05-q01","source":"白皮书第 2 章综合"},{"k":"num","q":"教学情景：60,000 DWT 船非货重量预计 3,500 吨，港口限制又要求减载 1,000 吨。简化货量上限约？","o":["56,500 吨","59,000 吨","64,500 吨","55,500 吨"],"a":"55,500 吨","w":"60,000－3,500－1,000＝55,500 吨。这只是量级判断，正式配载还受舱容、稳性和强度约束。","pre":"","id":"u04-l05-q02","source":"白皮书第 2 章综合"},{"k":"tf","q":"若港口按 GT 收费，降低本航次货量就会让船舶证书上的 GT 自动下降。","o":["正确","错误"],"a":"错误","w":"GT 是船舶登记尺度，不随每航次装货量变化；减载会改变吃水和排水量。","pre":"","id":"u04-l05-q03","source":"白皮书第 2 章综合"},{"k":"multi","q":"一项性能对比要可信，应披露哪些共同条件？","o":["燃油及计量边界","样本期与数据来源","航速和载况","天气海况"],"a":["航速和载况","天气海况","燃油及计量边界","样本期与数据来源"],"w":"四项共同决定数字是否可比，缺少条件的‘精确数字’可能比区间更误导。","pre":"","id":"u04-l05-q04","source":"白皮书第 2 章综合"},{"k":"order","q":"把陌生规格参数转成决策信息的步骤排序。","o":["确认定义、单位和状态","核对证书或原始数据来源","映射到港口、货量、成本或合规","用同口径情景做比较和压力测试"],"a":["确认定义、单位和状态","核对证书或原始数据来源","映射到港口、货量、成本或合规","用同口径情景做比较和压力测试"],"w":"先定义和验证，再解释影响，最后比较情景，是避免吨位误读的稳定流程。","pre":"","id":"u04-l05-q05","source":"白皮书第 2 章综合"},{"k":"mc","q":"两船 DWT 相同，A 船轻载更重。其他条件相近时可能意味着？","o":["A 一定更新","A 不需燃油","A 可用于货物和消耗品的载重分配更受挤压","A 的 GT 必为零"],"a":"A 可用于货物和消耗品的载重分配更受挤压","w":"DWT 已是可承载差额，轻载重往往反映结构或设备更多；具体经济性仍需结合舱容性能。","pre":"","id":"u04-l05-q06","source":"白皮书第 2 章综合"},{"k":"prod","q":"拿到 Vessel Particulars 后，给出一套四问检查法。","model":"问定义：每个吨位和性能口径是什么；问状态：在何种吃水、航速和环境下；问证据：来自证书、海试还是运营数据；问影响：它限制货量、港口、费用、租金还是合规。","a":"问定义：每个吨位和性能口径是什么；问状态：在何种吃水、航速和环境下；问证据：来自证书、海试还是运营数据；问影响：它限制货量、港口、费用、租金还是合规。","w":"四问把参数从静态表格转成可审计的业务判断。","pre":"","id":"u04-l05-q07","source":"白皮书第 2 章综合"},{"k":"mc","q":"参数分析的终点不是记数字，而是？","o":["把所有吨位相加","只做漂亮图表","说明数字改变了什么可行性、现金流或风险","收集尽可能多缩写"],"a":"说明数字改变了什么可行性、现金流或风险","w":"参数只有连接到装载、港口、合同、成本或法规时才成为决策信息。","pre":"","id":"u04-l05-q08","source":"白皮书第 2 章综合"}]}]},{"id":"u05","t":"租约责任","s":"先问谁控制，再问谁付哪一笔钱","c":"#8854d0","i":"🤝","guide":"TC、VC、BBC 不是三个缩写，而是三套控制权和成本分配。所有收益分析都应先标注租约结构。","outcomes":["比较三类租约的控制权与成本责任","把收入形式与对应成本配对","根据商业目的选择租约结构"],"L":[{"t":"TC、VC 与 BBC","goal":"抓住时间、航次和光船三种交易对象","intro":"期租购买一段时间的运力，航次租购买一次或一组货运服务，光租取得近似占有式的船舶使用。","keys":["TC 按时间付 hire","VC 按货量或包干付 freight","BBC 转移更多营运责任"],"trap":"用付款频率判断租约，而不看谁控制航次和承担成本。","source":"白皮书 4.1","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"租家希望未来一年自行安排多个航次，船东保留技术管理。最贴近哪种结构？","o":["光船租 BBC","船舶买卖","期租 TC","单航次租 VC"],"a":"期租 TC","w":"TC 让租家在约定范围内调度商业使用，船东通常继续负责配员、维修和保险。","pre":"","id":"u05-l01-q01","source":"白皮书 4.1"},{"k":"mc","q":"货主只需要把 50,000 吨煤从 A 港运到 B 港，最直接对应？","o":["船舶抵押","航次租 VC","长期光船租","造船合同"],"a":"航次租 VC","w":"VC 的交易对象是一项具体货运服务，船东通常负责航行和燃油等航次执行。","pre":"","id":"u05-l01-q02","source":"白皮书 4.1"},{"k":"tf","q":"BBC 下承租人通常承担比 TC 租家更多的配员、维修和保险责任。","o":["正确","错误"],"a":"正确","w":"光租接近把船壳交给承租人运营，承租人常接管船员、技术和运营成本，具体仍以条款为准。","pre":"","id":"u05-l01-q03","source":"白皮书 4.1"},{"k":"multi","q":"判断陌生租约属于哪一类，可以先看哪些线索？","o":["收入按时间还是航次","谁提供船员和技术管理","谁付燃油与港费","合同封面颜色"],"a":["收入按时间还是航次","谁提供船员和技术管理","谁付燃油与港费"],"w":"付款逻辑、管理责任和航次成本分配共同指向租约本质。","pre":"","id":"u05-l01-q04","source":"白皮书 4.1"},{"k":"prod","q":"用一句话分别概括 TC、VC、BBC 买的是什么。","model":"TC 买一段时间的可用运力，VC 买一项特定货运结果，BBC 买一段时间内对裸船的高度占有和运营控制。","a":"TC 买一段时间的可用运力，VC 买一项特定货运结果，BBC 买一段时间内对裸船的高度占有和运营控制。","w":"答案要落到交易对象，而不是只展开缩写。","pre":"","id":"u05-l01-q05","source":"白皮书 4.1"}]},{"t":"成本责任表","goal":"把 OPEX、燃油、港费和航次成本贴回责任方","intro":"通常 TC 船东负 OPEX、租家负燃油港费；VC 船东覆盖大部分船舶及航次成本；BBC 承租人承担大部分营运成本。","keys":["通常不等于永远","费用责任要与控制权匹配","例外必须回到条款"],"trap":"背完责任表就不看合同中的特别约定。","source":"白皮书 4.2","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"在典型 TC 中，主机日常维修成本通常由谁承担？","o":["船东","期租租家","收货人","港口"],"a":"船东","w":"TC 船东保留技术管理并收取 hire，因此通常承担船员、维修、保险等 OPEX。","pre":"","id":"u05-l02-q01","source":"白皮书 4.2"},{"k":"mc","q":"在典型 VC 中，航次燃油价格上涨首先侵蚀谁的航次利润？","o":["登记机关","船东","货主的船员","船级社"],"a":"船东","w":"VC 船东收 freight 并执行航次，通常承担燃油和港费；合同附加条款可能另行分配。","pre":"","id":"u05-l02-q02","source":"白皮书 4.2"},{"k":"tf","q":"TC 下租家通常支付燃油，因此节速和航线安排对租家经济性很重要。","o":["正确","错误"],"a":"正确","w":"租家承担航次费用时会关注燃油、港费和时间，但指示不得违反安全与合同限制。","pre":"","id":"u05-l02-q03","source":"白皮书 4.2"},{"k":"multi","q":"典型 BBC 承租人常承担哪些成本？","o":["日常燃油","船员","维修保养","船舶保险"],"a":["船员","维修保养","船舶保险","日常燃油"],"w":"光租把大部分运营控制和成本转给承租人，船东更多保留资产和融资端责任。","pre":"","id":"u05-l02-q04","source":"白皮书 4.2"},{"k":"prod","q":"为什么责任表只能是分析起点，不能替代租约？","model":"行业惯例提供默认预期，但租约可以通过附加条款改变燃油、港费、维修、保险和停租责任；最终现金流必须按已签文本逐条建模。","a":"行业惯例提供默认预期，但租约可以通过附加条款改变燃油、港费、维修、保险和停租责任；最终现金流必须按已签文本逐条建模。","w":"答出‘惯例—例外—文本优先’三层即可。","pre":"","id":"u05-l02-q05","source":"白皮书 4.2"}]},{"t":"控制权与指示","goal":"区分商业指示、航海安全和技术管理","intro":"租家可以拥有商业调度权，却不能迫使船长实施不安全或非法指示。船长和船东保留安全与适航责任。","keys":["合法且安全的指示才可执行","船长对航海安全负责","控制权越强，成本和风险通常越多"],"trap":"把商业控制理解为对船长的无限命令权。","source":"白皮书 4.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"TC 租家要求驶入不安全港口。船东最合理的态度是？","o":["由船级社决定运费","依据安全港条款和事实评估并保留拒绝权","任何指示都必须执行","直接卖船"],"a":"依据安全港条款和事实评估并保留拒绝权","w":"商业指示受租约、安全港保证、制裁和航海安全约束，不能因租家付油费就无限扩张。","pre":"","id":"u05-l03-q01","source":"白皮书 4.3"},{"k":"mc","q":"谁对船舶即时航海操纵拥有专业权威？","o":["货主销售","保险经纪","船长","租家财务经理"],"a":"船长","w":"船长要结合安全、法规和船况执行或拒绝具体航行操作，但合同后果仍需另行分析。","pre":"","id":"u05-l03-q02","source":"白皮书 4.3"},{"k":"tf","q":"期租租家能指定合法航线和货物，因此也自动负责船体结构维护。","o":["正确","错误"],"a":"错误","w":"商业调度和技术管理是两套职能。TC 中技术维护通常仍由船东承担。","pre":"","id":"u05-l03-q03","source":"白皮书 4.3"},{"k":"multi","q":"收到租家航次指示后，船东或船长应核查哪些边界？","o":["货物合法和适装","制裁与保险覆盖","船舶性能和吃水","港口与泊位安全"],"a":["港口与泊位安全","货物合法和适装","制裁与保险覆盖","船舶性能和吃水"],"w":"合同指示必须同时过安全、合规、保险和能力四道门。","pre":"","id":"u05-l03-q04","source":"白皮书 4.3"},{"k":"prod","q":"解释‘商业上由租家用船，航海上仍由船长负责’。","model":"租家决定在租约范围内去哪里、装什么和何时经营；船长判断具体航行、配载和操作是否安全合法。两者分工，发生冲突时需依据租约和事实处理。","a":"租家决定在租约范围内去哪里、装什么和何时经营；船长判断具体航行、配载和操作是否安全合法。两者分工，发生冲突时需依据租约和事实处理。","w":"不能把商业选择和专业安全职责混成一层。","pre":"","id":"u05-l03-q05","source":"白皮书 4.3"}]},{"t":"怎样选择结构","goal":"根据风险偏好、能力和市场观点匹配租约","intro":"锁定收入、保留市场敞口、控制船舶或减少运营负担，分别会推向不同租约安排。","keys":["固定期限降低收入波动但牺牲上行","VC 保留航次利润也承担波动","BBC 对承租人能力要求高"],"trap":"只追最高名义租金，不看成本、信用和灵活性。","source":"白皮书 4.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"船东希望未来三年现金流较稳定、降低现货运价波动，可能优先考虑？","o":["拆船","有信用支持的中长期 TC","每航次现货 VC","不签任何合同"],"a":"有信用支持的中长期 TC","w":"期限租约能锁定一部分日租收入，但还要评估租家信用、停租和市场上行机会成本。","pre":"","id":"u05-l04-q01","source":"白皮书 4.4"},{"k":"mc","q":"一家公司缺乏技术船管能力，却想长期掌控裸船运营。最大的前置问题是？","o":["是否有能力承担 BBC 下配员、维修、保险和合规","船名是否漂亮","GT 是否等于 DWT","运河是否免费"],"a":"是否有能力承担 BBC 下配员、维修、保险和合规","w":"BBC 转移的是一整套运营责任，不只是便宜地获得船舶使用权。","pre":"","id":"u05-l04-q02","source":"白皮书 4.4"},{"k":"tf","q":"固定租金越高，租约就一定越好，不必考虑租家信用。","o":["正确","错误"],"a":"错误","w":"名义价格只有在能按时收回时才有价值。信用、担保、押金、违约救济和再出租能力都影响真实收益。","pre":"","id":"u05-l04-q03","source":"白皮书 4.4"},{"k":"multi","q":"船东比较两份 TC 报价时，应同时比较？","o":["停租、还船及航区条款","净租金和佣金","租期与选择权","租家信用和担保"],"a":["净租金和佣金","租期与选择权","租家信用和担保","停租、还船及航区条款"],"w":"价格、期限、信用和风险条款共同决定期租价值，不能只按 headline rate 排序。","pre":"","id":"u05-l04-q04","source":"白皮书 4.4"},{"k":"prod","q":"市场可能上涨时，为什么船东仍可能接受长期 TC？","model":"长期 TC 可提高现金流可见性、支持融资和覆盖固定成本；船东用部分上行换取下行保护。是否值得取决于价格、信用、杠杆和风险承受力。","a":"长期 TC 可提高现金流可见性、支持融资和覆盖固定成本；船东用部分上行换取下行保护。是否值得取决于价格、信用、杠杆和风险承受力。","w":"关键是把租约看成风险配置，不是对行情的单一投票。","pre":"","id":"u05-l04-q05","source":"白皮书 4.4"}]},{"t":"单元闯关：谁付这笔钱","goal":"综合拆解租约、控制与现金流","intro":"先定结构，再对收入、OPEX、航次成本和风险逐项标注。遇到例外回到合同。","keys":["结构先于测算","权利与成本成对","信用决定名义收入能否兑现"],"trap":"不写假设就直接算净收益。","source":"白皮书第 4 章租约基础综合","kind":"checkpoint","difficulty":2,"q":[{"k":"mc","q":"船东收固定日租，租家安排航次并买燃油，最可能是？","o":["S&P","造船合同","TC","VC"],"a":"TC","w":"按日收 hire、租家承担商业航次与燃油是典型期租组合。","pre":"","id":"u05-l05-q01","source":"白皮书第 4 章租约基础综合"},{"k":"mc","q":"船东收每吨运费并承担燃油港费，最可能是？","o":["抵押贷款","船管协议","VC","BBC"],"a":"VC","w":"航次租按运输结果收 freight，船东通常负责执行航次成本。","pre":"","id":"u05-l05-q02","source":"白皮书第 4 章租约基础综合"},{"k":"tf","q":"同一条船在不同租约下，船东的 TCE 和风险暴露可以完全不同。","o":["正确","错误"],"a":"正确","w":"资产没变，但收入形式、燃油和港费责任、停租及市场敞口会随合同改变。","pre":"","id":"u05-l05-q03","source":"白皮书第 4 章租约基础综合"},{"k":"multi","q":"期租租家发布装货指示前需考虑？","o":["安全港与吃水","制裁和保险","租期是否足够完成航次","租约允许的货种"],"a":["租约允许的货种","安全港与吃水","制裁和保险","租期是否足够完成航次"],"w":"合法、可操作、可保险和时间可完成是四条独立边界。","pre":"","id":"u05-l05-q04","source":"白皮书第 4 章租约基础综合"},{"k":"order","q":"分析一份租约经济性的顺序。","o":["确认租约类型和期限","逐项分配收入、OPEX 与航次成本","加入停租、佣金和信用情景","计算净现金流并做压力测试"],"a":["确认租约类型和期限","逐项分配收入、OPEX 与航次成本","加入停租、佣金和信用情景","计算净现金流并做压力测试"],"w":"合同结构决定模型边界，之后才有可比的净收益。","pre":"","id":"u05-l05-q05","source":"白皮书第 4 章租约基础综合"},{"k":"num","q":"教学情景：TC 日租 18,000 美元，佣金 5%。船东每日毛租金扣佣后约为？","o":["900 美元","17,100 美元","18,900 美元","13,000 美元"],"a":"17,100 美元","w":"18,000×(1－5%)＝17,100。之后还要扣船东 OPEX、管理费和停租影响。","pre":"","id":"u05-l05-q06","source":"白皮书第 4 章租约基础综合"},{"k":"prod","q":"看到‘日租 2 万美元’，你会补哪四个限定词？","model":"至少补：哪种租约、毛租还是净租、租期与交还范围、佣金与停租条款；还应补租家信用和成本责任，才能进入收益比较。","a":"至少补：哪种租约、毛租还是净租、租期与交还范围、佣金与停租条款；还应补租家信用和成本责任，才能进入收益比较。","w":"任何价格都必须带上租约、期限、费用与风险口径，否则不能进入净收益比较。","pre":"","id":"u05-l05-q07","source":"白皮书第 4 章租约基础综合"},{"k":"mc","q":"本单元最重要的动作是？","o":["画一张谁控制、谁收钱、谁付成本的责任表","背所有合同缩写","只找最高报价","默认所有费用由船东付"],"a":"画一张谁控制、谁收钱、谁付成本的责任表","w":"责任表把抽象租约翻译为现金流和风险，是后续 TCE、融资和投资分析的入口。","pre":"","id":"u05-l05-q08","source":"白皮书第 4 章租约基础综合"}]}]},{"id":"u06","t":"租约条款与 Recap","s":"从价格走进可执行的合同","c":"#6f50b5","i":"📋","guide":"谈妥价格只完成了交易的一小部分。停租、性能、安全港、装卸时间、滞期费、担保和 Subjects 会决定最终结果。","outcomes":["识别三类租约的关键条款","读懂 Recap 与 Subjects 的法律和流程意义","把模糊商业说法改写成可执行条款"],"L":[{"t":"TC 关键条款","goal":"理解 hire、off-hire、性能、航区与还船","intro":"期租利润取决于实际付租天数与合同性能。任何停租、速度油耗或还船争议都会改变现金流。","keys":["hire 需写币种、周期和付款","off-hire 需事件、因果和时间损失","性能保证必须附带条件"],"trap":"把‘船有问题’直接等同停租，不查条款触发和净时间损失。","source":"白皮书 4.5","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"TC 中 off-hire 条款主要解决什么？","o":["登记国选择","特定事件导致船舶不能提供约定服务时是否暂停付租","船舶买价","货物所有权"],"a":"特定事件导致船舶不能提供约定服务时是否暂停付租","w":"停租通常需要落入列举事件并造成约定的时间损失，具体因果和举证很重要。","pre":"","id":"u06-l01-q01","source":"白皮书 4.5"},{"k":"mc","q":"速度油耗保证最需要搭配哪类定义？","o":["良好天气、载况、容差和测量方法","船员生日","公司市值","港口 Logo"],"a":"良好天气、载况、容差和测量方法","w":"没有适用条件就无法把观测差异归因于船舶性能，也难计算损失。","pre":"","id":"u06-l01-q02","source":"白皮书 4.5"},{"k":"tf","q":"故障是否构成停租，需要同时核对列举事件、服务损失、持续时间和例外。","o":["正确","错误"],"a":"正确","w":"要看故障是否属于条款事件、是否造成服务损失、持续多久以及是否有例外。","pre":"","id":"u06-l01-q03","source":"白皮书 4.5"},{"k":"multi","q":"还船条款通常应明确哪些内容？","o":["地点或范围","燃油数量与价格","船况和提前通知","时间窗口"],"a":["时间窗口","地点或范围","燃油数量与价格","船况和提前通知"],"w":"还船同时影响租期、下一张租约、燃油结算和技术交接，四项缺口都可能引发索赔。","pre":"","id":"u06-l01-q04","source":"白皮书 4.5"},{"k":"prod","q":"把‘船要跑得快、烧得少’改写成可谈判的条款要素。","model":"明确目标航速、主辅机油耗、载况、燃油规格、良好天气海况、容差、数据来源、计算期和索赔方法，并约定慢速航行等例外。","a":"明确目标航速、主辅机油耗、载况、燃油规格、良好天气海况、容差、数据来源、计算期和索赔方法，并约定慢速航行等例外。","w":"可执行性来自适用条件、测量方法和违约救济三层，缺一层都会留下争议空间。","pre":"","id":"u06-l01-q05","source":"白皮书 4.5"}]},{"t":"VC 关键条款","goal":"掌握 laytime、demurrage、NOR 和装卸责任","intro":"航次租的时间经济学围绕允许装卸时间展开。NOR 是否有效、时间何时起算、哪些时段除外，会决定滞期费。","keys":["NOR 是准备就绪通知","laytime 是约定允许时间","demurrage 是超时后的约定补偿"],"trap":"把船到港时间直接当成 laytime 起算时间。","source":"白皮书 4.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"NOR 的核心作用是？","o":["通知船舶已按合同要求到达并准备好装卸","出售船舶","确认贷款放款","签发船级证书"],"a":"通知船舶已按合同要求到达并准备好装卸","w":"有效 NOR 往往是 laytime 起算链条的关键，但到达、准备好和递交通知都需满足条款。","pre":"","id":"u06-l02-q01","source":"白皮书 4.6"},{"k":"mc","q":"Laytime 已用完，装卸仍在继续，通常进入？","o":["贷款宽限期","Demurrage 滞期","Off-hire 停租","船舶报废"],"a":"Demurrage 滞期","w":"滞期费是对超过允许装卸时间的约定金额，是否持续计时及例外要看租约。","pre":"","id":"u06-l02-q02","source":"白皮书 4.6"},{"k":"tf","q":"NOR 是否有效取决于到达船、递交范围、检疫和货舱准备等合同条件。","o":["正确","错误"],"a":"正确","w":"要看租约对 arrived ship、泊位/港口范围、检疫和货舱准备等条件的约定。","pre":"","id":"u06-l02-q03","source":"白皮书 4.6"},{"k":"multi","q":"核算 laytime 应收集哪些时间证据？","o":["Statement of Facts","NOR 及接受记录","天气和装卸中断记录","租约时间条款"],"a":["Statement of Facts","NOR 及接受记录","天气和装卸中断记录","租约时间条款"],"w":"事实时间线必须与合同计时规则结合，单有 SOF 不能自动得到结算结果。","pre":"","id":"u06-l02-q04","source":"白皮书 4.6"},{"k":"prod","q":"解释为什么 demurrage 不是普通意义上的‘罚款’。","model":"它通常是双方预先约定对超过 laytime 的时间损失进行计价的合同机制；是否应付、费率和例外来自租约，不是行政处罚。","a":"它通常是双方预先约定对超过 laytime 的时间损失进行计价的合同机制；是否应付、费率和例外来自租约，不是行政处罚。","w":"要把合同约定损害补偿和公共法罚款区分开。","pre":"","id":"u06-l02-q05","source":"白皮书 4.6"}]},{"t":"BBC 与长期控制","goal":"关注交还、维护、保险和融资接口","intro":"光租期限长、责任转移深，条款必须把技术标准、保险、登记、抵押配合和交还状态写细。","keys":["维护标准保护残值","保险权益要覆盖船东与贷款人","交还条件决定尾部风险"],"trap":"只看长期租金覆盖贷款，不检查资产如何被维护和交还。","source":"白皮书 4.7、8.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"BBC 船东最应持续关注哪项资产保护条款？","o":["每日航线指示","每票货运价","码头装卸工时","承租人的维修、入级、保险和交还义务"],"a":"承租人的维修、入级、保险和交还义务","w":"船东不做日常运营，更依赖合同和监控保证资产状态与保险不中断。","pre":"","id":"u06-l03-q01","source":"白皮书 4.7、8.3"},{"k":"mc","q":"融资船舶做 BBC 时，为什么常需贷款人关注租约？","o":["租约能替代抵押","贷款人决定货物价格","租约现金流和承租人控制会影响抵押物与偿债","贷款人负责开船"],"a":"租约现金流和承租人控制会影响抵押物与偿债","w":"贷款文件可能限制长期租约，并要求转让收益、通知和介入权。","pre":"","id":"u06-l03-q02","source":"白皮书 4.7、8.3"},{"k":"tf","q":"BBC 即使由承租人投保，也通常要在保单、赔款支付和取消通知中保护船东与贷款人。","o":["正确","错误"],"a":"正确","w":"船东和贷款人的资产权益通常需要在保单、赔款支付和取消通知中得到保护。","pre":"","id":"u06-l03-q03","source":"白皮书 4.7、8.3"},{"k":"multi","q":"长期 BBC 交还条款可覆盖哪些方面？","o":["船级和证书状态","坞修与剩余检验周期","备件和记录","允许的正常磨损"],"a":["船级和证书状态","坞修与剩余检验周期","备件和记录","允许的正常磨损"],"w":"交还质量影响再出租和残值，应在签约时定义，不能等到最后一周再争论。","pre":"","id":"u06-l03-q04","source":"白皮书 4.7、8.3"},{"k":"prod","q":"为什么 BBC 租金覆盖债务还不代表项目安全？","model":"还要看承租人信用、保险与维护、残值、违约收船可行性、利率和再融资；若资产失修或承租人违约，账面覆盖会迅速失效。","a":"还要看承租人信用、保险与维护、残值、违约收船可行性、利率和再融资；若资产失修或承租人违约，账面覆盖会迅速失效。","w":"现金流覆盖只是一个屏障，不是全部风险。","pre":"","id":"u06-l03-q05","source":"白皮书 4.7、8.3"}]},{"t":"Recap 与 Subjects","goal":"理解成交摘要、条件先决与合同形成","intro":"Recap 汇总主条款，Subjects 表示仍待满足或解除的条件。措辞、适用法与沟通记录会影响何时形成约束。","keys":["Recap 必须完整反映主条款","Subjects 要写主体、动作和截止时间","解除条件要留证"],"trap":"把‘双方基本同意’当成无条件成交，或反过来认为没签长约就永不受约束。","source":"白皮书 4.8、3.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"Subject to board approval 最需要补充什么？","o":["由谁在何时以何种方式批准或解除条件","船舶颜色","员工人数","油价预测"],"a":"由谁在何时以何种方式批准或解除条件","w":"条件模糊会让双方对是否成交、何时可退出产生不同理解。","pre":"","id":"u06-l04-q01","source":"白皮书 4.8、3.4"},{"k":"mc","q":"Recap 与长式合同正文冲突时，应怎么做？","o":["任选更有利的一条","忽略 Recap","删除所有条款","尽快通过优先顺序和一致性审查消除冲突"],"a":"尽快通过优先顺序和一致性审查消除冲突","w":"Recap 常记录成交商业核心，长约补充细节；冲突不处理会成为争议源。","pre":"","id":"u06-l04-q02","source":"白皮书 4.8、3.4"},{"k":"tf","q":"只要邮件标题写了 ‘subject’，交易就一定没有任何约束力。","o":["正确","错误"],"a":"错误","w":"法律效果取决于完整措辞、条件性质、双方行为和适用法，不能靠单个词机械判断。","pre":"","id":"u06-l04-q03","source":"白皮书 4.8、3.4"},{"k":"multi","q":"高质量 Recap 应至少清楚覆盖？","o":["关键责任与条款修改","Subjects、法律和争议解决","主体和船舶","租金/运费及期限"],"a":["主体和船舶","租金/运费及期限","关键责任与条款修改","Subjects、法律和争议解决"],"w":"Recap 要让不在谈判现场的人也能还原交易，不只记录 headline price。","pre":"","id":"u06-l04-q04","source":"白皮书 4.8、3.4"},{"k":"prod","q":"把‘管理层同意就成交’改写成更可执行的 Subject。","model":"本交易以租家董事会于北京时间某日 18:00 前书面批准为条件；租家须在截止前书面解除该 Subject，逾期未解除则谈判终止且双方不再受拟议条款约束。","a":"本交易以租家董事会于北京时间某日 18:00 前书面批准为条件；租家须在截止前书面解除该 Subject，逾期未解除则谈判终止且双方不再受拟议条款约束。","w":"示例展示主体、动作、形式、时点和后果；正式文本仍需法律审查。","pre":"","id":"u06-l04-q05","source":"白皮书 4.8、3.4"}]},{"t":"单元闯关：从报价到合同","goal":"综合审查租约条款和成交状态","intro":"用‘事件—条件—证据—后果’读条款：什么发生，在什么条件下，用什么证明，最后谁承担多少钱。","keys":["条款必须可触发和可计算","时间证据与文本配对","成交状态不可凭感觉"],"trap":"只标红价格，不标红触发机制与救济。","source":"白皮书第 4 章条款综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"主机故障 10 小时，其中仅 6 小时造成服务损失。停租计算最先取决于？","o":["船价","GT","船名","具体 off-hire 条款对事件和净时间损失的定义"],"a":"具体 off-hire 条款对事件和净时间损失的定义","w":"故障持续时间不必然等于停租时间，需按触发与损失机制计算。","pre":"","id":"u06-l05-q01","source":"白皮书第 4 章条款综合"},{"k":"mc","q":"船已到港但货舱未达到合同清洁标准，NOR 风险是？","o":["可能因未准备好而无效或推迟 laytime","自动增加 DWT","贷款立即到期","船级自动取消"],"a":"可能因未准备好而无效或推迟 laytime","w":"准备就绪通常包括物理和法律准备，货舱不合格会破坏有效 NOR 的基础。","pre":"","id":"u06-l05-q02","source":"白皮书第 4 章条款综合"},{"k":"tf","q":"Recap 应足以让未参加谈判的人还原关键商业条款、风险分配和成交条件。","o":["正确","错误"],"a":"正确","w":"关键条款如果留白，后续可能不是起草细节而是重新谈判，成交状态和风险分配都会不确定。","pre":"","id":"u06-l05-q03","source":"白皮书第 4 章条款综合"},{"k":"multi","q":"审查速度油耗索赔需交叉核对？","o":["合同保证及条件","航海日志和天气数据","载况与航线","计算方法及容差"],"a":["合同保证及条件","航海日志和天气数据","载况与航线","计算方法及容差"],"w":"合同定义决定何时可索赔，事实数据证明是否触发，两条证据链缺一不可。","pre":"","id":"u06-l05-q04","source":"白皮书第 4 章条款综合"},{"k":"order","q":"航次租 laytime 核算的一般顺序。","o":["确认有效 NOR 和计时起点","建立 SOF 事实时间线","按条款剔除或计入各时段","与 allowance 比较并计算滞期或速遣"],"a":["确认有效 NOR 和计时起点","建立 SOF 事实时间线","按条款剔除或计入各时段","与 allowance 比较并计算滞期或速遣"],"w":"从触发到事实，再到规则和金额，保持审计链。","pre":"","id":"u06-l05-q05","source":"白皮书第 4 章条款综合"},{"k":"num","q":"教学情景：允许装卸 72 小时，按条款核算实际计时 84 小时，滞期费每天 24,000 美元。应计滞期约？","o":["288,000 美元","0","12,000 美元","24,000 美元"],"a":"12,000 美元","w":"超时 12 小时即 0.5 天，0.5×24,000＝12,000；正式结算要依租约计时规则。","pre":"","id":"u06-l05-q06","source":"白皮书第 4 章条款综合"},{"k":"prod","q":"给一条重要商业条款做‘四件套’改写。","model":"写清触发事件、适用条件、证据或计算方法、违约或费用后果。例如停租不能只写‘故障停租’，还要定义故障、服务损失、起止和例外。","a":"写清触发事件、适用条件、证据或计算方法、违约或费用后果。例如停租不能只写‘故障停租’，还要定义故障、服务损失、起止和例外。","w":"触发、条件、证据和后果四件套会把模糊口号改造成可以验证、计算和救济的机制。","pre":"","id":"u06-l05-q07","source":"白皮书第 4 章条款综合"},{"k":"mc","q":"最容易让高租金交易变差的因素是？","o":["船名太短","船级证书页数多","不可执行的条款、严重停租和低信用共同吞噬收入","字体不统一"],"a":"不可执行的条款、严重停租和低信用共同吞噬收入","w":"headline rate 只是起点，收到多少、何时收到以及为此承担什么风险才是净价值。","pre":"","id":"u06-l05-q08","source":"白皮书第 4 章条款综合"}]}]},{"id":"u07","t":"船舶经济性","s":"把日租、运费和成本算成同一语言","c":"#e66b2e","i":"🧮","guide":"收入高不等于利润高。先确认租约与可运营天数，再分 OPEX、航次成本和资本开支，最后用 TCE、EBITDA 等同口径比较。","outcomes":["拆分 OPEX、Voyage Cost 与 CAPEX","计算可运营天数、TCE 和船舶 EBITDA","识别现金流模型的数量级错误"],"L":[{"t":"成本分层","goal":"分清日常运营、航次和资本性支出","intro":"OPEX 维持船舶日常适航，航次成本随具体航次发生，CAPEX 带来长期资产或重大改造。分类决定谁承担、如何比较和怎样计入现金流。","keys":["OPEX 常含船员、维修、保险、管理","Voyage Cost 常含燃油与港费","坞修可能含费用化与资本化部分"],"trap":"把所有现金支出统称 OPEX，导致责任方和利润口径混乱。","source":"白皮书 4.7、frag_income","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"典型 TC 船东测算日常船舶 EBITDA 时，最直接从净租金扣什么？","o":["船东承担的 OPEX","租家燃油费","货物采购价","港口建设费"],"a":"船东承担的 OPEX","w":"TC 船东通常收 hire、负担船员维修保险等 OPEX；燃油港费多由租家承担。","pre":"","id":"u07-l01-q01","source":"白皮书 4.7、frag_income"},{"k":"mc","q":"主机节能改造预计使用多年，通常更接近哪类支出？","o":["CAPEX","单航次港费","佣金","租金收入"],"a":"CAPEX","w":"改造形成多年受益并改变资产性能，模型中应与日常维修区分，并考虑停航和折旧/现金流。","pre":"","id":"u07-l01-q02","source":"白皮书 4.7、frag_income"},{"k":"tf","q":"燃油通常按航次成本处理，最终责任取决于租约而非一律归船东。","o":["正确","错误"],"a":"正确","w":"燃油通常是航次成本，责任取决于租约；TC 常由租家承担，VC 常由船东承担。","pre":"","id":"u07-l01-q03","source":"白皮书 4.7、frag_income"},{"k":"multi","q":"船舶 OPEX 预算通常包含哪些科目？","o":["维修备件","保险与管理费","现货航次燃油","船员与伙食"],"a":["船员与伙食","维修备件","保险与管理费"],"w":"燃油是典型航次成本。将其混入 OPEX 会破坏跨租约比较。","pre":"","id":"u07-l01-q04","source":"白皮书 4.7、frag_income"},{"k":"prod","q":"解释为什么成本分类不是会计洁癖。","model":"它决定租约下由谁付款、TCE 与 EBITDA 如何比较、资本开支何时发生以及贷款现金流是否覆盖；分类错一层，投资结论可能整体反向。","a":"它决定租约下由谁付款、TCE 与 EBITDA 如何比较、资本开支何时发生以及贷款现金流是否覆盖；分类错一层，投资结论可能整体反向。","w":"回答要把分类连接到责任、指标和决策。","pre":"","id":"u07-l01-q05","source":"白皮书 4.7、frag_income"}]},{"t":"可运营天数与 EBITDA","goal":"让停租、坞修和佣金进入年度收益","intro":"365 天不是 365 个收租日。计划坞修、故障、空档和停租会减少 earning days；佣金也应在收入层扣除。","keys":["Earning days = 日历天数－停航/空档","毛租先扣佣金","EBITDA 仍不等于自由现金流"],"trap":"用日租×365 作为可分配现金，漏掉停航、利息和资本开支。","source":"白皮书 4.7、案例","kind":"skill","difficulty":1,"q":[{"k":"num","q":"教学情景：日租 20,000 美元，佣金 5%，预计收租 350 天。年度净租金约？","o":["6.30 百万美元","7.30 百万美元","6.65 百万美元","7.00 百万美元"],"a":"6.65 百万美元","w":"20,000×95%×350＝6,650,000。之后还需扣 OPEX 等。","pre":"","id":"u07-l02-q01","source":"白皮书 4.7、案例"},{"k":"num","q":"上题若 OPEX 为 6,500 美元/日并按 365 天发生，船舶 EBITDA 约？","o":["6.65 百万美元","2.37 百万美元","8.02 百万美元","4.28 百万美元"],"a":"4.28 百万美元","w":"6.65m－6,500×365(2.3725m)≈4.2775m；停航时 OPEX 通常仍在发生。","pre":"","id":"u07-l02-q02","source":"白皮书 4.7、案例"},{"k":"tf","q":"船舶 EBITDA 已扣除贷款本金、利息和全部坞修资本开支。","o":["正确","错误"],"a":"错误","w":"EBITDA 是运营层指标，不能替代债务服务和自由现金流。融资与资本开支需要另列。","pre":"","id":"u07-l02-q03","source":"白皮书 4.7、案例"},{"k":"multi","q":"哪些事件可能减少年度 earning days？","o":["可停租故障","船员正常值班","计划坞修","无租约空档"],"a":["计划坞修","无租约空档","可停租故障"],"w":"三类事件都可能让船不能收取约定收入；正常值班属于持续运营。","pre":"","id":"u07-l02-q04","source":"白皮书 4.7、案例"},{"k":"prod","q":"为什么停航一天的经济损失可能大于一天 OPEX？","model":"停航通常损失一天收入，同时多数船员、保险和管理成本仍继续发生，还可能产生修理、改期和后续租约错位损失。","a":"停航通常损失一天收入，同时多数船员、保险和管理成本仍继续发生，还可能产生修理、改期和后续租约错位损失。","w":"要看到收入损失、固定成本和二阶影响。","pre":"","id":"u07-l02-q05","source":"白皮书 4.7、案例"}]},{"t":"TCE 统一语言","goal":"把航次利润折成等价日租","intro":"TCE 用航次收入扣除航次成本后除以航次天数，把不同航线、运价和燃油成本折成可与期租比较的每日收益。","keys":["TCE 先扣 Voyage Cost","分母包括相关航次时间","TCE 通常未扣 OPEX"],"trap":"把 freight 直接除以海上天数，漏掉港口时间、佣金或燃油。","source":"白皮书 4.8、案例","kind":"skill","difficulty":1,"q":[{"k":"num","q":"教学情景：航次运费收入 1.8m，佣金 0.09m，燃油港费等 0.71m，航次 50 天。TCE 约？","o":["20,000 美元/日","36,000 美元/日","14,200 美元/日","18,000 美元/日"],"a":"20,000 美元/日","w":"(1.8－0.09－0.71)m÷50＝20,000/日。这个数仍需再扣船东 OPEX。","pre":"","id":"u07-l03-q01","source":"白皮书 4.8、案例"},{"k":"mc","q":"TCE 最适合解决哪种比较？","o":["比较船舶 GT","确定化学品相容性","判断抵押是否登记","把不同航次净收益和期租日租放到近似同一口径"],"a":"把不同航次净收益和期租日租放到近似同一口径","w":"TCE 是经营表现桥梁，不是技术或法律指标。","pre":"","id":"u07-l03-q02","source":"白皮书 4.8、案例"},{"k":"tf","q":"两条航次 TCE 相同，风险和最终自由现金流就一定相同。","o":["正确","错误"],"a":"错误","w":"货款回收、天数不确定、港口风险、OPEX、坞修和融资仍可能不同。TCE 是比较起点。","pre":"","id":"u07-l03-q03","source":"白皮书 4.8、案例"},{"k":"multi","q":"严谨 TCE 模型需要哪些输入？","o":["海上和港口总时间","可实现运费及佣金","航次燃油消耗与价格","港费/运河费"],"a":["可实现运费及佣金","航次燃油消耗与价格","港费/运河费","海上和港口总时间"],"w":"收入、变动成本和完整时间构成 TCE 三要素。","pre":"","id":"u07-l03-q04","source":"白皮书 4.8、案例"},{"k":"prod","q":"向小白解释为什么港口多等两天会压低 TCE。","model":"运费通常不会因正常等待自动增加，而燃油或港口费用可能继续发生；同一净航次收入被更多天数分摊，所以每日等价收益下降。","a":"运费通常不会因正常等待自动增加，而燃油或港口费用可能继续发生；同一净航次收入被更多天数分摊，所以每日等价收益下降。","w":"答案要指出净收入分子没有同步增加、航次天数分母却变大，因而每日收益下降。","pre":"","id":"u07-l03-q05","source":"白皮书 4.8、案例"}]},{"t":"数字压力测试","goal":"用航速、油价、空放和利用率挑战基准情景","intro":"经济性不是一个答案，而是一组情景。油价改变航次成本，航速改变油耗和天数，空放占用时间，停租直接减少收入。","keys":["变量可能同时影响分子和分母","压力测试需写触发范围","回程货概率不能当确定收入"],"trap":"只改单个数字，却忘了其联动效应。","source":"白皮书案例 1—3、7","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"VC 模型中油价上涨最直接怎样影响 TCE？","o":["运费必然等额上涨","DWT 下降","GT 上升","航次成本上升，TCE 下降"],"a":"航次成本上升，TCE 下降","w":"短期内运费未必同步变化，燃油责任在船东时成本冲击先进入航次利润。","pre":"","id":"u07-l04-q01","source":"白皮书案例 1—3、7"},{"k":"mc","q":"为获取更高运费而空放 8 天，模型最容易漏掉？","o":["船名变更费","GT 变化","船员人数自动翻倍","空放燃油、时间和机会成本"],"a":"空放燃油、时间和机会成本","w":"高 headline freight 需扣到达装港前的成本和时间，才可与当前位置机会比较。","pre":"","id":"u07-l04-q02","source":"白皮书案例 1—3、7"},{"k":"tf","q":"降低航速可能省油却延长航次，所以是否提高 TCE 要结合油价、运价和周转判断。","o":["正确","错误"],"a":"正确","w":"节速可能省油却延长航次并减少年度周转；最终效果取决于油价、运价、租约和速度油耗曲线。","pre":"","id":"u07-l04-q03","source":"白皮书案例 1—3、7"},{"k":"multi","q":"一份可信的经济性敏感性表应测试哪些变量？","o":["利用率/停租","油价与航速","OPEX 和坞修","运价或日租"],"a":["运价或日租","利用率/停租","油价与航速","OPEX 和坞修"],"w":"收入、运营天数、航次成本和固定成本是最常改变结果的驱动。","pre":"","id":"u07-l04-q04","source":"白皮书案例 1—3、7"},{"k":"prod","q":"设计一个‘差但不荒谬’的下行情景。","model":"例如日租下降 15%、收租天数由 355 降至 335、OPEX 上升 8%，并把临近坞修支出前置；说明这些变化可能由市场转弱、故障或成本通胀触发。","a":"例如日租下降 15%、收租天数由 355 降至 335、OPEX 上升 8%，并把临近坞修支出前置；说明这些变化可能由市场转弱、故障或成本通胀触发。","w":"压力情景要有可解释触发，不是随意把所有数归零。","pre":"","id":"u07-l04-q05","source":"白皮书案例 1—3、7"}]},{"t":"单元闯关：从收入到现金","goal":"综合计算 TCE、EBITDA 和现金流边界","intro":"先画合同责任，再确定天数、分子和分母，最后说明指标没有覆盖什么。","keys":["先口径后公式","运营利润不等于偿债后现金","基准必须有压力情景"],"trap":"公式正确但输入属于不同租约或不同时间口径。","source":"白皮书 4.7—4.8 综合","kind":"checkpoint","difficulty":3,"q":[{"k":"num","q":"教学情景：净航次收入 900,000 美元，航次 45 天，TCE 是？","o":["40,500 美元/日","900,000 美元/日","20,000 美元/日","18,000 美元/日"],"a":"20,000 美元/日","w":"900,000÷45＝20,000/日。净航次收入须已扣除佣金和航次成本。","pre":"","id":"u07-l05-q01","source":"白皮书 4.7—4.8 综合"},{"k":"num","q":"TCE 20,000/日，OPEX 7,000/日，按 360 个经营日简化，运营贡献约？","o":["7.20 百万美元","2.52 百万美元","9.72 百万美元","4.68 百万美元"],"a":"4.68 百万美元","w":"(20,000－7,000)×360＝4.68m；正式模型需区分 OPEX 是否按 365 天发生。","pre":"","id":"u07-l05-q02","source":"白皮书 4.7—4.8 综合"},{"k":"tf","q":"把 OPEX 从航次收入中扣除后再计算 TCE，会与通常口径不同。","o":["正确","错误"],"a":"正确","w":"通常 TCE 在扣航次成本后、扣 OPEX 前。若改口径必须显式标注，否则不可比较。","pre":"","id":"u07-l05-q03","source":"白皮书 4.7—4.8 综合"},{"k":"multi","q":"从 EBITDA 走到股东可用现金，还要继续考虑？","o":["利息和本金","税费","坞修与改造 CAPEX","营运资金"],"a":["利息和本金","税费","坞修与改造 CAPEX","营运资金"],"w":"运营层利润不是现金流终点，债务、税、资本开支和营运资金会继续占用现金。","pre":"","id":"u07-l05-q04","source":"白皮书 4.7—4.8 综合"},{"k":"order","q":"建立一艘船年度收益模型的合理顺序。","o":["确定租约和成本责任","估算可收费天数与收入","扣佣金、航次成本和 OPEX","加入 CAPEX、融资、税和退出情景"],"a":["确定租约和成本责任","估算可收费天数与收入","扣佣金、航次成本和 OPEX","加入 CAPEX、融资、税和退出情景"],"w":"这个顺序确保收入、运营利润、融资后现金与退出价值各自具有清晰口径边界。","pre":"","id":"u07-l05-q05","source":"白皮书 4.7—4.8 综合"},{"k":"mc","q":"两条航次 TCE 都是 22,000/日，A 需高风险港口且回款慢。应如何比较？","o":["认为完全等价","只选航程更长的","忽略合同方","保留 TCE 结论，同时为风险、回款和尾部成本作调整"],"a":"保留 TCE 结论，同时为风险、回款和尾部成本作调整","w":"等价日租没有涵盖信用、制裁、安全和现金时点。","pre":"","id":"u07-l05-q06","source":"白皮书 4.7—4.8 综合"},{"k":"prod","q":"用三句话向老板汇报一艘船的经济性。","model":"先报口径：在何种租约、利用率和成本责任下。再报结果：基准 TCE/EBITDA/偿债后现金。最后报脆弱点：哪三个变量会让结论翻转，以及触发阈值。","a":"先报口径：在何种租约、利用率和成本责任下。再报结果：基准 TCE/EBITDA/偿债后现金。最后报脆弱点：哪三个变量会让结论翻转，以及触发阈值。","w":"一份可用于决策的汇报必须同时给出结果、关键假设和观点失效条件，缺一不可。","pre":"","id":"u07-l05-q07","source":"白皮书 4.7—4.8 综合"},{"k":"mc","q":"经济性模型最重要的审计问题是？","o":["每个收入、成本和天数是否属于同一合同与情景","小数位是否最多","图表颜色是否统一","公式是否很长"],"a":"每个收入、成本和天数是否属于同一合同与情景","w":"模型输入只有处在同一合同、日期和情景口径下才可比较，口径一致性比公式复杂度更重要。","pre":"","id":"u07-l05-q08","source":"白皮书 4.7—4.8 综合"}]}]},{"id":"u08","t":"新造船交易","s":"从船厂报价走到可交付的资产","c":"#cf6a32","i":"🏗️","guide":"新造船是多年期项目：规格、付款、退款担保、延期、性能和转让结构相互咬合。每个节点都要有文件和救济。","outcomes":["画出新造船五节点与付款风险","区分 MOA 转让与 Novation","审查谈判、担保和建造合同红线"],"L":[{"t":"五个里程碑","goal":"理解签约、开工、铺龙骨、下水和交付","intro":"造船合同把工程节点与分期付款连接。买方付款越早，越依赖船厂信用、退款担保和进度验证。","keys":["生效条件先于大额付款","里程碑应可客观验证","交付前要完成试航、文件和缺陷处理"],"trap":"把船厂发票当成里程碑已经完成的充分证据。","source":"白皮书 3.1","kind":"skill","difficulty":1,"q":[{"k":"order","q":"把典型新造船主要节点排序。","o":["合同签署并满足生效条件","开工/切钢","铺设龙骨","下水及舾装","海试验收并交付"],"a":["合同签署并满足生效条件","开工/切钢","铺设龙骨","下水及舾装","海试验收并交付"],"w":"节点体现从法律生效到实体形成再到性能验收的过程；具体付款表以合同为准。","pre":"","id":"u08-l01-q01","source":"白皮书 3.1"},{"k":"mc","q":"买方支付首期大额款前，最关键的信用保护之一是？","o":["船名获赞","船厂社交媒体活跃","先签交船证明","收到符合合同的退款担保"],"a":"收到符合合同的退款担保","w":"船厂不能交付或合同依法解除时，退款担保为已付款项提供独立追索路径。","pre":"","id":"u08-l01-q02","source":"白皮书 3.1"},{"k":"tf","q":"新造船延期救济通常取决于延期类型、允许天数、累计天数和合同取消日。","o":["正确","错误"],"a":"正确","w":"合同通常设允许延期、可免责延期、违约金和取消日期，救济取决于延期类型与累计天数。","pre":"","id":"u08-l01-q03","source":"白皮书 3.1"},{"k":"multi","q":"交付验收前通常应核对哪些方面？","o":["未决缺陷清单","交付文件和燃油备品","海试性能","船级和法定证书"],"a":["海试性能","船级和法定证书","未决缺陷清单","交付文件和燃油备品"],"w":"技术、法律和实物交接共同构成交付条件。","pre":"","id":"u08-l01-q04","source":"白皮书 3.1"},{"k":"prod","q":"为什么新造船付款表本质上是风险分配表？","model":"每一期付款决定在船尚未完成时买方暴露多少资金，也决定船厂的现金支持；里程碑、验证权、退款担保和解除救济共同平衡双方风险。","a":"每一期付款决定在船尚未完成时买方暴露多少资金，也决定船厂的现金支持；里程碑、验证权、退款担保和解除救济共同平衡双方风险。","w":"把付款、工程证据和信用保护串起来。","pre":"","id":"u08-l01-q05","source":"白皮书 3.1"}]},{"t":"MOA 与 Novation","goal":"区分转卖建造权益和合同主体替换","intro":"新造船转售可能通过买卖建造中权益、交付后买卖，或在船厂同意下进行合同更替。结构决定谁对船厂有直接权利。","keys":["MOA 解决买卖关系","Novation 让新主体承接原合同权利义务","船厂同意和担保重置常是关键"],"trap":"认为签一份 MOA 就自动成为造船合同买方。","source":"白皮书 3.2","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"Novation 的核心法律效果通常是？","o":["自动取消退款担保","把 TC 变成 VC","经相关方同意，以新合同主体替换原主体并承接权利义务","只修改船名"],"a":"经相关方同意，以新合同主体替换原主体并承接权利义务","w":"它不是简单转让一项应收权，而是重构合同当事人关系。","pre":"","id":"u08-l02-q01","source":"白皮书 3.2"},{"k":"mc","q":"买方通过 MOA 购买一艘交付后船舶，与直接 Novate 造船合同最大的差别是？","o":["MOA 一定无付款","Novation 不需同意","前者主要向卖方取得船舶，后者直接进入船厂合同关系","两者完全相同"],"a":"前者主要向卖方取得船舶，后者直接进入船厂合同关系","w":"直接权利、交付风险、担保受益人和付款路径会不同。","pre":"","id":"u08-l02-q02","source":"白皮书 3.2"},{"k":"tf","q":"原买方和新买方私下同意 Novation，就一定能约束船厂。","o":["正确","错误"],"a":"错误","w":"合同主体替换通常需要船厂及相关方同意，并同步处理退款担保、付款和技术文件。","pre":"","id":"u08-l02-q03","source":"白皮书 3.2"},{"k":"multi","q":"设计 Novation 结构时应重置或确认哪些事项？","o":["原主体是否解除","已付款与后续付款","退款担保受益人","规格变更和索赔"],"a":["已付款与后续付款","退款担保受益人","规格变更和索赔","原主体是否解除"],"w":"主体变了，钱、担保、历史权利和释放范围都必须闭环。","pre":"","id":"u08-l02-q04","source":"白皮书 3.2"},{"k":"prod","q":"用一句话提醒客户 MOA 不能替代什么。","model":"MOA 可以约定买卖，但不能自动让买方成为造船合同当事人或直接取得对船厂、退款担保人的权利；这些要靠有效转让、Novation 或交付结构实现。","a":"MOA 可以约定买卖，但不能自动让买方成为造船合同当事人或直接取得对船厂、退款担保人的权利；这些要靠有效转让、Novation 或交付结构实现。","w":"抓住‘卖方承诺’与‘对第三方直接权利’的区别。","pre":"","id":"u08-l02-q05","source":"白皮书 3.2"}]},{"t":"谈判桌与 Subjects","goal":"从 LOI、报价和还价走向条件清楚的成交","intro":"新造船谈判会经历询价、技术澄清、报价、还价、LOI 和主合同。商业团队必须标明哪些内容仅供讨论，哪些条件尚未解除。","keys":["技术规格与价格同步冻结","Subjects 需有截止和解除方式","长交期放大信用与市场变化"],"trap":"先锁价格后再发现规格、币种和交期口径不同。","source":"白皮书 3.3—3.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"船厂报价便宜 5%，但交期晚两年。比较时必须加入？","o":["GT 加总","船名评分","两年市场机会、成本通胀和信用暴露","只按名义船价排序"],"a":"两年市场机会、成本通胀和信用暴露","w":"新造船价格离不开交付时间，资金占用和周期位置可能比折价更重要。","pre":"","id":"u08-l03-q01","source":"白皮书 3.3—3.4"},{"k":"mc","q":"LOI 最稳健的使用方式是？","o":["明确哪些条款有约束力、哪些仅表意向及后续条件","默认全文都无约束","替代完整规格","省略适用法"],"a":"明确哪些条款有约束力、哪些仅表意向及后续条件","w":"保密、排他、费用等可能单独有约束力，商业主条款是否绑定需清楚表达并法律审查。","pre":"","id":"u08-l03-q02","source":"白皮书 3.3—3.4"},{"k":"tf","q":"技术规格尚未冻结时，最低船价一定是最好报价。","o":["正确","错误"],"a":"错误","w":"不同设备、能耗、备件、船级符号和保修边界会造成全生命周期成本差异。","pre":"","id":"u08-l03-q03","source":"白皮书 3.3—3.4"},{"k":"multi","q":"对船厂 Counter Offer 做可比表，应统一哪些维度？","o":["技术规格与性能","担保、延期和保修","价格币种与税费","交期和付款表"],"a":["价格币种与税费","交期和付款表","技术规格与性能","担保、延期和保修"],"w":"四维统一后才是真正的 apples-to-apples。","pre":"","id":"u08-l03-q04","source":"白皮书 3.3—3.4"},{"k":"prod","q":"写一条高质量新造船报价结论。","model":"在相同规格、交期和付款假设下，A 方案全周期成本较低；但其退款担保银行与延期救济仍未满足门槛，只有 Subject 解除且担保文本获批后才建议推进。","a":"在相同规格、交期和付款假设下，A 方案全周期成本较低；但其退款担保银行与延期救济仍未满足门槛，只有 Subject 解除且担保文本获批后才建议推进。","w":"结论要同时给比较口径、优势、缺口和下一动作。","pre":"","id":"u08-l03-q05","source":"白皮书 3.3—3.4"}]},{"t":"合同与担保红线","goal":"审查 SBC、RG、母公司支持与股东安排","intro":"建造合同定义资产，退款担保保护预付款，母公司担保补充船厂信用，股东协议解决共同投资治理。文本必须相互匹配。","keys":["RG 金额、期限、索赔条件要覆盖合同","性能救济需可测量","变更单会改变价格和交期"],"trap":"只核担保金额，不核担保人、到期和索赔条件。","source":"白皮书 3.5—3.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"退款担保最危险的缺口之一是？","o":["没有船舶照片","字体不是蓝色","在合同取消权可能发生前已到期","页数太少"],"a":"在合同取消权可能发生前已到期","w":"担保有效期必须覆盖付款暴露与合同救济窗口，否则最需要时可能无法索赔。","pre":"","id":"u08-l04-q01","source":"白皮书 3.5—3.6"},{"k":"mc","q":"海试达不到保证航速时，救济取决于？","o":["船员人数","GT 收费","性能定义、容差、复试和违约金/取消机制","市场当天运价"],"a":"性能定义、容差、复试和违约金/取消机制","w":"工程差异只有经过合同测试口径才能转成价格调整或解除权。","pre":"","id":"u08-l04-q02","source":"白皮书 3.5—3.6"},{"k":"tf","q":"船厂母公司出具安慰函，与无条件付款担保的信用保护通常等同。","o":["正确","错误"],"a":"错误","w":"不同文件的义务强度和可执行性可能相差巨大，必须看具体承诺、法律和签署权限。","pre":"","id":"u08-l04-q03","source":"白皮书 3.5—3.6"},{"k":"multi","q":"审查 Change Order 时应同步确认？","o":["性能和保修后果","技术变更内容","价格调整","交期影响"],"a":["技术变更内容","价格调整","交期影响","性能和保修后果"],"w":"一个看似局部的设备变更可能影响重量、能耗、试验和交期。","pre":"","id":"u08-l04-q04","source":"白皮书 3.5—3.6"},{"k":"prod","q":"给退款担保做一个五项检查清单。","model":"核担保人信用和授权、受益人与合同主体、覆盖金额及币种、索赔触发和单据、有效期与自动延长；再核适用法、送达和制裁条款。","a":"核担保人信用和授权、受益人与合同主体、覆盖金额及币种、索赔触发和单据、有效期与自动延长；再核适用法、送达和制裁条款。","w":"检查必须覆盖谁担、担多少、何时索、怎么索、担到何时。","pre":"","id":"u08-l04-q05","source":"白皮书 3.5—3.6"}]},{"t":"单元闯关：把船从图纸变成资产","goal":"综合处理节点、结构、担保和救济","intro":"新造船不是押注船厂会顺利完成，而是把不顺利时的验证、暂停付款、退款和退出机制提前写进交易。","keys":["工程节点有客观证据","付款有信用保护","主体变化必须重做权利链"],"trap":"把乐观进度表当成风险管理。","source":"白皮书第 3 章新造船综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"船厂要求在 RG 原件未交付前支付首期款，最稳健做法是？","o":["按生效与付款条件暂停，先完成担保审核和交付","立即付款建立关系","只口头确认","用宣传册替代"],"a":"按生效与付款条件暂停，先完成担保审核和交付","w":"付款暴露应与合同保护同步，不应以关系替代可执行信用支持。","pre":"","id":"u08-l05-q01","source":"白皮书第 3 章新造船综合"},{"k":"mc","q":"拟接替原买方直接对船厂履约，应优先研究？","o":["仅改船名","签一份经纪佣金单","期租 Recap","经船厂同意的 Novation 及担保重置"],"a":"经船厂同意的 Novation 及担保重置","w":"只有重建合同主体和配套权利，才能让新买方直接面对船厂。","pre":"","id":"u08-l05-q02","source":"白皮书第 3 章新造船综合"},{"k":"tf","q":"重大里程碑付款应把证书签发标准与合同定义、现场事实交叉核对。","o":["正确","错误"],"a":"正确","w":"证书签发人、标准和事实可能与合同不同，重大付款应按约定验证。","pre":"","id":"u08-l05-q03","source":"白皮书第 3 章新造船综合"},{"k":"multi","q":"海试后发现性能偏差，决策前要核对？","o":["测试是否符合合同条件","偏差是否超过容差","复试和修复权","价格调整或取消阈值"],"a":["测试是否符合合同条件","偏差是否超过容差","复试和修复权","价格调整或取消阈值"],"w":"从事实到门槛再到救济，不能直接跳到拒船。","pre":"","id":"u08-l05-q04","source":"白皮书第 3 章新造船综合"},{"k":"order","q":"新造船首期付款控制流程排序。","o":["确认合同生效条件","完成 RG 文本和担保人审核","收到约定形式的有效担保","核对付款指令并按授权付款"],"a":["确认合同生效条件","完成 RG 文本和担保人审核","收到约定形式的有效担保","核对付款指令并按授权付款"],"w":"先让义务生效、信用保护落地，再执行资金。","pre":"","id":"u08-l05-q05","source":"白皮书第 3 章新造船综合"},{"k":"mc","q":"同价两份船厂报价，A 交期更早但 RG 较弱。正确比较是？","o":["随机选择","把交期价值与退款信用风险分别量化后决策","只选 A","只选 B"],"a":"把交期价值与退款信用风险分别量化后决策","w":"商业机会与违约损失是不同维度，需要共同进入风险调整价值。","pre":"","id":"u08-l05-q06","source":"白皮书第 3 章新造船综合"},{"k":"prod","q":"用‘如果—那么—证据’写一条延期控制。","model":"如果非允许延期累计达到约定取消日，那么买方可按约取消并要求返还分期款；累计天数由船厂通知、监造记录和合同延期分类共同证明。","a":"如果非允许延期累计达到约定取消日，那么买方可按约取消并要求返还分期款；累计天数由船厂通知、监造记录和合同延期分类共同证明。","w":"结构化表达能暴露触发、救济和证据缺口。","pre":"","id":"u08-l05-q07","source":"白皮书第 3 章新造船综合"},{"k":"mc","q":"新造船交易最核心的闭环是？","o":["交期最早","船厂规模最大","规格—节点—付款—担保—救济相互一致","船价最低"],"a":"规格—节点—付款—担保—救济相互一致","w":"任何一环脱节都会把工程问题变成无法追回的资金问题。","pre":"","id":"u08-l05-q08","source":"白皮书第 3 章新造船综合"}]}]},{"id":"u09","t":"二手船与尽调","s":"不是收齐文件，而是验证一艘会继续老化的资产","c":"#ca573b","i":"🔎","guide":"二手船交易把市场判断、技术状态、权属和合同集中到几周内。尽调的任务是把卖方说法变成可验证事实，再把缺口变成价格、条件或退出权。","outcomes":["走完二手船交易六步","审查 Q88、证书、检验和唯一编号","把尽调发现转成可执行交易条件"],"L":[{"t":"交易六步","goal":"掌握询价、检查、MOA、条件、交割和收尾","intro":"典型流程从机会与报价开始，经过船舶检查和文件尽调，签 MOA、满足条件、交割付款，最后完成登记和索赔收尾。","keys":["速度取决于资料与船期","检查权和条件要在 MOA 中保住","交割不是流程终点"],"trap":"先被低价吸引并承诺成交，再补做无法改变结果的尽调。","source":"白皮书 3.7、frag_dd","kind":"skill","difficulty":1,"q":[{"k":"order","q":"把二手船交易主要步骤排序。","o":["初筛船舶与卖方并交换报价","检查船舶和关键文件","谈判签署 MOA 并支付押金","满足条件并准备交割","付款、交船和产权登记","完成尾项与档案"],"a":["初筛船舶与卖方并交换报价","检查船舶和关键文件","谈判签署 MOA 并支付押金","满足条件并准备交割","付款、交船和产权登记","完成尾项与档案"],"w":"交易从商业筛选进入技术法律验证，再形成合同并完成同时交割。","pre":"","id":"u09-l01-q01","source":"白皮书 3.7、frag_dd"},{"k":"mc","q":"买方支付押金前最应确认？","o":["卖方没有其他船","MOA 已生效、账户真实且押金机制清楚","船名不会变","所有未来运价上涨"],"a":"MOA 已生效、账户真实且押金机制清楚","w":"押金是实际资金暴露，要核合同触发、托管/持有安排、退款条件和反欺诈验证。","pre":"","id":"u09-l01-q02","source":"白皮书 3.7、frag_dd"},{"k":"tf","q":"签署 MOA 是把检查、交付条件和缺陷救济法律化，而不是结束尽调。","o":["正确","错误"],"a":"正确","w":"MOA 应保留约定检查、交付条件和缺陷救济；签约只是把验证流程法律化。","pre":"","id":"u09-l01-q03","source":"白皮书 3.7、frag_dd"},{"k":"multi","q":"二手船初筛阶段应同步看哪些维度？","o":["卖方权属与信用","目标贸易适配","价格与租金背景","船龄和检验节点"],"a":["价格与租金背景","船龄和检验节点","卖方权属与信用","目标贸易适配"],"w":"商业、技术、法律和用途四维可快速淘汰不合适项目。","pre":"","id":"u09-l01-q04","source":"白皮书 3.7、frag_dd"},{"k":"prod","q":"为什么二手船交易需要‘边看船边看文件’？","model":"实船检查能发现状态，文件能解释历史、权属和证书；两者交叉才能识别照片之外的缺陷和纸面之外的实际问题。","a":"实船检查能发现状态，文件能解释历史、权属和证书；两者交叉才能识别照片之外的缺陷和纸面之外的实际问题。","w":"尽调不是两条流水线，而是证据互证。","pre":"","id":"u09-l01-q05","source":"白皮书 3.7、frag_dd"}]},{"t":"Q88 与文件包","goal":"从问卷提取船舶身份、性能和合规线索","intro":"Q88/规格问卷是高密度入口，但多由提供方填写。要用证书、图纸、报告和运营数据验证关键字段。","keys":["版本和日期决定可用性","字段间要做逻辑校验","空白与 N/A 也是风险信号"],"trap":"把填写完整等同信息真实，或把旧版本当当前状态。","source":"白皮书 3.8、frag_dd","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"收到一份三年前 Q88，第一步应？","o":["只改封面日期","删除历史记录","要求更新并标注截至日期，同时验证关键变化","直接用于当前交割"],"a":"要求更新并标注截至日期，同时验证关键变化","w":"设备、证书、管理人和缺陷都可能变化，陈旧问卷只能做历史线索。","pre":"","id":"u09-l02-q01","source":"白皮书 3.8、frag_dd"},{"k":"mc","q":"Q88 写有某设备，近期检验报告却标注停用。正确处理是？","o":["只信宣传册","取两者平均","把矛盾列为验证项并确认当前状态和修复条件","只信 Q88"],"a":"把矛盾列为验证项并确认当前状态和修复条件","w":"矛盾本身是高价值信号，应通过记录、现场和合同承诺闭环。","pre":"","id":"u09-l02-q02","source":"白皮书 3.8、frag_dd"},{"k":"tf","q":"Q88 是卖方陈述的重要材料，但通常不能替代证书和实船检验。","o":["正确","错误"],"a":"正确","w":"问卷便于筛选和提问，证据链仍需落到可验证来源。","pre":"","id":"u09-l02-q03","source":"白皮书 3.8、frag_dd"},{"k":"multi","q":"审查船舶文件包时应做哪些控制？","o":["追踪缺失和例外","建立清单和版本号","记录签发/到期日","交叉核对船名、IMO 号和主体"],"a":["建立清单和版本号","记录签发/到期日","交叉核对船名、IMO 号和主体","追踪缺失和例外"],"w":"文档控制使数百页材料变成可审计结论。","pre":"","id":"u09-l02-q04","source":"白皮书 3.8、frag_dd"},{"k":"prod","q":"写出一条高质量文件尽调发现。","model":"发现：Q88 记载压载水系统已投用，但最新证书附件未列明该型号；影响：可能限制特定港口合规；行动：卖方在押金到期前提供型式认可、安装和调试证据，否则列为交割条件。","a":"发现：Q88 记载压载水系统已投用，但最新证书附件未列明该型号；影响：可能限制特定港口合规；行动：卖方在押金到期前提供型式认可、安装和调试证据，否则列为交割条件。","w":"发现要包括事实、影响、证据缺口和动作。","pre":"","id":"u09-l02-q05","source":"白皮书 3.8、frag_dd"}]},{"t":"检验、测厚与 PSC","goal":"从证书有效走向技术状态判断","intro":"船级记录、特检、坞检、UTM 测厚和 PSC 缺陷各看一层。证书未过期不等于没有递延维修或集中资本开支。","keys":["UTM 看钢板余量趋势","Conditions of Class 是重要红旗","PSC 重复缺陷反映管理质量"],"trap":"只看有效期，不看附注、遗留项目和下一次检验范围。","source":"白皮书 3.8、frag_dd","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"UTM 报告最直接帮助判断？","o":["运费结算","船舶 GT","船体钢板厚度衰减与换板风险","租家信用"],"a":"船体钢板厚度衰减与换板风险","w":"测厚数据要结合原始厚度、允许腐蚀和位置，评估未来修理量。","pre":"","id":"u09-l03-q01","source":"白皮书 3.8、frag_dd"},{"k":"mc","q":"反复出现相同 PSC 缺陷，可能说明？","o":["船价必然上涨","船级自动升级","货物更轻","维护或安全管理存在系统性弱点"],"a":"维护或安全管理存在系统性弱点","w":"单次缺陷可偶发，重复模式提示整改未根治或管理执行不足。","pre":"","id":"u09-l03-q02","source":"白皮书 3.8、frag_dd"},{"k":"tf","q":"有效船级证书只反映特定时点，未来特检、坞修和腐蚀 CAPEX 仍需预测。","o":["正确","错误"],"a":"正确","w":"证书反映特定时点符合要求，未来特检、坞修、腐蚀和设备寿命仍会带来 CAPEX。","pre":"","id":"u09-l03-q03","source":"白皮书 3.8、frag_dd"},{"k":"multi","q":"看船级状态摘要时，应重点找？","o":["重大改装记录","船级中断历史","Conditions/Recommendations","逾期或即将到期检验"],"a":["Conditions/Recommendations","逾期或即将到期检验","重大改装记录","船级中断历史"],"w":"四类信息可能改变可运营性、保险和交割条件。","pre":"","id":"u09-l03-q04","source":"白皮书 3.8、frag_dd"},{"k":"prod","q":"为什么‘没发现缺陷’不等于‘没有缺陷’？","model":"检验有范围、时间和可达性限制；未开舱、未拆检或未在工况下测试的设备仍有不确定性，应记录限制并用保证、价格或后续检查分配风险。","a":"检验有范围、时间和可达性限制；未开舱、未拆检或未在工况下测试的设备仍有不确定性，应记录限制并用保证、价格或后续检查分配风险。","w":"好报告必须披露检查边界。","pre":"","id":"u09-l03-q05","source":"白皮书 3.8、frag_dd"}]},{"t":"身份、权属与估值","goal":"用 IMO、船体号、呼号和登记号锁定资产","intro":"船名和旗国可变，IMO 号通常随船终身。权属审查还要看登记、抵押、制裁、公司授权和无负担交付。","keys":["四个编号有不同用途","估值日和租约状态必须一致","清洁产权需要可交割证明"],"trap":"用船名搜索代替唯一标识和历史穿透。","source":"白皮书 3.8、附录术语","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"跨船名和旗国追踪同一艘商船，最稳健的核心标识是？","o":["船壳颜色","经纪简称","IMO 号","当前船名"],"a":"IMO 号","w":"IMO 号通常伴随船舶终身，适合关联历史记录；仍应与证书交叉核对。","pre":"","id":"u09-l04-q01","source":"白皮书 3.8、附录术语"},{"k":"mc","q":"二手船清洁产权交付最需要排除？","o":["未解除抵押、海事留置或其他负担","船员爱好","航速过快","GT 太精确"],"a":"未解除抵押、海事留置或其他负担","w":"买方必须取得合同约定的无负担所有权，并设计付款与注销文件同步。","pre":"","id":"u09-l04-q02","source":"白皮书 3.8、附录术语"},{"k":"tf","q":"同一艘船在不同估值日、租约状态和交割窗口下，合理价值可以不同。","o":["正确","错误"],"a":"正确","w":"资产价格随市场、合同现金流、状态和时间变化，估值必须冻结口径。","pre":"","id":"u09-l04-q03","source":"白皮书 3.8、附录术语"},{"k":"multi","q":"估值可比船调整通常考虑？","o":["规格和检验状态","租约附着情况","成交日期与市场变化","船龄与船厂"],"a":["船龄与船厂","规格和检验状态","租约附着情况","成交日期与市场变化"],"w":"没有完全相同的船，调整逻辑应可解释而非只取平均。","pre":"","id":"u09-l04-q04","source":"白皮书 3.8、附录术语"},{"k":"prod","q":"解释为什么船名不能作为尽调主键。","model":"船名可多次变更且可能重名，容易漏掉历史事故、制裁和 PSC 记录；应以 IMO 号为主键，再用船体号、呼号和登记信息互证。","a":"船名可多次变更且可能重名，容易漏掉历史事故、制裁和 PSC 记录；应以 IMO 号为主键，再用船体号、呼号和登记信息互证。","w":"答案要指出可变、重名和漏检风险。","pre":"","id":"u09-l04-q05","source":"白皮书 3.8、附录术语"}]},{"t":"单元闯关：把文件变成结论","goal":"综合形成二手船尽调意见","intro":"尽调输出不应是‘收到 87 份文件’，而应说明哪些假设被证实、哪些缺口影响价格或交割、谁在何时补齐。","keys":["证据要互证","缺口要量化影响","行动要有负责人和截止"],"trap":"把材料数量当作尽调质量。","source":"白皮书 3.7—3.8 综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"卖方只给近期漂亮照片，但拒绝开放船级记录。最合理判断？","o":["忽略船级","重大信息缺口，应暂停关键承诺并要求授权查验","照片足够","直接涨价"],"a":"重大信息缺口，应暂停关键承诺并要求授权查验","w":"对核心证据的访问受阻本身会提高技术和诚信风险。","pre":"","id":"u09-l05-q01","source":"白皮书 3.7—3.8 综合"},{"k":"mc","q":"测厚显示多处接近换板阈值，交易处理可包括？","o":["只保存报告","删除数据","改船名","量化修理和停航并反映在价格、条件或退出权"],"a":"量化修理和停航并反映在价格、条件或退出权","w":"尽调价值在于把发现转换成风险分配。","pre":"","id":"u09-l05-q02","source":"白皮书 3.7—3.8 综合"},{"k":"tf","q":"只要卖方保证无负担，交割时就无需任何抵押注销证据。","o":["正确","错误"],"a":"错误","w":"保证提供追索，但买方更需要在付款同步取得注销、登记和交付文件，避免事后追偿。","pre":"","id":"u09-l05-q03","source":"白皮书 3.7—3.8 综合"},{"k":"multi","q":"二手船红旗升级委员会前，应写清？","o":["尚缺证据","建议条件、价格或放弃方案","已知事实和来源","最坏与可修复影响"],"a":["已知事实和来源","最坏与可修复影响","尚缺证据","建议条件、价格或放弃方案"],"w":"决策者需要的是结构化不确定性和可选动作。","pre":"","id":"u09-l05-q04","source":"白皮书 3.7—3.8 综合"},{"k":"order","q":"把尽调闭环步骤排序。","o":["从投资假设生成问题清单","收集并交叉验证证据","记录发现、影响和置信度","转成价格、交割条件、保证或退出权"],"a":["从投资假设生成问题清单","收集并交叉验证证据","记录发现、影响和置信度","转成价格、交割条件、保证或退出权"],"w":"尽调从假设出发，以合同和决策动作结束。","pre":"","id":"u09-l05-q05","source":"白皮书 3.7—3.8 综合"},{"k":"mc","q":"Q88 与证书的 IMO 号不一致，第一动作是？","o":["选较大的号码","忽略一位数字","暂停使用材料并核实资产身份与版本","按船名猜"],"a":"暂停使用材料并核实资产身份与版本","w":"身份错误可能意味着整包材料属于另一艘船，是最高优先级数据完整性问题。","pre":"","id":"u09-l05-q06","source":"白皮书 3.7—3.8 综合"},{"k":"prod","q":"给投资委员会写一条二手船尽调结论。","model":"在目标贸易和基准租金下项目可行，但特检前换板量、抵押注销路径及压载水文件未闭环；建议把修理上限计入价格，并将三项设为有客观证据的交割先决条件，逾期允许退出。","a":"在目标贸易和基准租金下项目可行，但特检前换板量、抵押注销路径及压载水文件未闭环；建议把修理上限计入价格，并将三项设为有客观证据的交割先决条件，逾期允许退出。","w":"结论应同时包含价值判断、关键缺口和交易保护。","pre":"","id":"u09-l05-q07","source":"白皮书 3.7—3.8 综合"},{"k":"mc","q":"二手船尽调成功的标准是？","o":["没有任何问题","一天内结束","让重大风险被验证、定价、转移或明确拒绝","文件越多越好"],"a":"让重大风险被验证、定价、转移或明确拒绝","w":"风险无法消失，但可以被理解和分配。","pre":"","id":"u09-l05-q08","source":"白皮书 3.7—3.8 综合"}]}]},{"id":"u10","t":"交船与文件","s":"让钱、权属、实物和证据在同一时刻闭环","c":"#b94f62","i":"🗂️","guide":"交船日是交易风险最密集的几个小时。实物交接、产权转移、付款到账、登记注销与合同条件必须按预定顺序同步。","outcomes":["区分三类交船文件","按分钟设计交割日流程","处理 CP、抵押、保险与登记接口"],"L":[{"t":"三类文件","goal":"区分交易、技术和公司授权文件","intro":"交易文件转移权利并记录付款，技术文件证明船舶身份状态，公司文件证明主体和签字人有权完成交易。","keys":["BoS 是产权转移核心文件之一","Protocol 记录实物交付时点","董事会决议和授权书支撑签署权限"],"trap":"把一张交船证明当成所有法律、技术和付款条件的替代品。","source":"白皮书 3.3—3.4、附录 F.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"Bill of Sale 最直接服务于？","o":["安排船员伙食","转移船舶所有权","证明主机性能","计算 TCE"],"a":"转移船舶所有权","w":"BoS 是产权交割核心文件，形式、签署、公证和登记要求需符合合同及注册地规则。","pre":"","id":"u10-l01-q01","source":"白皮书 3.3—3.4、附录 F.3"},{"k":"mc","q":"Protocol of Delivery and Acceptance 通常记录？","o":["历史所有人名单","市场预测","船舶在约定时间地点完成实物交付和接受","贷款利率"],"a":"船舶在约定时间地点完成实物交付和接受","w":"它固定交付时点，常关联风险、收益、燃油和租约切换。","pre":"","id":"u10-l01-q02","source":"白皮书 3.3—3.4、附录 F.3"},{"k":"tf","q":"交易签署权限应由章程、决议、授权书和适用法律证明，不能只看职位。","o":["正确","错误"],"a":"正确","w":"权限来自公司章程、决议、授权书和适用法律，职位称谓不能替代交易授权。","pre":"","id":"u10-l01-q03","source":"白皮书 3.3—3.4、附录 F.3"},{"k":"multi","q":"交船公司文件包可能包括？","o":["法律意见","存续证明","董事会/股东决议","授权书和签字样本"],"a":["存续证明","董事会/股东决议","授权书和签字样本","法律意见"],"w":"这些文件证明主体存在、审批完成、签署有效和义务可执行。","pre":"","id":"u10-l01-q04","source":"白皮书 3.3—3.4、附录 F.3"},{"k":"prod","q":"向新人解释技术文件为什么也会影响产权交割。","model":"证书、日志、图纸和手册虽不直接转移产权，却决定船能否登记、保险和继续营运；缺失可能使买方拿到法律所有权却无法正常使用资产。","a":"证书、日志、图纸和手册虽不直接转移产权，却决定船能否登记、保险和继续营运；缺失可能使买方拿到法律所有权却无法正常使用资产。","w":"交割要实现可拥有也可运营。","pre":"","id":"u10-l01-q05","source":"白皮书 3.3—3.4、附录 F.3"}]},{"t":"条件先决 CP","goal":"把付款前必须满足的事项变成可核验清单","intro":"CP 不是泛泛的‘一切满意’，而是明确谁提交什么文件、满足什么标准、由谁豁免以及何时截止。","keys":["每项 CP 有责任人和证据","Waiver 权限需清楚","未满足与仅待形式确认要区分"],"trap":"在交割电话上第一次发现关键批准或注销文件缺失。","source":"白皮书 3.3、8.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"高质量 CP 清单最需要哪一列？","o":["参与人昵称","状态、责任人、证据和截止时间","文件颜色","打印页数"],"a":"状态、责任人、证据和截止时间","w":"清单要能驱动关闭流程，而不只是列名词。","pre":"","id":"u10-l02-q01","source":"白皮书 3.3、8.6"},{"k":"mc","q":"某 CP 尚未满足但商业团队想继续交割，正确机制是？","o":["让经纪人代签所有文件","由有权主体评估影响并按合同书面豁免或延期","口头忽略","删除清单"],"a":"由有权主体评估影响并按合同书面豁免或延期","w":"豁免会放弃保护，需要知道风险、权限和是否附条件。","pre":"","id":"u10-l02-q02","source":"白皮书 3.3、8.6"},{"k":"tf","q":"CP Waiver 只表示愿意在条件未满足时继续，原风险可能仍需其他保护。","o":["正确","错误"],"a":"正确","w":"豁免只表示一方愿意在未满足条件下继续，风险可能仍在并需其他保护。","pre":"","id":"u10-l02-q03","source":"白皮书 3.3、8.6"},{"k":"multi","q":"适合作为买方交割 CP 的事项包括？","o":["有效保险和登记安排","付款账户反欺诈核验","无负担产权证明","卖方授权文件"],"a":["无负担产权证明","卖方授权文件","有效保险和登记安排","付款账户反欺诈核验"],"w":"产权、权限、接续营运和资金安全都是交割门槛。","pre":"","id":"u10-l02-q04","source":"白皮书 3.3、8.6"},{"k":"prod","q":"把‘文件齐全后付款’改写成可操作控制。","model":"买方仅在关闭清单列明的每项 CP 均由指定审核人标记满足或获授权书面豁免、最终签署版进入交割托管且收款账户完成独立回拨验证后发出付款指令。","a":"买方仅在关闭清单列明的每项 CP 均由指定审核人标记满足或获授权书面豁免、最终签署版进入交割托管且收款账户完成独立回拨验证后发出付款指令。","w":"控制必须定义清单、审核、版本和资金动作。","pre":"","id":"u10-l02-q05","source":"白皮书 3.3、8.6"}]},{"t":"交割日分钟表","goal":"设计付款、文件释放和船舶交付的同步机制","intro":"良好 closing agenda 把时区、通话人、文件托管、银行确认、BoS 释放、PODA 签署和船上交接排到分钟。","keys":["钱到和文件释放要同步","账户变更必须独立核验","船上与办公室保持单一时间线"],"trap":"先释放不可逆文件，再等待无法确认的资金。","source":"白皮书案例 4、附录 F.3","kind":"skill","difficulty":1,"q":[{"k":"order","q":"把简化交割动作按稳健顺序排列。","o":["确认全部 CP 与签署版文件就绪","买方发出经核验的付款指令","收款行确认可用资金到账","托管方释放 BoS 等产权文件","双方签署 PODA 并完成船上交接"],"a":["确认全部 CP 与签署版文件就绪","买方发出经核验的付款指令","收款行确认可用资金到账","托管方释放 BoS 等产权文件","双方签署 PODA 并完成船上交接"],"w":"核心是条件满足后让资金、产权和实物尽可能同步。","pre":"","id":"u10-l03-q01","source":"白皮书案例 4、附录 F.3"},{"k":"mc","q":"交割前夜收到邮件要求更换收款账户，首要动作？","o":["把款拆小规避审批","停止付款并通过已知独立渠道回拨核验及重新授权","按新邮件立即支付","只看域名相似"],"a":"停止付款并通过已知独立渠道回拨核验及重新授权","w":"交割支付是商务电邮诈骗高风险场景，任何账户变化都必须脱离原邮件链验证。","pre":"","id":"u10-l03-q02","source":"白皮书案例 4、附录 F.3"},{"k":"tf","q":"银行显示付款已发送，就等同卖方已收到不可撤销可用资金。","o":["正确","错误"],"a":"错误","w":"发送、处理中、到账和可用是不同状态，文件释放条件应使用合同约定的可靠确认。","pre":"","id":"u10-l03-q03","source":"白皮书案例 4、附录 F.3"},{"k":"multi","q":"Closing Agenda 应列明？","o":["失败时暂停与升级路径","动作和精确顺序","负责人及联系方式","所需证据与版本"],"a":["动作和精确顺序","负责人及联系方式","所需证据与版本","失败时暂停与升级路径"],"w":"分钟表既是计划也是异常处理剧本。","pre":"","id":"u10-l03-q04","source":"白皮书案例 4、附录 F.3"},{"k":"prod","q":"写一条交割日 Stop Rule。","model":"若收款账户、抵押注销文件、银行到账状态或签署权限与已批准关闭包不一致，任何人均应暂停文件释放和船上签字，并立即升级至交易负责人和法律顾问。","a":"若收款账户、抵押注销文件、银行到账状态或签署权限与已批准关闭包不一致，任何人均应暂停文件释放和船上签字，并立即升级至交易负责人和法律顾问。","w":"Stop Rule 必须列出触发和暂停对象。","pre":"","id":"u10-l03-q05","source":"白皮书案例 4、附录 F.3"}]},{"t":"登记、抵押与权利转让","goal":"理解旧权利退出和新权利生效的接力","intro":"卖方需注销旧登记和抵押，买方需建立新登记、保险和融资担保。租约收益、保险赔款和账户权利也可能同步转让。","keys":["Deletion 与新登记时间要衔接","Mortgage release 与新抵押要协调","Notice/Acknowledgment 让第三方知道转让"],"trap":"认为签完 BoS，登记、保险和抵押会自动完成。","source":"白皮书 3.4、8.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"买方贷款人要求对船舶取得第一顺位抵押，交割前必须重点确认？","o":["旧抵押可按同步机制解除且新抵押可有效登记","船名不改","运价上涨","GT 与 NT 相等"],"a":"旧抵押可按同步机制解除且新抵押可有效登记","w":"同一资产不能在未知旧负担下交付清洁产权，顺位取决于注销和登记。","pre":"","id":"u10-l04-q01","source":"白皮书 3.4、8.6"},{"k":"mc","q":"向租家发出 earnings assignment notice 的主要目的？","o":["取消保险","增加航速","通知租金收款权已按融资文件转让","改变租约类型"],"a":"通知租金收款权已按融资文件转让","w":"通知和确认让租家知道在触发后应向谁付款，并完善对第三方效力。","pre":"","id":"u10-l04-q02","source":"白皮书 3.4、8.6"},{"k":"tf","q":"船舶更换旗国期间，保险和法定证书接续可以留到开航后再处理。","o":["正确","错误"],"a":"错误","w":"登记、证书和保险缺口可能让船无法合法开航或失去保障，应在交付时间线上闭环。","pre":"","id":"u10-l04-q03","source":"白皮书 3.4、8.6"},{"k":"multi","q":"交割后立即归档哪些最终证据？","o":["付款及到账证明","已释放产权和注销文件","PODA 与燃油备品结算","新登记、保险和抵押回执"],"a":["付款及到账证明","已释放产权和注销文件","PODA 与燃油备品结算","新登记、保险和抵押回执"],"w":"最终档案支持产权、审计、融资和未来再出售。","pre":"","id":"u10-l04-q04","source":"白皮书 3.4、8.6"},{"k":"prod","q":"解释交割为什么像接力赛而不是单点签字。","model":"卖方的产权、抵押、登记和保险需要有序退出，买方的新产权、融资担保、登记和保险同时接上；任一棒落地都会出现权利或运营空档。","a":"卖方的产权、抵押、登记和保险需要有序退出，买方的新产权、融资担保、登记和保险同时接上；任一棒落地都会出现权利或运营空档。","w":"强调旧体系退出与新体系生效的同步。","pre":"","id":"u10-l04-q05","source":"白皮书 3.4、8.6"}]},{"t":"单元闯关：交船日不能即兴","goal":"综合处理资金、文件、船上与异常事件","intro":"交割最好的状态不是所有人反应快，而是每个人只需按已经演练的 agenda、版本清单和 Stop Rule 行动。","keys":["一份关闭清单","一个时间基准","一个文件真相源","明确暂停权"],"trap":"关键时刻用群聊消息替代正式状态和授权。","source":"白皮书交付文件与案例综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"卖方称已注销抵押但暂时无正式证据，买方应？","o":["仅凭口头继续","把价格加一美元","先接船再说","按 CP 和同步机制暂停不可逆交割动作"],"a":"按 CP 和同步机制暂停不可逆交割动作","w":"清洁产权是核心交割条件，缺证据时不应靠事后索赔替代。","pre":"","id":"u10-l05-q01","source":"白皮书交付文件与案例综合"},{"k":"mc","q":"船上已签 PODA，办公室才发现价款未到。暴露说明？","o":["保险太多","实物交接与资金/文件释放未使用统一控制点","船速太快","GT 太低"],"a":"实物交接与资金/文件释放未使用统一控制点","w":"跨地点交割必须让船上只按经授权的 closing call 指令签署。","pre":"","id":"u10-l05-q02","source":"白皮书交付文件与案例综合"},{"k":"tf","q":"最终文件只需保留扫描件文件名，不必记录签署版、时间和释放条件。","o":["正确","错误"],"a":"错误","w":"版本、签署、时间和释放状态决定文件是否真正生效。","pre":"","id":"u10-l05-q03","source":"白皮书交付文件与案例综合"},{"k":"multi","q":"交割前 Dry Run 应验证？","o":["异常暂停与升级","联系人和替代人","银行时区与截止","文件签署/托管/释放"],"a":["联系人和替代人","银行时区与截止","文件签署/托管/释放","异常暂停与升级"],"w":"演练用来发现流程依赖，不是形式会议。","pre":"","id":"u10-l05-q04","source":"白皮书交付文件与案例综合"},{"k":"order","q":"处理交割账户变更请求的顺序。","o":["立即冻结原付款流程","通过预先登记号码独立回拨","获取双方重新授权及银行证明","更新关闭清单后再执行"],"a":["立即冻结原付款流程","通过预先登记号码独立回拨","获取双方重新授权及银行证明","更新关闭清单后再执行"],"w":"脱离可疑邮件链验证，并重新走授权。","pre":"","id":"u10-l05-q05","source":"白皮书交付文件与案例综合"},{"k":"mc","q":"CP 已满足但文件中的船舶 IMO 号错一位，应？","o":["暂停签署/释放并更正，重新核对全部相关文件","认为是小事","手写后不留记录","按船名猜"],"a":"暂停签署/释放并更正，重新核对全部相关文件","w":"核心资产标识错误会影响产权、登记和执行，不能留给交割后。","pre":"","id":"u10-l05-q06","source":"白皮书交付文件与案例综合"},{"k":"prod","q":"用 30 秒口头汇报交割状态。","model":"截至统一时间，全部 24 项 CP 中 23 项满足，旧抵押注销回执待银行出具；资金已备妥但未发送，BoS 在托管且未释放，船上已获暂停指令。下一更新节点为回执收到并由法律审核通过。","a":"截至统一时间，全部 24 项 CP 中 23 项满足，旧抵押注销回执待银行出具；资金已备妥但未发送，BoS 在托管且未释放，船上已获暂停指令。下一更新节点为回执收到并由法律审核通过。","w":"状态必须同时报条件、钱、文件、船上和下一动作。","pre":"","id":"u10-l05-q07","source":"白皮书交付文件与案例综合"},{"k":"mc","q":"交割完成的真正判据是？","o":["视频会议结束","经纪人说 Done","PODA 单独签完","价款、清洁产权、实物、登记保险和最终证据按约闭环"],"a":"价款、清洁产权、实物、登记保险和最终证据按约闭环","w":"‘Done’ 应由证据定义，不由情绪定义。","pre":"","id":"u10-l05-q08","source":"白皮书交付文件与案例综合"}]}]},{"id":"u11","t":"保险与事故","s":"从事故问到保单、免赔、证据和追偿","c":"#d64c5b","i":"🛟","guide":"保险不是九个缩写，而是不同损失口袋的分工。事故发生后要先保人保船、通知保全，再分析哪张保单、哪些除外和谁可追偿。","outcomes":["区分主要海事保险的承保对象","处理碰撞、机损、停租与战争风险","建立事故通知和索赔证据链"],"L":[{"t":"保险九宫格","goal":"识别 H&M、P&I、War、LOH 等主要保障","intro":"H&M 关注船体机器自身物损，P&I 处理大量第三方责任，War 覆盖战争相关风险，LOH 保护特定停航收入。其他保障按建造、绑架、货物或政治风险补充。","keys":["先问损失对象","再问致因与除外","最后看免赔和限额"],"trap":"看到事故就问‘买保险了吗’，却不区分损失口袋和触发原因。","source":"白皮书 5.1—5.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"主机突发损坏，修理船舶自身机器的损失首先可能落在哪类保险？","o":["信用保险","H&M 船壳险","P&I 货主责任","租家责任险"],"a":"H&M 船壳险","w":"H&M 主要承保船体和机器的物质损失，但是否赔付仍取决于致因、除外、维护义务和免赔额。","pre":"","id":"u11-l01-q01","source":"白皮书 5.1—5.3"},{"k":"mc","q":"船员受伤、油污责任和货损索赔更典型由？","o":["建造险","P&I 保赔险","仅 H&M","贷款保险"],"a":"P&I 保赔险","w":"P&I 是船东第三方责任的主要安排，具体范围由协会规则和入会条件决定。","pre":"","id":"u11-l01-q02","source":"白皮书 5.1—5.3"},{"k":"tf","q":"H&M 的机器损坏赔付仍受事故原因、维护义务、除外和免赔额限制。","o":["正确","错误"],"a":"正确","w":"磨损、维护不善、免赔额和除外可能限制赔偿；要从事故原因和保单条款判断。","pre":"","id":"u11-l01-q03","source":"白皮书 5.1—5.3"},{"k":"multi","q":"为营运船舶建立基础保险图谱时，通常应考虑？","o":["战争险","根据收入结构考虑 LOH","H&M","P&I"],"a":["H&M","P&I","战争险","根据收入结构考虑 LOH"],"w":"四类分别保护资产、责任、战争致因和部分收入中断，彼此不完全替代。","pre":"","id":"u11-l01-q04","source":"白皮书 5.1—5.3"},{"k":"prod","q":"用‘对象—原因—后果’解释如何找保单。","model":"先看损失对象是本船、第三方、收入还是人员，再查事故由海上危险、机器故障、战争或其他原因触发，最后核对修理、责任、停租等后果落在哪张保单及其除外。","a":"先看损失对象是本船、第三方、收入还是人员，再查事故由海上危险、机器故障、战争或其他原因触发，最后核对修理、责任、停租等后果落在哪张保单及其除外。","w":"不要从保单名称倒推所有事故。","pre":"","id":"u11-l01-q05","source":"白皮书 5.1—5.3"}]},{"t":"H&M、P&I 与碰撞","goal":"处理本船损失、对外责任和保险接口","intro":"碰撞可能同时造成本船物损、他船物损、污染、人员和货物责任，因此常跨 H&M 与 P&I，并涉及责任比例和追偿。","keys":["本船物损与第三方责任分开","碰撞责任条款决定接口","未经同意的责任承认可能伤害理赔"],"trap":"认为一次事故只报一张保单，或现场直接承认全部责任。","source":"白皮书案例 5—6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"本船与他船碰撞，本船船首受损。修理本船的部分首先看？","o":["H&M","他船货物保险","租家信用险","LOH 单独"],"a":"H&M","w":"本船物质损失属于 H&M 典型范围；随后由保险人依据责任对第三方追偿。","pre":"","id":"u11-l02-q01","source":"白皮书案例 5—6"},{"k":"mc","q":"碰撞导致大量油污清理和第三方索赔，首先应同步通知？","o":["无需通知","P&I 及相关保险/应急方","只通知船厂","只通知租家销售"],"a":"P&I 及相关保险/应急方","w":"污染责任需要快速应急、证据和专业处理，迟报可能放大损失或影响保障。","pre":"","id":"u11-l02-q02","source":"白皮书案例 5—6"},{"k":"tf","q":"碰撞后应先救援、保全事实和通知，不应未经授权承认全部责任。","o":["正确","错误"],"a":"正确","w":"应先救援、保全事实并按程序通知；责任认定需要证据和法律分析，避免未经授权承认。","pre":"","id":"u11-l02-q03","source":"白皮书案例 5—6"},{"k":"multi","q":"碰撞索赔证据可能包括？","o":["航海日志与 VDR","AIS/雷达和海图","船员证言与事故照片","检验和修理报价"],"a":["航海日志与 VDR","AIS/雷达和海图","船员证言与事故照片","检验和修理报价"],"w":"责任与损失金额需要不同证据共同支持。","pre":"","id":"u11-l02-q04","source":"白皮书案例 5—6"},{"k":"prod","q":"解释为什么碰撞理赔要建立‘两个账本’。","model":"一个账本记录本船修理、救助和停航等自身损失，另一个记录他船、货物、人员、污染等第三方责任；两者对应保单、免赔和追偿路径不同。","a":"一个账本记录本船修理、救助和停航等自身损失，另一个记录他船、货物、人员、污染等第三方责任；两者对应保单、免赔和追偿路径不同。","w":"分账能避免遗漏和重复。","pre":"","id":"u11-l02-q05","source":"白皮书案例 5—6"}]},{"t":"LOH、战争与绑架","goal":"识别收入中断和特殊致因保障","intro":"LOH 并不为所有没赚到的钱买单，通常要求先发生符合条件的物损并超过免赔期。战争与 K&R 处理常规保单排除的特殊风险。","keys":["LOH 有触发事故和免赔天数","War Risk 受航区与通知影响","K&R 重视专业响应与保密"],"trap":"把市场没货、普通延误和承保物损导致的停航混为一谈。","source":"白皮书 5.2—5.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"船因市场低迷闲置 20 天，LOH 通常是否赔付？","o":["通常不赔，因为缺少承保物损触发","必然赔","由 GT 决定","由船名决定"],"a":"通常不赔，因为缺少承保物损触发","w":"LOH 不是营业额保证；它通常跟随 H&M 等承保事故造成的时间损失。","pre":"","id":"u11-l03-q01","source":"白皮书 5.2—5.3"},{"k":"mc","q":"进入列明战争高风险区域前，常需要？","o":["自动获得免费保障","注销船级","删除 AIS 历史","通知保险人、确认附加保费和航区条件"],"a":"通知保险人、确认附加保费和航区条件","w":"战争险的保障地域和通知义务会动态调整，商业决定前需确认有效覆盖。","pre":"","id":"u11-l03-q02","source":"白皮书 5.2—5.3"},{"k":"tf","q":"LOH 免赔期为 14 天，承保事故停航 10 天，通常不会产生可赔天数。","o":["正确","错误"],"a":"正确","w":"免赔期先由被保险人承担；具体是 deductible 还是 franchise 需看条款。","pre":"","id":"u11-l03-q03","source":"白皮书 5.2—5.3"},{"k":"multi","q":"绑架或海盗事件处理中，哪些原则重要？","o":["立即通知指定专业响应方","控制信息和授权链","保存沟通和费用证据","人员安全优先"],"a":["人员安全优先","立即通知指定专业响应方","控制信息和授权链","保存沟通和费用证据"],"w":"此类事件高度敏感，需要保险人、危机顾问和政府等按预案协调。","pre":"","id":"u11-l03-q04","source":"白皮书 5.2—5.3"},{"k":"prod","q":"为什么战争险要在每个高风险航次前重新确认？","model":"高风险区域、附加费和制裁环境可能快速变化，昨天的航区许可和保费不一定覆盖明天的挂港；应以出航前保险人确认和最新条款为准。","a":"高风险区域、附加费和制裁环境可能快速变化，昨天的航区许可和保费不一定覆盖明天的挂港；应以出航前保险人确认和最新条款为准。","w":"强调动态边界和书面确认。","pre":"","id":"u11-l03-q05","source":"白皮书 5.2—5.3"}]},{"t":"IOI 与索赔链","goal":"理解保险利益、共同被保险人和通知流程","intro":"IOI 是 Interest of Insured 的安排证明/确认，不是多买一张相同保单。融资人、船东和管理人可能需要不同保险权益。","keys":["先确认谁有可保利益","保单取消与赔款支付应保护贷款人","事故通知越早越好"],"trap":"把 IOI 当重复投保，或事故处理完才通知保险人。","source":"白皮书 5.2、8.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"贷款人要求保险赔款转让和取消通知，主要保护？","o":["提高 GT","减少船员","抵押资产受损时的偿债与担保价值","贷款人开船权"],"a":"抵押资产受损时的偿债与担保价值","w":"贷款人依赖船舶和保险赔款作为信用支持，需要知道保单不会无通知失效。","pre":"","id":"u11-l04-q01","source":"白皮书 5.2、8.6"},{"k":"mc","q":"重大事故发生后的第一组动作应更接近？","o":["救人控险、保全证据并按保单及时通知","先计算最终赔款","先承认责任","等待媒体报道"],"a":"救人控险、保全证据并按保单及时通知","w":"安全、减损和通知是理赔基础，金额评估随后逐步完善。","pre":"","id":"u11-l04-q02","source":"白皮书 5.2、8.6"},{"k":"tf","q":"同一保险安排列入多个受保护主体，等同每个主体都能就同一损失重复获得全额赔偿。","o":["正确","错误"],"a":"错误","w":"保险遵循损失补偿与利益边界，列名是保护权益和程序，不产生重复获利。","pre":"","id":"u11-l04-q03","source":"白皮书 5.2、8.6"},{"k":"multi","q":"索赔通知至少应包含？","o":["已采取的减损措施","联系人与后续证据计划","事故时间地点和初步经过","已知损失和人员环境情况"],"a":["事故时间地点和初步经过","已知损失和人员环境情况","已采取的减损措施","联系人与后续证据计划"],"w":"初报不必等事实全部清楚，但应让保险人能介入并保留权利。","pre":"","id":"u11-l04-q04","source":"白皮书 5.2、8.6"},{"k":"prod","q":"写一条理赔材料的证据链。","model":"用事故通知锁定时点和初步事实，以日志/VDR/检验报告证明原因，以发票工时和付款证明量化损失，再用租约和收入记录证明停航损失，并记录保险人审批与减损动作。","a":"用事故通知锁定时点和初步事实，以日志/VDR/检验报告证明原因，以发票工时和付款证明量化损失，再用租约和收入记录证明停航损失，并记录保险人审批与减损动作。","w":"原因、金额、合同损失和程序四层都要闭环。","pre":"","id":"u11-l04-q05","source":"白皮书 5.2、8.6"}]},{"t":"单元闯关：事故发生后","goal":"综合定位保险、程序与追偿","intro":"先响应事故，再并行开本船、第三方、收入和特殊风险四条线；每条线都记录触发、免赔、限额、证据和追偿。","keys":["安全与减损优先","多保单并行通知","不未经授权承认责任"],"trap":"等最终原因报告出来才报案。","source":"白皮书第 5 章保险综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"主机承保损坏导致停航 25 天，可能同时涉及？","o":["只有战争险","没有任何保险","H&M 修理和符合条件的 LOH 时间损失","只有 P&I"],"a":"H&M 修理和符合条件的 LOH 时间损失","w":"同一物损可触发资产修复与收入中断两条保单，但免赔和条件各自计算。","pre":"","id":"u11-l05-q01","source":"白皮书第 5 章保险综合"},{"k":"mc","q":"船员受伤并产生岸上医疗和遣返费用，首先看？","o":["TCE","造船 RG","P&I 责任范围及船员安排","GT 证书"],"a":"P&I 责任范围及船员安排","w":"船员伤病责任是 P&I 的典型领域，同时要履行劳动和医疗义务。","pre":"","id":"u11-l05-q02","source":"白皮书第 5 章保险综合"},{"k":"tf","q":"事故费用低于 H&M 免赔额，就无需记录或通知任何相关方。","o":["正确","错误"],"a":"错误","w":"金额可能继续扩大、涉及第三方或形成追偿；是否通知要按保单和管理程序，而非早期估值武断决定。","pre":"","id":"u11-l05-q03","source":"白皮书第 5 章保险综合"},{"k":"multi","q":"一次搁浅事故可能产生哪些损失口袋？","o":["救助和共同海损","货损/污染责任","停航收入","本船船体损伤"],"a":["本船船体损伤","救助和共同海损","货损/污染责任","停航收入"],"w":"复杂海事事故往往跨 H&M、P&I、货物和 LOH。","pre":"","id":"u11-l05-q04","source":"白皮书第 5 章保险综合"},{"k":"order","q":"事故响应与理赔的一般顺序。","o":["保护人员环境并控制进一步损失","按应急预案通知保险人和主管方","保全现场、数据与文件","查明责任并量化损失","提交索赔、配合调查并追偿"],"a":["保护人员环境并控制进一步损失","按应急预案通知保险人和主管方","保全现场、数据与文件","查明责任并量化损失","提交索赔、配合调查并追偿"],"w":"安全和通知必须先于最终分析，证据从第一分钟开始。","pre":"","id":"u11-l05-q05","source":"白皮书第 5 章保险综合"},{"k":"mc","q":"保险经纪人说‘应该能赔’，可以直接记为确定应收款吗？","o":["可以全额入账","只要口头说过即可","由租家决定","不能，应以保单、事实、免赔和保险人确认评估"],"a":"不能，应以保单、事实、免赔和保险人确认评估","w":"保险回收有不确定性和时间差，财务模型应审慎。","pre":"","id":"u11-l05-q06","source":"白皮书第 5 章保险综合"},{"k":"prod","q":"用一页事故简报的结构回答管理层。","model":"事件与当前安全状态；本船、第三方、收入和特殊风险损失；已通知保单及免赔限额；关键证据和责任不确定性；未来 24 小时动作、负责人和需要决策事项。","a":"事件与当前安全状态；本船、第三方、收入和特殊风险损失；已通知保单及免赔限额；关键证据和责任不确定性；未来 24 小时动作、负责人和需要决策事项。","w":"简报既要控制现在也要保护未来索赔。","pre":"","id":"u11-l05-q07","source":"白皮书第 5 章保险综合"},{"k":"mc","q":"保险管理的终点是？","o":["把所有事故外包","事故后再读条款","让风险、保障、程序和证据在事故前后都能闭环","买最多保单"],"a":"让风险、保障、程序和证据在事故前后都能闭环","w":"保险是风险融资与治理系统，不是一张万能收据。","pre":"","id":"u11-l05-q08","source":"白皮书第 5 章保险综合"}]}]},{"id":"u12","t":"环保、风险与制裁","s":"任何一条红线都可能让商业方案归零","c":"#c53b5b","i":"🛡️","guide":"项目必须同时过技术、商业、财务、法律、环境和制裁六维。环保指标和制裁筛查都不是一次性打勾，而是随船、货、主体和航次变化。","outcomes":["建立六维风险审批图","区分 MARPOL、EEXI、CII 与 BWTS","穿透主体、货物、船舶和付款链做制裁筛查"],"L":[{"t":"六维风险图","goal":"从单一收益率扩展到六类可否决风险","intro":"技术看船能不能做，商业看有没有需求，财务看现金流，法律看权利可执行，环境看排放合规，制裁看交易是否可做。","keys":["维度之间会传导","红线可直接否决","风险必须有 Owner 和监测指标"],"trap":"把高收益当成其他风险可以被忽略的理由。","source":"白皮书 5.4—5.5","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"项目 IRR 很高，但目标货主在制裁名单上。最合理结论？","o":["收益高就继续","只提高利率","换船名即可","先停止推进并完成法律制裁评估，高收益不能覆盖违法风险"],"a":"先停止推进并完成法律制裁评估，高收益不能覆盖违法风险","w":"制裁可造成交易禁止、资金冻结、保险失效和刑责，不能简单定价吸收。","pre":"","id":"u12-l01-q01","source":"白皮书 5.4—5.5"},{"k":"mc","q":"船舶技术可行但目标港口保险无法覆盖，属于什么信号？","o":["商业方案仍不可执行，需要重构航线或保障","技术证书可替代保险","只影响船名","没有影响"],"a":"商业方案仍不可执行，需要重构航线或保障","w":"六维不是独立评分加总，任何关键维度不通过都可能形成 No-Go。","pre":"","id":"u12-l01-q02","source":"白皮书 5.4—5.5"},{"k":"tf","q":"可执行的风险登记表应写概率影响、触发指标、负责人和应对动作。","o":["正确","错误"],"a":"正确","w":"没有 Owner、触发和动作的风险表无法驱动管理。","pre":"","id":"u12-l01-q03","source":"白皮书 5.4—5.5"},{"k":"multi","q":"完整项目审批可覆盖哪些维度？","o":["法律、环保与制裁","技术与运营","市场与交易对手","财务与融资"],"a":["技术与运营","市场与交易对手","财务与融资","法律、环保与制裁"],"w":"这些维度共同决定项目是否可做、可收钱、可持续。","pre":"","id":"u12-l01-q04","source":"白皮书 5.4—5.5"},{"k":"prod","q":"给一个风险写成可监测句。","model":"若未来 90 天 CII 滚动预测降至 D 且未有经批准的整改计划，则由技术负责人在下一航次前提交节速、清洁或改造方案，并重新测算租约和收入影响。","a":"若未来 90 天 CII 滚动预测降至 D 且未有经批准的整改计划，则由技术负责人在下一航次前提交节速、清洁或改造方案，并重新测算租约和收入影响。","w":"好风险句包含指标、阈值、时限、Owner 和动作。","pre":"","id":"u12-l01-q05","source":"白皮书 5.4—5.5"}]},{"t":"MARPOL 与排放","goal":"分清 SOx、NOx、油污、垃圾和污水规则","intro":"MARPOL 各附则处理不同污染源。燃油硫限值、ECA、主机 NOx Tier、油水分离和记录簿都有不同证据。","keys":["SOx 重点在燃油硫或等效措施","NOx 与发动机年代和区域有关","记录簿造假本身是重大风险"],"trap":"把所有环保要求缩成‘装了脱硫塔就合规’。","source":"白皮书 5.6、frag_env","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"进入更严格硫排放控制区前，船舶常需？","o":["提高 GT","关闭 AIS","取消 P&I","使用合规低硫燃油或获批等效措施并完成换油记录"],"a":"使用合规低硫燃油或获批等效措施并完成换油记录","w":"合规既包括设备/燃油，也包括换油时点、取样和记录证据。","pre":"","id":"u12-l02-q01","source":"白皮书 5.6、frag_env"},{"k":"mc","q":"NOx Tier 要求主要关联？","o":["租金付款周期","船舶抵押","船用柴油机排放标准、建造/安装年代和适用海域","货舱容积"],"a":"船用柴油机排放标准、建造/安装年代和适用海域","w":"它不是燃油硫限值的另一种叫法。","pre":"","id":"u12-l02-q02","source":"白皮书 5.6、frag_env"},{"k":"tf","q":"法定污染记录的真实性本身就是合规要求，虚假补写可形成重大风险。","o":["正确","错误"],"a":"正确","w":"法定记录真实性本身是执法重点，错误或虚假记录可引发严重处罚和信誉损失。","pre":"","id":"u12-l02-q03","source":"白皮书 5.6、frag_env"},{"k":"multi","q":"检查燃油硫合规证据可包括？","o":["脱硫塔监测记录","Bunker Delivery Note","燃油样品与检测","换油程序和日志"],"a":["Bunker Delivery Note","燃油样品与检测","换油程序和日志","脱硫塔监测记录"],"w":"使用哪种合规路径，就应有对应采购、操作和监测证据。","pre":"","id":"u12-l02-q04","source":"白皮书 5.6、frag_env"},{"k":"prod","q":"解释环保合规为什么同时是技术问题和商业问题。","model":"设备、燃油和操作决定能否合规；合规方案又改变油耗、维护、停航、可挂港和租约责任，从而影响 TCE 与资产价值。","a":"设备、燃油和操作决定能否合规；合规方案又改变油耗、维护、停航、可挂港和租约责任，从而影响 TCE 与资产价值。","w":"环保投入必须进入运营和现金流模型。","pre":"","id":"u12-l02-q05","source":"白皮书 5.6、frag_env"}]},{"t":"EEDI、EEXI、CII 与 BWTS","goal":"区分设计效率、现有船技术指标和运营评级","intro":"EEDI 面向新船设计效率，EEXI 对现有船技术效率做一次性门槛评估，CII 每年看运营碳强度，BWTS 处理压载水生物转移。","keys":["EEXI 合格不保证 CII 高评级","CII 受运营策略影响","BWTS 有设备、证书和使用三层"],"trap":"把所有环保缩写视为同一张证书，或认为 CII E 就自动全球禁航。","source":"白皮书 5.6—5.7","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"哪项指标最直接随年度燃油消耗和运输工作量变化？","o":["GT","船体号","CII","IMO 号"],"a":"CII","w":"CII 是运营碳强度评级，航速、等待、航程和运量都会影响。","pre":"","id":"u12-l03-q01","source":"白皮书 5.6—5.7"},{"k":"mc","q":"EEXI 最接近解决什么问题？","o":["货物污染","抵押顺位","现有船舶技术能效是否达到规定门槛","每年租金"],"a":"现有船舶技术能效是否达到规定门槛","w":"它常通过主机功率限制、节能装置等技术方案满足，但实际运营评级仍另看 CII。","pre":"","id":"u12-l03-q02","source":"白皮书 5.6—5.7"},{"k":"tf","q":"CII 连续低评级可能触发整改计划，但不应简单表述为立即自动罚款禁航。","o":["正确","错误"],"a":"正确","w":"监管后果有程序和船旗国实施安排，商业影响还可能先通过租家、融资和估值体现。","pre":"","id":"u12-l03-q03","source":"白皮书 5.6—5.7"},{"k":"multi","q":"验证 BWTS 合规应检查？","o":["型式认可和证书","安装调试与维护","船员操作和记录","目标港口具体要求"],"a":["型式认可和证书","安装调试与维护","船员操作和记录","目标港口具体要求"],"w":"设备存在不等于能正确运行，更不保证满足所有地方执行口径。","pre":"","id":"u12-l03-q04","source":"白皮书 5.6—5.7"},{"k":"prod","q":"解释 EEXI 合格但 CII 仍可能差。","model":"EEXI 看技术设计基线，CII 看一年怎么实际运营；船即使技术门槛合格，若高速、高耗、长等待或载货效率低，年度碳强度仍可能评级较差。","a":"EEXI 看技术设计基线，CII 看一年怎么实际运营；船即使技术门槛合格，若高速、高耗、长等待或载货效率低，年度碳强度仍可能评级较差。","w":"技术能力与使用方式要分开。","pre":"","id":"u12-l03-q05","source":"白皮书 5.6—5.7"}]},{"t":"制裁与影子风险","goal":"穿透 SDN、所有权、船史、货物、港口和付款链","intro":"制裁筛查不能只搜当前船名。要用唯一编号穿透历史，识别 50% ownership、STS、AIS 异常、敏感货和支付银行。","keys":["主体、船、货、航次、钱五线并查","所有权规则可能覆盖未列名公司","筛查需在关键节点重复"],"trap":"查一次名单截图后，直到收款都不再更新。","source":"白皮书 5.7、案例 10","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"交易对手本身未列名，但由多个受制裁主体合计持有多数股权。风险是？","o":["一定安全","改英文名即可","只查船级","可能受所有权规则覆盖，需立即专业审查"],"a":"可能受所有权规则覆盖，需立即专业审查","w":"名单筛查只是入口，所有权和控制穿透可能使未列名实体也受限制。","pre":"","id":"u12-l04-q01","source":"白皮书 5.7、案例 10"},{"k":"mc","q":"船舶频繁关闭 AIS 并在高风险海域 STS，最稳健态度？","o":["自动认定合法","只提高租金","作为高风险红旗调查货物、对手和航迹，不能直接忽略","证明船速快"],"a":"作为高风险红旗调查货物、对手和航迹，不能直接忽略","w":"行为异常并非自动违法证据，但会提高规避制裁和来源不明风险。","pre":"","id":"u12-l04-q02","source":"白皮书 5.7、案例 10"},{"k":"tf","q":"船名未出现在制裁名单，交易就一定可以做。","o":["正确","错误"],"a":"错误","w":"还要查 IMO 号、历史名称、所有权控制、货物、港口、对手和金融机构。","pre":"","id":"u12-l04-q03","source":"白皮书 5.7、案例 10"},{"k":"multi","q":"制裁筛查应在哪些时点刷新？","o":["首次接触和报价前","签约/解除 Subjects 前","装货或交割前","付款前"],"a":["首次接触和报价前","签约/解除 Subjects 前","装货或交割前","付款前"],"w":"名单和事实会变化，越接近不可逆动作越要重新核验。","pre":"","id":"u12-l04-q04","source":"白皮书 5.7、案例 10"},{"k":"prod","q":"写一条制裁红旗升级结论。","model":"IMO 历史显示该船近半年三次在高风险水域长时 AIS 缺口并进行 STS，货物来源文件不完整；在独立航迹、对手受益所有权、货源及保险人确认完成前，暂停签约和付款。","a":"IMO 历史显示该船近半年三次在高风险水域长时 AIS 缺口并进行 STS，货物来源文件不完整；在独立航迹、对手受益所有权、货源及保险人确认完成前，暂停签约和付款。","w":"事实、缺口、暂停范围和解锁条件必须明确。","pre":"","id":"u12-l04-q05","source":"白皮书 5.7、案例 10"}]},{"t":"单元闯关：一票否决不是打分低","goal":"综合审查环保、保险和制裁可执行性","intro":"高回报项目也必须能合法开航、获得保险、收付资金并持续满足环保。红线不是多收一点风险溢价就自动消失。","keys":["关键节点重复筛查","合规证据和运营事实互证","No-Go 条件预先定义"],"trap":"把无法执行的方案包装成‘高风险高收益’。","source":"白皮书第 5 章综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"租金极高但收款行明确拒绝处理该航线相关资金，最合理结论？","o":["改备注规避","现金收取","现金流不可执行，应暂停并合法重构或放弃","先开航再说"],"a":"现金流不可执行，应暂停并合法重构或放弃","w":"不能收款的名义收入不是可投资现金流，规避银行筛查还会放大风险。","pre":"","id":"u12-l05-q01","source":"白皮书第 5 章综合"},{"k":"mc","q":"船舶 EEXI 合格但预计下一年度 CII 为 E，应？","o":["自动报废","只换旗国","制定并测算运营/技术整改，同时评估租约与价值影响","认为全部环保完成"],"a":"制定并测算运营/技术整改，同时评估租约与价值影响","w":"技术门槛和运营评级不同，整改可能涉及节速、清洁、改造和商业安排。","pre":"","id":"u12-l05-q02","source":"白皮书第 5 章综合"},{"k":"tf","q":"制裁风险可以仅靠合同中的一般合规保证完全转移给对手。","o":["正确","错误"],"a":"错误","w":"保证提供追索，却不能消除执法、保险、银行和声誉后果；自身筛查义务仍需履行。","pre":"","id":"u12-l05-q03","source":"白皮书第 5 章综合"},{"k":"multi","q":"批准高风险航次前的四份关键确认可包括？","o":["保险人书面覆盖确认","船舶技术/环保可行性","付款银行可处理确认","法律制裁意见"],"a":["法律制裁意见","保险人书面覆盖确认","船舶技术/环保可行性","付款银行可处理确认"],"w":"合法、可保、能做、能收钱是最低闭环。","pre":"","id":"u12-l05-q04","source":"白皮书第 5 章综合"},{"k":"order","q":"制裁异常的处理顺序。","o":["暂停不可逆动作并保全资料","用 IMO/主体标识扩展筛查","穿透所有权、货物、航迹和付款","由专业负责人形成 Go/No-Go 与条件","在签约或付款前再次刷新"],"a":["暂停不可逆动作并保全资料","用 IMO/主体标识扩展筛查","穿透所有权、货物、航迹和付款","由专业负责人形成 Go/No-Go 与条件","在签约或付款前再次刷新"],"w":"先控制暴露，再调查、决策和复核。","pre":"","id":"u12-l05-q05","source":"白皮书第 5 章综合"},{"k":"mc","q":"一张有效 IAPP 证书最能证明？","o":["永远不会违规","所有航次 CII 为 A","所有港口都接受任意燃油","船舶在证书范围和时点满足相关空气污染法定要求"],"a":"船舶在证书范围和时点满足相关空气污染法定要求","w":"证书不能替代每天的燃油、设备运行和记录合规。","pre":"","id":"u12-l05-q06","source":"白皮书第 5 章综合"},{"k":"prod","q":"给管理层一个六维一句话结论模板。","model":"技术可做、商业有货、基准现金流覆盖，但法律/制裁仍有一项未闭环且保险附加费未锁定；建议暂停 Subject 解除，待所有权穿透和保险书面确认后按更新 TCE 决策。","a":"技术可做、商业有货、基准现金流覆盖，但法律/制裁仍有一项未闭环且保险附加费未锁定；建议暂停 Subject 解除，待所有权穿透和保险书面确认后按更新 TCE 决策。","w":"一句话也要区分已通过、未通过和下一动作。","pre":"","id":"u12-l05-q07","source":"白皮书第 5 章综合"},{"k":"mc","q":"本单元最重要的判断是？","o":["收益成立前，项目必须先合法、可保、可操作且可收付","收益高就能补偿一切","证书越多越安全","只需开会表决"],"a":"收益成立前，项目必须先合法、可保、可操作且可收付","w":"可执行性是现金流的前提。","pre":"","id":"u12-l05-q08","source":"白皮书第 5 章综合"}]}]},{"id":"u13","t":"市场、周期与研究","s":"从一条新闻追到吨海里、有效供给和资产价格","c":"#159f75","i":"📈","guide":"航运需求是货量乘距离，供给是可用运力乘效率。小幅剪刀差能引发大幅运价波动；研究必须明确数据日、口径、机制和失效条件。","outcomes":["拆解吨海里与有效供给","识别航运周期和指数适用边界","把事件写成可验证研究链"],"L":[{"t":"吨海里需求","goal":"理解货量、距离和结构共同决定运输工作量","intro":"运量只告诉你多少吨，吨海里还考虑跑多远。相同货量若改走更远来源地，船舶占用时间和需求都会上升。","keys":["Tonne-mile = 吨数×距离","贸易重路由可放大需求","货种与船型不能随意合并"],"trap":"把全球产量增速直接当成所有船型运力需求增速。","source":"白皮书 6.1—6.3、案例 7","kind":"skill","difficulty":1,"q":[{"k":"num","q":"教学情景：1 百万吨货物航程从 2,000 海里改为 3,000 海里，吨海里需求增幅约？","o":["100%","0%","50%","33%"],"a":"50%","w":"货量不变时，距离由 2,000 增至 3,000，运输工作量增加 1,000/2,000＝50%。","pre":"","id":"u13-l01-q01","source":"白皮书 6.1—6.3、案例 7"},{"k":"mc","q":"某国煤炭进口吨数不变，但供应地显著变远。对相关散货运力需求的第一方向是？","o":["不受影响","GT 自动增加","吨海里增加，其他条件不变时需求增强","必然下降"],"a":"吨海里增加，其他条件不变时需求增强","w":"更长航程占用船舶更久，相同吨数需要更多船天。","pre":"","id":"u13-l01-q02","source":"白皮书 6.1—6.3、案例 7"},{"k":"tf","q":"从铁矿石产量推 Capesize 需求，还要考虑海运比例、航距、库存和船型分配。","o":["正确","错误"],"a":"正确","w":"还受海运比例、来源地距离、库存、港口和船型分配影响。","pre":"","id":"u13-l01-q03","source":"白皮书 6.1—6.3、案例 7"},{"k":"multi","q":"预测吨海里应拆哪些变量？","o":["贸易路线结构","货种与船型匹配","海运货量","平均航距"],"a":["海运货量","平均航距","贸易路线结构","货种与船型匹配"],"w":"四项决定运输工作量如何真正落到目标船型。","pre":"","id":"u13-l01-q04","source":"白皮书 6.1—6.3、案例 7"},{"k":"prod","q":"用因果链解释运河绕行为什么可能推高运价。","model":"绕行拉长航距和航行天数，使每条船一年可完成航次数下降；在货量与船队短期不变时，有效供给收紧，利用率和运价更易上升。","a":"绕行拉长航距和航行天数，使每条船一年可完成航次数下降；在货量与船队短期不变时，有效供给收紧，利用率和运价更易上升。","w":"从距离推到船天、供给和价格。","pre":"","id":"u13-l01-q05","source":"白皮书 6.1—6.3、案例 7"}]},{"t":"有效供给与剪刀差","goal":"从船队总量走到可用船天和效率","intro":"名义船队要扣修理、低速、拥堵和不可用船，再考虑航速与周转。需求和有效供给的一点差异会通过高利用率市场放大。","keys":["交付与拆解改变船队","速度和拥堵改变效率","高利用率下价格弹性非线性"],"trap":"看到手持订单就直接断言运价下跌，忽略交付时间和需求。","source":"白皮书 6.4—6.6、案例 8","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"港口拥堵增加、船队规模不变时，有效供给通常？","o":["上升","不变","由 GT 决定","下降，因为更多船天被等待占用"],"a":"下降，因为更多船天被等待占用","w":"拥堵不删除船舶，却降低可用于完成运输的周转效率。","pre":"","id":"u13-l02-q01","source":"白皮书 6.4—6.6、案例 8"},{"k":"mc","q":"新船大量交付对供给的影响为何可能延迟？","o":["订单不存在","船无需建造","交付只影响保险","交付有时间表，且旧船拆解、限速和需求可部分抵消"],"a":"交付有时间表，且旧船拆解、限速和需求可部分抵消","w":"净供给看交付、拆解和效率，不是订单簿一个比例。","pre":"","id":"u13-l02-q02","source":"白皮书 6.4—6.6、案例 8"},{"k":"tf","q":"船队 DWT 增速与有效供给增速可能因航速、拥堵和停航而不同。","o":["正确","错误"],"a":"正确","w":"航速、拥堵、停航、制裁和船型航线配置会使有效增速不同。","pre":"","id":"u13-l02-q03","source":"白皮书 6.4—6.6、案例 8"},{"k":"multi","q":"有效供给模型可纳入？","o":["期初船队与交付","拆解和损失","航速/拥堵","坞修和不可用率"],"a":["期初船队与交付","拆解和损失","航速/拥堵","坞修和不可用率"],"w":"存量、增减和效率共同决定船天。","pre":"","id":"u13-l02-q04","source":"白皮书 6.4—6.6、案例 8"},{"k":"prod","q":"解释航运的‘剪刀差’。","model":"需求吨海里和有效供给增速像两片剪刀：当需求略快于供给，尤其利用率已高时，现货运力迅速稀缺，运价可能远大于增速差地上涨；反向也会急跌。","a":"需求吨海里和有效供给增速像两片剪刀：当需求略快于供给，尤其利用率已高时，现货运力迅速稀缺，运价可能远大于增速差地上涨；反向也会急跌。","w":"关键是小差异与非线性价格反应。","pre":"","id":"u13-l02-q05","source":"白皮书 6.4—6.6、案例 8"}]},{"t":"周期时钟","goal":"区分短期扰动、中期交付和长期造船响应","intro":"天气和拥堵影响周月，贸易和库存影响季度，订单交付跨年，船厂产能和替代燃料改变更慢。市场观点必须匹配时间尺度。","keys":["供给短期刚性","高运价刺激订船但有滞后","资产价通常提前反映预期"],"trap":"用一周运价上涨证明五年结构牛市。","source":"白皮书 6.7—6.9","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"现货运价大涨后，新造船为何不能下个月就平抑市场？","o":["设计建造和交付需要数年","新船不能航行","船厂不收钱","运价与供给无关"],"a":"设计建造和交付需要数年","w":"供给反应滞后是航运周期波动大的核心原因。","pre":"","id":"u13-l03-q01","source":"白皮书 6.7—6.9"},{"k":"mc","q":"评估未来三个月运价，哪类变量通常比五年后替代燃料路线更直接？","o":["船名趋势","季节性货量、拥堵、库存和可用船位","船厂十年规划","长期人口预测单一变量"],"a":"季节性货量、拥堵、库存和可用船位","w":"时间尺度要匹配：短期看即时货盘与船位，中长期再看产能和技术。","pre":"","id":"u13-l03-q02","source":"白皮书 6.7—6.9"},{"k":"tf","q":"船价和运价一定同步、同幅度变化。","o":["正确","错误"],"a":"错误","w":"资产价反映未来盈利、利率、融资和残值预期，可能领先、滞后或放大/缩小现货变化。","pre":"","id":"u13-l03-q03","source":"白皮书 6.7—6.9"},{"k":"multi","q":"判断周期位置可组合观察？","o":["船厂交期和融资条件","运价与期租曲线","二手船价和新造价","订单簿与拆船"],"a":["运价与期租曲线","二手船价和新造价","订单簿与拆船","船厂交期和融资条件"],"w":"收入、资产、供给响应和资本可得性共同勾勒周期。","pre":"","id":"u13-l03-q04","source":"白皮书 6.7—6.9"},{"k":"prod","q":"用四阶段描述典型航运周期。","model":"复苏：需求改善、闲置减少；繁荣：运价与船价高、订船增加；过热转折：成本和订单膨胀；衰退：交付碰上需求转弱、运价跌、拆船增加。真实市场不会整齐按钟走。","a":"复苏：需求改善、闲置减少；繁荣：运价与船价高、订船增加；过热转折：成本和订单膨胀；衰退：交付碰上需求转弱、运价跌、拆船增加。真实市场不会整齐按钟走。","w":"阶段模型是观察框架，不是确定预测。","pre":"","id":"u13-l03-q05","source":"白皮书 6.7—6.9"}]},{"t":"指数与研究纪律","goal":"知道 BDI、BDTI、SCFI 等能说什么、不能说什么","intro":"指数有船型、航线、租约和发布时间口径。研究结论必须注明数据截至日、来源和估计，不能拿一个指数代表整个航运。","keys":["指数先看覆盖范围","同日口径才可比较","观点必须写监测指标与失效条件"],"trap":"拼接不同日期的漂亮数字，或用 BDI 推断油轮与集装箱。","source":"白皮书 6.10—6.12、附录 F","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"BDI 最主要反映？","o":["集装箱现货全部航线","干散货若干航线和船型的运价综合","全球所有船型利润","油轮保险费"],"a":"干散货若干航线和船型的运价综合","w":"它是干散货市场入口，不应跨船型外推。","pre":"","id":"u13-l04-q01","source":"白皮书 6.10—6.12、附录 F"},{"k":"mc","q":"研究报告同时使用今日运价和半年前船价，却未说明日期，最大问题是？","o":["颜色不统一","无法计算 GT","估值与收益口径错位，可能制造虚假吸引力","数字太多"],"a":"估值与收益口径错位，可能制造虚假吸引力","w":"航运数据变化快，所有关键数字需要同一估值日或明确调整。","pre":"","id":"u13-l04-q02","source":"白皮书 6.10—6.12、附录 F"},{"k":"tf","q":"来源可靠就不必记录数据发布日期和截至日期。","o":["正确","错误"],"a":"错误","w":"权威来源也会更新；没有时间戳就无法复现或判断信息是否已过期。","pre":"","id":"u13-l04-q03","source":"白皮书 6.10—6.12、附录 F"},{"k":"multi","q":"一条可审计市场观点应包含？","o":["因果机制","数据与口径","监测指标和失效条件","核心结论"],"a":["核心结论","因果机制","数据与口径","监测指标和失效条件"],"w":"这四项让观点可验证、可更新而非一句口号。","pre":"","id":"u13-l04-q04","source":"白皮书 6.10—6.12、附录 F"},{"k":"prod","q":"把‘BDI 涨了，所以买船’改写成研究命题。","model":"BDI 上涨是否由目标船型可持续货盘而非短期拥堵驱动？若吨海里增速持续高于有效供给，且期租和资产价尚未完全反映，则买船可能有价值；需监测货盘、船位、期租曲线和成交价。","a":"BDI 上涨是否由目标船型可持续货盘而非短期拥堵驱动？若吨海里增速持续高于有效供给，且期租和资产价尚未完全反映，则买船可能有价值；需监测货盘、船位、期租曲线和成交价。","w":"改写后有对象、机制、条件和验证指标。","pre":"","id":"u13-l04-q05","source":"白皮书 6.10—6.12、附录 F"}]},{"t":"单元闯关：从新闻到观点","goal":"综合建立需求—供给—价格—资产链","intro":"任何事件都沿五问展开：发生什么、改变哪条货流或船天、直接影响谁、二阶如何传导、什么数据能证伪。","keys":["事件不是结论","同一冲击对不同船型方向可不同","观点要有期限和阈值"],"trap":"把相关价格同涨直接写成因果。","source":"白皮书第 6 章综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"红海绕行增加集装箱航程，最直接的供需机制是？","o":["港口 GT 上升","航程延长吸收船天，短期有效供给趋紧","船队 DWT 立即减少","货物重量翻倍"],"a":"航程延长吸收船天，短期有效供给趋紧","w":"影响强弱还取决于货量、航速、额外投船和拥堵。","pre":"","id":"u13-l05-q01","source":"白皮书第 6 章综合"},{"k":"mc","q":"订单簿很高但船厂交期集中在三年后，对下季度现货判断应？","o":["记录中期压力，但短期仍看当下船位和需求","直接断言下季度崩盘","忽略订单","认为运价固定"],"a":"记录中期压力，但短期仍看当下船位和需求","w":"供给冲击的时间分布比总比例更重要。","pre":"","id":"u13-l05-q02","source":"白皮书第 6 章综合"},{"k":"tf","q":"吨海里需求上升时，目标船型运价必然上涨，不需考虑供给。","o":["正确","错误"],"a":"错误","w":"价格由需求相对有效供给决定，若供给增得更快仍可能下跌。","pre":"","id":"u13-l05-q03","source":"白皮书第 6 章综合"},{"k":"multi","q":"一条地缘事件对航运的二阶影响可包括？","o":["航线重构和燃油消耗","港口拥堵","资产价与订船行为","保险附加费"],"a":["保险附加费","航线重构和燃油消耗","港口拥堵","资产价与订船行为"],"w":"事件会通过成本、效率和预期继续传导。","pre":"","id":"u13-l05-q04","source":"白皮书第 6 章综合"},{"k":"order","q":"把焦点新闻转成研究结论的顺序。","o":["核实事件、时间和来源","映射货流、航距和有效供给","区分船型与时间尺度","估计运价/成本/资产影响","列监测指标与失效条件"],"a":["核实事件、时间和来源","映射货流、航距和有效供给","区分船型与时间尺度","估计运价/成本/资产影响","列监测指标与失效条件"],"w":"顺序防止从标题直接跳到交易。","pre":"","id":"u13-l05-q05","source":"白皮书第 6 章综合"},{"k":"num","q":"教学情景：吨海里需求增 4%，有效供给增 2%。剪刀差为？","o":["+8%","+2 个百分点","+6 个百分点","-2 个百分点"],"a":"+2 个百分点","w":"4%－2%＝2 个百分点；运价反应并不必然等于 2%。","pre":"","id":"u13-l05-q06","source":"白皮书第 6 章综合"},{"k":"prod","q":"用一句话写出可证伪的市场观点。","model":"若未来两个季度目标船型吨海里增速持续高于有效供给 2 个百分点以上，且港口等待不明显回落，则期租中枢应保持坚挺；若主要货流转弱或交付提前，观点失效。","a":"若未来两个季度目标船型吨海里增速持续高于有效供给 2 个百分点以上，且港口等待不明显回落，则期租中枢应保持坚挺；若主要货流转弱或交付提前，观点失效。","w":"要有期限、机制、阈值与反例。","pre":"","id":"u13-l05-q07","source":"白皮书第 6 章综合"},{"k":"mc","q":"最好的市场研究输出是？","o":["永远正确的方向词","指数截图合集","不写日期的数字","能被数据更新和推翻的因果判断"],"a":"能被数据更新和推翻的因果判断","w":"研究价值来自可检验和及时修正。","pre":"","id":"u13-l05-q08","source":"白皮书第 6 章综合"}]}]},{"id":"u14","t":"投资判断","s":"让回报、风险、流动性和执行同桌决策","c":"#32845d","i":"💹","guide":"船舶投资不是找最高 IRR，而是建立可审计现金流，用多指标、敏感性和退出条件判断项目是否在可承受风险内创造价值。","outcomes":["正确使用 IRR、NPV、回收期、ROE 与 ACY","建立全周期现金流和残值情景","形成可执行投资筛选与退出纪律"],"L":[{"t":"五个指标","goal":"理解 IRR、NPV、回收期、ROE 和现金收益率的用途","intro":"IRR 给内含回报率，NPV 用资本成本衡量价值，回收期看资金回笼，ROE 看杠杆后权益回报，现金收益率看当期现金产出。","keys":["指标回答不同问题","IRR 对时点和残值敏感","ROE 高可能来自高杠杆"],"trap":"用一个最高指标替代项目规模、风险和现金分布。","source":"白皮书 7.1—7.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"两个项目 IRR 相同但 A 规模大、NPV 明显更高。说明？","o":["两项目完全相同","IRR 未反映绝对价值规模，需结合 NPV","A 一定更差","NPV 无意义"],"a":"IRR 未反映绝对价值规模，需结合 NPV","w":"百分比回报和创造的绝对价值是不同维度。","pre":"","id":"u14-l01-q01","source":"白皮书 7.1—7.3"},{"k":"mc","q":"提高债务比例可能抬高基准 ROE，同时通常会？","o":["消除波动","提高船舶 DWT","取消利息","增加偿债和尾部风险"],"a":"增加偿债和尾部风险","w":"杠杆放大权益收益也放大亏损和违约概率。","pre":"","id":"u14-l01-q02","source":"白皮书 7.1—7.3"},{"k":"tf","q":"IRR 达标后仍要检查逐期负现金、追加资本和峰值资金占用。","o":["正确","错误"],"a":"正确","w":"现金缺口可能触发追加资本或违约，路径与峰值资金占用同样关键。","pre":"","id":"u14-l01-q03","source":"白皮书 7.1—7.3"},{"k":"multi","q":"投资委员会比较项目时应并列观察？","o":["下行残值和退出流动性","IRR/NPV","最低现金和回收期","DSCR 与杠杆"],"a":["IRR/NPV","最低现金和回收期","DSCR 与杠杆","下行残值和退出流动性"],"w":"价值、流动性、偿债和尾部风险需要同桌。","pre":"","id":"u14-l01-q04","source":"白皮书 7.1—7.3"},{"k":"prod","q":"一句话解释 NPV 为正。","model":"在所采用的风险调整折现率和现金流假设下，项目未来现金流现值超过初始投入，预计创造正的经济价值；结论仍取决于假设质量。","a":"在所采用的风险调整折现率和现金流假设下，项目未来现金流现值超过初始投入，预计创造正的经济价值；结论仍取决于假设质量。","w":"必须包含折现率和假设条件。","pre":"","id":"u14-l01-q05","source":"白皮书 7.1—7.3"}]},{"t":"全周期现金流","goal":"从购买、运营、融资、税费到出售","intro":"投资现金流必须覆盖入场价与费用、运营收入成本、坞修改造、债务服务、税和退出净收入，并对时间点建模。","keys":["残值是变量不是常数","坞修造成现金支出和停航双重影响","营运资金与交易费用不能漏"],"trap":"只建稳定租金年份，再把买价原样当残值。","source":"白皮书 7.4、案例 9","kind":"skill","difficulty":1,"q":[{"k":"order","q":"把简化股权现金流顺序排列。","o":["支付船价、交易费和首期资本","获得租金/运费并支付运营成本","支付坞修、税费和债务服务","出售船舶并扣交易费与剩余债务"],"a":["支付船价、交易费和首期资本","获得租金/运费并支付运营成本","支付坞修、税费和债务服务","出售船舶并扣交易费与剩余债务"],"w":"现金流从进入到持有再到退出，时点直接影响回报。","pre":"","id":"u14-l02-q01","source":"白皮书 7.4、案例 9"},{"k":"mc","q":"老船将在第二年特检，模型应怎样处理？","o":["加入修理 CAPEX、停航收入损失和不确定区间","只加一笔固定 OPEX","完全忽略","把残值提高"],"a":"加入修理 CAPEX、停航收入损失和不确定区间","w":"特检同时影响支出和 earning days，且实际修理量有范围。","pre":"","id":"u14-l02-q02","source":"白皮书 7.4、案例 9"},{"k":"tf","q":"出售船价是投资期末唯一现金流，不需扣佣金、税费和贷款余额。","o":["正确","错误"],"a":"错误","w":"股东得到的是净出售所得，要扣交易成本、税和债务清偿。","pre":"","id":"u14-l02-q03","source":"白皮书 7.4、案例 9"},{"k":"multi","q":"买入端初始现金需求可包括？","o":["经纪法律与登记费","初始修理改造","营运资金和融资费","船价/首付款"],"a":["船价/首付款","经纪法律与登记费","初始修理改造","营运资金和融资费"],"w":"只按船价准备资金会低估峰值投入。","pre":"","id":"u14-l02-q04","source":"白皮书 7.4、案例 9"},{"k":"prod","q":"解释为什么利润表盈利时项目仍可能缺现金。","model":"应收未回、贷款本金到期、坞修 CAPEX 或营运资金占用都会消耗现金，而部分利润项目非现金；因此要逐期看 cash balance 和资金缺口。","a":"应收未回、贷款本金到期、坞修 CAPEX 或营运资金占用都会消耗现金，而部分利润项目非现金；因此要逐期看 cash balance 和资金缺口。","w":"利润、现金流和偿债必须分开。","pre":"","id":"u14-l02-q05","source":"白皮书 7.4、案例 9"}]},{"t":"敏感性与残值","goal":"寻找最能让结论翻转的变量","intro":"基准情景只是一个切片。至少测试租金、利用率、OPEX、利率、坞修、残值和退出时间，并识别盈亏平衡阈值。","keys":["残值受周期和船龄双重影响","变量存在相关性","Break-even 比无穷情景更可行动"],"trap":"只做上下 10% 对称变化，却不考虑真实尾部和变量联动。","source":"白皮书 7.5—7.6","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"船舶投资 IRR 对残值特别敏感，最合理应对？","o":["固定为买价","删除退出现金流","只用最高经纪估值","设置多种退出价与时间，并披露残值贡献"],"a":"设置多种退出价与时间，并披露残值贡献","w":"残值常占总回报很大比例，不能把单点预测当事实。","pre":"","id":"u14-l03-q01","source":"白皮书 7.5—7.6"},{"k":"mc","q":"运价下跌时资产价也往往下跌。敏感性应？","o":["只降运价","只升残值","不做压力测试","考虑收入与残值相关下行，而非永远独立变化"],"a":"考虑收入与残值相关下行，而非永远独立变化","w":"周期下行会同时压缩持有现金和退出价值，形成相关尾部。","pre":"","id":"u14-l03-q02","source":"白皮书 7.5—7.6"},{"k":"tf","q":"高质量敏感性应聚焦有机制、有范围的驱动和翻转阈值，而非无差别堆情景。","o":["正确","错误"],"a":"正确","w":"关键是选择有机制、有范围的驱动并找阈值；无差别堆数会掩盖真正脆弱点。","pre":"","id":"u14-l03-q03","source":"白皮书 7.5—7.6"},{"k":"multi","q":"下行情景可联动哪些变量？","o":["利用率下降","融资利差上升","残值折价","日租下降"],"a":["日租下降","利用率下降","融资利差上升","残值折价"],"w":"市场转弱时四项可能同向恶化。","pre":"","id":"u14-l03-q04","source":"白皮书 7.5—7.6"},{"k":"prod","q":"写一个投资观点失效条件。","model":"若可锁定的一年期净租金低于 13,000 美元/日，或同龄可比船成交价跌破模型残值 20%，则基准 DSCR 与目标 IRR 同时失守，项目暂停并重新定价。","a":"若可锁定的一年期净租金低于 13,000 美元/日，或同龄可比船成交价跌破模型残值 20%，则基准 DSCR 与目标 IRR 同时失守，项目暂停并重新定价。","w":"失效条件要可监测且能触发动作。","pre":"","id":"u14-l03-q05","source":"白皮书 7.5—7.6"}]},{"t":"筛选与执行","goal":"用四道门把好项目从漂亮模型中筛出来","intro":"项目需依次通过战略适配、可执行性、风险调整回报和交易纪律。价格、条件、融资或尽调变化后要重新过门。","keys":["先排 No-Go","再比较风险调整价值","投后监测连接退出纪律"],"trap":"在模型里不断调高假设，直到项目通过。","source":"白皮书 7.7—7.8、附录 E","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"项目战略不匹配且团队无运营能力，即使基准 IRR 很高也应？","o":["直接批准","提高杠杆","隐藏风险","先评估是否 No-Go 或需要合作/能力补齐"],"a":"先评估是否 No-Go 或需要合作/能力补齐","w":"执行能力缺口会让模型收入和成本无法实现。","pre":"","id":"u14-l04-q01","source":"白皮书 7.7—7.8、附录 E"},{"k":"mc","q":"卖方突然提价 8%，最正确的模型动作？","o":["保留旧 IRR","提高残值抵消","更新全部现金流、融资和回报并重新审批","只改封面"],"a":"更新全部现金流、融资和回报并重新审批","w":"重大商业变化会重构价值和资金需求，旧批准不应自动延续。","pre":"","id":"u14-l04-q02","source":"白皮书 7.7—7.8、附录 E"},{"k":"tf","q":"项目上会后，关键假设变化也无需重新评估。","o":["正确","错误"],"a":"错误","w":"审批依赖明确假设，超出授权容差就应重新审议。","pre":"","id":"u14-l04-q03","source":"白皮书 7.7—7.8、附录 E"},{"k":"multi","q":"投后监测可围绕？","o":["DSCR/LTV 与契约","资产估值和退出窗口","实际租金与利用率","OPEX/故障和检验"],"a":["实际租金与利用率","OPEX/故障和检验","DSCR/LTV 与契约","资产估值和退出窗口"],"w":"运营、融资和资产三条线共同决定持有或退出。","pre":"","id":"u14-l04-q04","source":"白皮书 7.7—7.8、附录 E"},{"k":"prod","q":"给投资建议写一个‘有条件同意’。","model":"建议在船价不高于 X、目标租约完成信用与条款审查、技术 CAPEX 不超过 Y 且融资 DSCR 压力情景高于门槛的条件下推进；任一条件突破须重新上会。","a":"建议在船价不高于 X、目标租约完成信用与条款审查、技术 CAPEX 不超过 Y 且融资 DSCR 压力情景高于门槛的条件下推进；任一条件突破须重新上会。","w":"建议必须可执行、可暂停。","pre":"","id":"u14-l04-q05","source":"白皮书 7.7—7.8、附录 E"}]},{"t":"单元闯关：好项目不只会算","goal":"综合形成风险调整投资结论","intro":"模型、合同、技术和市场假设要指向同一个项目。先看能否做，再看值不值，最后定义何时退出或认错。","keys":["多指标而非单指标","现金路径而非年均利润","退出纪律在买入前写"],"trap":"把高 IRR 当作对缺失证据的补偿。","source":"白皮书第 7 章综合","kind":"checkpoint","difficulty":3,"q":[{"k":"mc","q":"项目基准 IRR 18%，但 70% 回报来自乐观残值。应？","o":["只看 ROE","重点压力测试退出价并降低结论置信度","直接批准","删除残值披露"],"a":"重点压力测试退出价并降低结论置信度","w":"回报集中在不可控尾部时，基准 IRR 稳健性弱。","pre":"","id":"u14-l05-q01","source":"白皮书第 7 章综合"},{"k":"mc","q":"A 项目 IRR 15%、NPV 8m；B 项目 IRR 17%、NPV 1m。正确态度？","o":["A 必然优","两者相同","结合规模、风险、资本约束和现金路径，不以 IRR 单排","B 必然优"],"a":"结合规模、风险、资本约束和现金路径，不以 IRR 单排","w":"指标给不同信息，资源约束和风险决定组合选择。","pre":"","id":"u14-l05-q02","source":"白皮书第 7 章综合"},{"k":"tf","q":"融资能提高 ROE，所以债务越多越好。","o":["正确","错误"],"a":"错误","w":"杠杆还会提高利息、契约和再融资风险，极端情况下权益价值归零。","pre":"","id":"u14-l05-q03","source":"白皮书第 7 章综合"},{"k":"multi","q":"投资备忘录应显式披露？","o":["现金流和资金缺口","关键风险及缓释","监测指标与退出条件","基准和压力假设"],"a":["基准和压力假设","现金流和资金缺口","关键风险及缓释","监测指标与退出条件"],"w":"好备忘录允许他人复算并反驳。","pre":"","id":"u14-l05-q04","source":"白皮书第 7 章综合"},{"k":"order","q":"投资决策的合理顺序。","o":["战略与合规初筛","市场、技术、合同尽调","建立全周期模型和敏感性","确定价格条件与融资","审批、执行并持续监测"],"a":["战略与合规初筛","市场、技术、合同尽调","建立全周期模型和敏感性","确定价格条件与融资","审批、执行并持续监测"],"w":"先确定可做与证据，再定价和执行。","pre":"","id":"u14-l05-q05","source":"白皮书第 7 章综合"},{"k":"num","q":"教学情景：投入 20m，一年产生股东现金 2m。当期现金收益率约？","o":["5%","20%","22%","10%"],"a":"10%","w":"2÷20＝10%；它不包含未来现金和残值，不能替代 IRR/NPV。","pre":"","id":"u14-l05-q06","source":"白皮书第 7 章综合"},{"k":"prod","q":"用‘结论—原因—脆弱点—动作’写投资意见。","model":"结论：按不超过目标价可投。原因：锁定租金覆盖 OPEX 和债务，基准 NPV 为正。脆弱点：第二年坞修和第五年残值。动作：把 CAPEX 上限设为价格条件，并按季度监测 LTV 与租约续期。","a":"结论：按不超过目标价可投。原因：锁定租金覆盖 OPEX 和债务，基准 NPV 为正。脆弱点：第二年坞修和第五年残值。动作：把 CAPEX 上限设为价格条件，并按季度监测 LTV 与租约续期。","w":"四段式把分析变成决策。","pre":"","id":"u14-l05-q07","source":"白皮书第 7 章综合"},{"k":"mc","q":"投资纪律最重要的价值是？","o":["让模型更复杂","在兴奋和压力下仍按证据、价格与退出规则行动","保证永不亏损","替代市场判断"],"a":"在兴奋和压力下仍按证据、价格与退出规则行动","w":"纪律不能消除不确定性，却能限制不可逆错误。","pre":"","id":"u14-l05-q08","source":"白皮书第 7 章综合"}]}]},{"id":"u15","t":"融资与银行控制","s":"贷款买的不只是船，也是可控的现金流和退出权","c":"#4564c7","i":"🏦","guide":"航运融资围绕船舶抵押、租金、保险和账户建立控制。借款人要理解摊还、尾款、LTV、DSCR、契约和文件链怎样共同决定权益风险。","outcomes":["比较主要融资结构与还款方式","计算 LTV、DSCR 并识别尾部风险","读懂 Term Sheet、CP 和担保文件链"],"L":[{"t":"融资结构","goal":"区分抵押贷款、租赁、夹层与项目融资思路","intro":"银行船舶贷款以抵押和现金流为核心；融资租赁把法律所有权与使用分开；夹层资本收益更高、顺位更后；项目融资更依赖特定现金流。","keys":["结构决定产权与控制","资本顺位决定价格","追索范围影响股东风险"],"trap":"只比较名义利率，不看所有权、费用、契约和退出成本。","source":"白皮书 8.1—8.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"传统船舶抵押贷款的核心担保通常包括？","o":["船舶抵押、租金和保险权益及账户控制","只看借款人 Logo","货物所有权","船员工资卡"],"a":"船舶抵押、租金和保险权益及账户控制","w":"贷款人希望在正常时获得还款，在违约时能控制资产和现金。","pre":"","id":"u15-l01-q01","source":"白皮书 8.1—8.3"},{"k":"mc","q":"融资租赁中，法律所有权通常先由谁持有？","o":["承租人船员","港口","租家货主","出租人/融资方的项目公司"],"a":"出租人/融资方的项目公司","w":"承租人取得使用和经济利益，并按合同可能最终购买；具体结构与会计税务另行分析。","pre":"","id":"u15-l01-q02","source":"白皮书 8.1—8.3"},{"k":"tf","q":"夹层融资因顺位更后、回收不确定性更高，通常要求高于一顺位贷款的回报。","o":["正确","错误"],"a":"正确","w":"夹层顺位更后、回收不确定性更高，通常要求更高回报并可能附权益安排。","pre":"","id":"u15-l01-q03","source":"白皮书 8.1—8.3"},{"k":"multi","q":"比较融资方案的全成本时应纳入？","o":["安排/承诺/代理费","对冲和账户成本","提前还款及退出费用","基准利率和利差"],"a":["基准利率和利差","安排/承诺/代理费","对冲和账户成本","提前还款及退出费用"],"w":"headline margin 只是一部分。","pre":"","id":"u15-l01-q04","source":"白皮书 8.1—8.3"},{"k":"prod","q":"为什么最便宜的融资不一定最优？","model":"低利差可能伴随更高摊还、严格现金封锁、资产处置限制、担保追索和昂贵退出；应比较全成本、灵活性与下行时的控制权。","a":"低利差可能伴随更高摊还、严格现金封锁、资产处置限制、担保追索和昂贵退出；应比较全成本、灵活性与下行时的控制权。","w":"价格、结构和韧性要共同评估。","pre":"","id":"u15-l01-q05","source":"白皮书 8.1—8.3"}]},{"t":"摊还、Balloon 与现金瀑布","goal":"理解本金怎样回收和尾款怎样形成","intro":"贷款可以等额本金、年金式或按较长年限摊还并在到期留 Balloon。尾款降低前期还款，却集中再融资与资产价值风险。","keys":["Amortization 决定去杠杆速度","Balloon 是到期未摊本金","现金瀑布决定钱先付给谁"],"trap":"把 Balloon 当成买船选择权，或只看初期 DSCR。","source":"白皮书 8.3—8.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"贷款到期 Balloon 10m 表示？","o":["可选择免费买船","银行奖励","保险赔款","到期仍需一次偿还的未摊本金"],"a":"到期仍需一次偿还的未摊本金","w":"它通常依赖出售、再融资或自有资金，属于尾部流动性风险。","pre":"","id":"u15-l02-q01","source":"白皮书 8.3—8.4"},{"k":"mc","q":"加快本金摊还通常会？","o":["增加 DWT","取消利息","提高前期债务服务但更快降低 LTV","同时降低每期付款和余额"],"a":"提高前期债务服务但更快降低 LTV","w":"现金流压力与去杠杆速度存在权衡。","pre":"","id":"u15-l02-q02","source":"白皮书 8.3—8.4"},{"k":"tf","q":"期间 DSCR 大于 1 仍需单独评估到期 Balloon 的出售或再融资来源。","o":["正确","错误"],"a":"正确","w":"期间付得起利息本金不代表到期有资金还尾款，必须看资产值、再融资和退出市场。","pre":"","id":"u15-l02-q03","source":"白皮书 8.3—8.4"},{"k":"multi","q":"受控账户现金瀑布可能依次支付？","o":["储备账户补足","满足条件后的股东分配","税费和必要运营支出","利息与本金"],"a":["税费和必要运营支出","利息与本金","储备账户补足","满足条件后的股东分配"],"w":"顺序以文件为准，核心是贷款人优先控制偿债和储备。","pre":"","id":"u15-l02-q04","source":"白皮书 8.3—8.4"},{"k":"prod","q":"解释 Balloon 为什么会把市场风险推到最后一天。","model":"前期少还本金让期内现金更轻松，却把大额余额留到到期；若届时船价、租金或融资市场转弱，出售和再融资都可能不足。","a":"前期少还本金让期内现金更轻松，却把大额余额留到到期；若届时船价、租金或融资市场转弱，出售和再融资都可能不足。","w":"尾款是时间上的风险集中。","pre":"","id":"u15-l02-q05","source":"白皮书 8.3—8.4"}]},{"t":"LTV、DSCR 与契约","goal":"用资产覆盖和现金覆盖双重监控","intro":"LTV 看贷款余额相对船价，DSCR 看现金流相对债务服务。前者受估值冲击，后者受租金、成本和利率冲击。","keys":["LTV = Debt/Value","DSCR = 可用于偿债现金/债务服务","触发后果比阈值名字更重要"],"trap":"DSCR 高就认为 LTV 无关，或把估值日期不同的数据混用。","source":"白皮书 8.4—8.5、案例 11—12","kind":"skill","difficulty":1,"q":[{"k":"num","q":"教学情景：贷款余额 36m，船舶市值 60m，LTV 为？","o":["167%","24%","60%","40%"],"a":"60%","w":"36÷60＝60%。若船价下跌而贷款不变，LTV 会升高。","pre":"","id":"u15-l03-q01","source":"白皮书 8.4—8.5、案例 11—12"},{"k":"num","q":"教学情景：可用于偿债现金 6m，年度本息 4m，DSCR 为？","o":["2.00x","10.0x","1.50x","0.67x"],"a":"1.50x","w":"6÷4＝1.5 倍，表示基准下每 1 美元债务服务有 1.5 美元现金覆盖。","pre":"","id":"u15-l03-q02","source":"白皮书 8.4—8.5、案例 11—12"},{"k":"tf","q":"船价下降 20%、贷款余额不变时，LTV 会改善。","o":["正确","错误"],"a":"错误","w":"分母变小使 LTV 上升，更可能触发补担保、提前还款或现金封锁。","pre":"","id":"u15-l03-q03","source":"白皮书 8.4—8.5、案例 11—12"},{"k":"multi","q":"DSCR 下滑可能由哪些因素造成？","o":["OPEX 上升","浮动利率上升","债务摊还增加","租金或利用率下降"],"a":["租金或利用率下降","OPEX 上升","浮动利率上升","债务摊还增加"],"w":"分子减少或分母增加都会压低覆盖。","pre":"","id":"u15-l03-q04","source":"白皮书 8.4—8.5、案例 11—12"},{"k":"prod","q":"为什么要同时看 LTV 和 DSCR？","model":"船可能有足够现金付本息但市值已跌破担保门槛，也可能资产值充足却暂时没有现金偿债；两项分别监控资产和现金流风险。","a":"船可能有足够现金付本息但市值已跌破担保门槛，也可能资产值充足却暂时没有现金偿债；两项分别监控资产和现金流风险。","w":"双指标捕捉不同违约路径。","pre":"","id":"u15-l03-q05","source":"白皮书 8.4—8.5、案例 11—12"}]},{"t":"Term Sheet 与文件链","goal":"从融资意向走到可提款的法律结构","intro":"TS 记录主要商业条件但常含非约束声明。正式融资还需信贷批准、尽调、贷款协议、抵押、转让、账户、保险和 CP。","keys":["TS 不等于已获批或可提款","文件需与船舶租约和交易同步","CP Satisfaction 是提款门槛"],"trap":"拿到 TS 就把融资记为确定，或到交割日才发现抵押登记做不了。","source":"白皮书 8.6—8.8","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"银行发出 Indicative Term Sheet 最稳健理解是？","o":["抵押已登记","所有 CP 已满足","主要条件供进一步审批和文件谈判，通常不代表无条件承诺","资金已到账"],"a":"主要条件供进一步审批和文件谈判，通常不代表无条件承诺","w":"需看约束条款、信贷批准和长式文件。","pre":"","id":"u15-l04-q01","source":"白皮书 8.6—8.8"},{"k":"mc","q":"贷款提款前为何要求保险权益确认？","o":["替代船级","确保抵押资产受损时保险安排保护贷款人","提高航速","确定货物价格"],"a":"确保抵押资产受损时保险安排保护贷款人","w":"保险转让、共同被保险和取消通知是担保包的一部分。","pre":"","id":"u15-l04-q02","source":"白皮书 8.6—8.8"},{"k":"tf","q":"融资 CP 可以在提款后慢慢补，因为银行已有抵押承诺。","o":["正确","错误"],"a":"错误","w":"关键 CP 正是提款前控制；少数后续事项也需明确期限和后果。","pre":"","id":"u15-l04-q03","source":"白皮书 8.6—8.8"},{"k":"multi","q":"典型船舶融资担保文件可包括？","o":["账户质押","股份质押和担保","法定抵押","租金与保险转让"],"a":["法定抵押","租金与保险转让","账户质押","股份质押和担保"],"w":"担保包围绕资产、现金流和项目公司控制。","pre":"","id":"u15-l04-q04","source":"白皮书 8.6—8.8"},{"k":"prod","q":"写一条融资状态汇报，避免说‘银行已经同意’。","model":"银行已发非约束 TS，利差和摊还达成商业共识，但仍待正式信贷批准、估值、KYC 和文件；当前可融资概率评为中等，最晚需在交割前十个工作日取得承诺。","a":"银行已发非约束 TS，利差和摊还达成商业共识，但仍待正式信贷批准、估值、KYC 和文件；当前可融资概率评为中等，最晚需在交割前十个工作日取得承诺。","w":"状态要区分已谈、已批、已签和可提。","pre":"","id":"u15-l04-q05","source":"白皮书 8.6—8.8"}]},{"t":"单元闯关：银行怎样看一条船","goal":"综合管理现金、资产、尾款和文件","intro":"贷款人不只看基准 DSCR，还看下行时能否控制租金、保险、账户和船舶，并在价值不足前触发保护。","keys":["期间覆盖与到期偿还分开","估值和现金都需压力测试","融资状态用证据分级"],"trap":"把漂亮 TS 和低利差当成资金确定性。","source":"白皮书第 8 章综合","kind":"checkpoint","difficulty":4,"q":[{"k":"mc","q":"船价下跌使 LTV 突破门槛，文件可能触发？","o":["免除利息","取消船级","补担保、提前还款或现金封锁等救济","自动提高 DWT"],"a":"补担保、提前还款或现金封锁等救济","w":"具体后果取决于契约和补救期。","pre":"","id":"u15-l05-q01","source":"白皮书第 8 章综合"},{"k":"mc","q":"浮动利率贷款未对冲，SOFR 上升最直接影响？","o":["利息和 DSCR","GT","船龄","货舱涂层"],"a":"利息和 DSCR","w":"债务服务分母上升会压缩现金覆盖和股东分配。","pre":"","id":"u15-l05-q02","source":"白皮书第 8 章综合"},{"k":"tf","q":"低摊还加大 Balloon，通常会改善前期现金但增加尾部风险。","o":["正确","错误"],"a":"正确","w":"这正是摊还结构的核心权衡。","pre":"","id":"u15-l05-q03","source":"白皮书第 8 章综合"},{"k":"multi","q":"评估再融资风险应看？","o":["到期 Balloon","届时预计船龄与价值","租约剩余期","信贷市场和利率"],"a":["到期 Balloon","届时预计船龄与价值","租约剩余期","信贷市场和利率"],"w":"余额、抵押物、现金流可见性和资本市场共同决定可再融资性。","pre":"","id":"u15-l05-q04","source":"白皮书第 8 章综合"},{"k":"order","q":"从 TS 到提款的主要步骤。","o":["商业谈判并取得指示性 TS","银行尽调、KYC、估值与信贷批准","谈判签署贷款和担保文件","满足或豁免提款 CP","完成抵押/转让并放款"],"a":["商业谈判并取得指示性 TS","银行尽调、KYC、估值与信贷批准","谈判签署贷款和担保文件","满足或豁免提款 CP","完成抵押/转让并放款"],"w":"意向、批准、签约和提款是四种不同状态。","pre":"","id":"u15-l05-q05","source":"白皮书第 8 章综合"},{"k":"num","q":"教学情景：船值从 60m 降到 45m，贷款仍 36m，新 LTV 为？","o":["80%","60%","75%","125%"],"a":"80%","w":"36÷45＝80%，说明价值下跌会显著侵蚀担保余量。","pre":"","id":"u15-l05-q06","source":"白皮书第 8 章综合"},{"k":"prod","q":"给融资方案写一条风险调整结论。","model":"A 方案利差低 50bp，但摊还更快且现金封锁门槛更严；在压力租金下 DSCR 仅 1.05x。建议优先谈缓冲和 Balloon 上限，若不能改善则选择全成本略高但韧性更强的 B。","a":"A 方案利差低 50bp，但摊还更快且现金封锁门槛更严；在压力租金下 DSCR 仅 1.05x。建议优先谈缓冲和 Balloon 上限，若不能改善则选择全成本略高但韧性更强的 B。","w":"不要只排序利率，要连接下行现金和控制条款。","pre":"","id":"u15-l05-q07","source":"白皮书第 8 章综合"},{"k":"mc","q":"融资安全的核心闭环是？","o":["利率最低","银行最大","文件最厚","资产、现金流、担保、契约和到期退出共同可控"],"a":"资产、现金流、担保、契约和到期退出共同可控","w":"任何一条断裂都可能让基准模型失效。","pre":"","id":"u15-l05-q08","source":"白皮书第 8 章综合"}]}]},{"id":"u16","t":"实务交付","s":"把知道变成提问、判断、沟通和可复核成果","c":"#724cc8","i":"🎓","guide":"老手不靠背更多术语，而是更快问到关键、识别征兆、把谈判资源花在高影响条款，并交付有来源、有日期、有结论的材料。","outcomes":["30 分钟内完成项目初筛","识别软信号并设置谈判优先级","产出周报、尽调清单和交割控制表"],"L":[{"t":"最初 30 分钟","goal":"用五问快速搭起项目骨架","intro":"先问交易目的、船/货、对手、合同和时间，再要最少证据。目标不是立刻给结论，而是找到会让项目停止或重构的未知。","keys":["先问为什么做","再问谁、什么资产和哪份合同","最后问时间、钱和红线"],"trap":"一上来索要全部资料，反而看不出最关键缺口。","source":"附录 E 老手工具、附录 F","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"陌生船舶项目开场最有价值的问题是？","o":["能否今天批准","我们要解决什么商业需求，收益由谁按什么合同支付","船名是什么颜色","PPT 有多少页"],"a":"我们要解决什么商业需求，收益由谁按什么合同支付","w":"目的和现金来源决定后续需要哪条船、什么租约和哪种风险审查。","pre":"","id":"u16-l01-q01","source":"附录 E 老手工具、附录 F"},{"k":"mc","q":"对方说机会只保留两小时，最佳反应是？","o":["放弃所有审查","直接付款","用更高报价换时间","明确最低信息门槛和 Stop Rules，在门槛内快速核验"],"a":"明确最低信息门槛和 Stop Rules，在门槛内快速核验","w":"紧迫性不能取消身份、制裁、资金和核心经济性控制。","pre":"","id":"u16-l01-q02","source":"附录 E 老手工具、附录 F"},{"k":"tf","q":"初筛应主动寻找致命缺口，先淘汰不可做项目，再投入深度资源。","o":["正确","错误"],"a":"正确","w":"初筛首先高效淘汰不可做项目，再把资源投向剩余机会。","pre":"","id":"u16-l01-q03","source":"附录 E 老手工具、附录 F"},{"k":"multi","q":"30 分钟项目快照应覆盖？","o":["合同与融资","时间线、红旗和下一证据","目的与收益逻辑","资产/货物和主体"],"a":["目的与收益逻辑","资产/货物和主体","合同与融资","时间线、红旗和下一证据"],"w":"四块足以形成第一张决策地图。","pre":"","id":"u16-l01-q04","source":"附录 E 老手工具、附录 F"},{"k":"prod","q":"给一个项目设计五个首问。","model":"为什么现在做、收入由谁按何合同支付、目标船和货流的硬约束是什么、对手与资金路径是否可核验、哪个日期前必须完成哪些不可逆动作；随后列最小证据包。","a":"为什么现在做、收入由谁按何合同支付、目标船和货流的硬约束是什么、对手与资金路径是否可核验、哪个日期前必须完成哪些不可逆动作；随后列最小证据包。","w":"问题应能改变 Go/No-Go，而不是满足好奇。","pre":"","id":"u16-l01-q05","source":"附录 E 老手工具、附录 F"}]},{"t":"Q88 与租约追问","goal":"从参数和合同中追到真正不确定性","intro":"高手不重复抄 Q88，而是找空白、异常、临近到期和与商业假设冲突的字段；看租约则先抓责任、触发和救济。","keys":["每个关键数字问口径和证据","每个条款问最坏情景","每个缺口指定关闭动作"],"trap":"把提问数量当专业度，不对问题排序。","source":"附录 E.1—E.2","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"Q88 中油耗比同型船低很多，最好的追问是？","o":["假设是新技术","删除可比船","该数据在何载况、航速、天气和时间段测得，有何原始证据","直接写进模型"],"a":"该数据在何载况、航速、天气和时间段测得，有何原始证据","w":"异常好数字比普通数字更需要条件和证据。","pre":"","id":"u16-l02-q01","source":"附录 E.1—E.2"},{"k":"mc","q":"租约写‘reasonable endeavours’，实务上应追问？","o":["改成彩色","具体义务边界、衡量标准和未做到的后果","翻译成尽力即可","忽略"],"a":"具体义务边界、衡量标准和未做到的后果","w":"抽象标准需要结合事实、先例和救济理解，不宜当成确定结果承诺。","pre":"","id":"u16-l02-q02","source":"附录 E.1—E.2"},{"k":"tf","q":"同一问题向十个人重复询问，一定比先查证书和合同更有效。","o":["正确","错误"],"a":"错误","w":"先定位最佳证据，再找责任人解释差异，能减少噪声。","pre":"","id":"u16-l02-q03","source":"附录 E.1—E.2"},{"k":"multi","q":"高价值追问常来自哪些信号？","o":["责任方说法不断变化","数字异常好或相互矛盾","关键字段空白","重大日期临近"],"a":["数字异常好或相互矛盾","关键字段空白","重大日期临近","责任方说法不断变化"],"w":"异常、缺失、时间和不一致是信息优先级。","pre":"","id":"u16-l02-q04","source":"附录 E.1—E.2"},{"k":"prod","q":"把‘这条船状态好吗’改成可验证问题。","model":"请提供截至同一日期的船级状态、最近特检/坞检和测厚、过去 24 个月重大故障维修、PSC 缺陷及当前待办，并说明未来 24 个月计划 CAPEX。","a":"请提供截至同一日期的船级状态、最近特检/坞检和测厚、过去 24 个月重大故障维修、PSC 缺陷及当前待办，并说明未来 24 个月计划 CAPEX。","w":"把形容词拆成证据、时间和前瞻成本。","pre":"","id":"u16-l02-q05","source":"附录 E.1—E.2"}]},{"t":"征兆与谈判子弹","goal":"识别软信号并把资源留给高价值条款","intro":"文件迟交、版本频繁变化、账户临时更换、异常催促和不愿授权查验，都是需要升级的征兆。谈判优先级看财务影响、发生概率和不可逆性。","keys":["信号不是定罪但会调整审查深度","先守红线再优化小条款","每次让步换取对价"],"trap":"在小措辞上耗尽时间，却放过担保、付款和退出权。","source":"附录 E.3","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"卖方对餐饮小条款快速配合，却拒绝提供抵押注销路径。谈判应？","o":["忽略抵押","把资源集中到清洁产权和同步交割红线","继续谈餐饮","先付款表示信任"],"a":"把资源集中到清洁产权和同步交割红线","w":"高影响不可逆事项必须优先，不能被低价值配合转移注意。","pre":"","id":"u16-l03-q01","source":"附录 E.3"},{"k":"mc","q":"对方在付款前更换账户并强调保密，属于？","o":["提高 TCE","需立即暂停并升级的欺诈红旗","正常小事","证明信用好"],"a":"需立即暂停并升级的欺诈红旗","w":"账户变化、紧迫和保密组合是高危信号。","pre":"","id":"u16-l03-q02","source":"附录 E.3"},{"k":"tf","q":"软信号不能单独证明欺诈，所以完全不应影响交易流程。","o":["正确","错误"],"a":"错误","w":"信号用于调整验证和暂停阈值，不等同最终定性。","pre":"","id":"u16-l03-q03","source":"附录 E.3"},{"k":"multi","q":"谈判优先级可按哪些维度评分？","o":["是否不可逆","替代方案和时间","现金影响","发生概率"],"a":["现金影响","发生概率","是否不可逆","替代方案和时间"],"w":"四维帮助把有限子弹用在真正改变结果的条款。","pre":"","id":"u16-l03-q04","source":"附录 E.3"},{"k":"prod","q":"写一个有对价的让步。","model":"我们可接受将交付窗口延长三天，前提是卖方同步延长押金退款和融资条件截止、承担由此产生的额外检查费，并在今日提供更新交割计划。","a":"我们可接受将交付窗口延长三天，前提是卖方同步延长押金退款和融资条件截止、承担由此产生的额外检查费，并在今日提供更新交割计划。","w":"让步要限定范围并换回价值。","pre":"","id":"u16-l03-q05","source":"附录 E.3"}]},{"t":"四种交付物","goal":"产出周报、尽调矩阵、决策备忘和交割清单","intro":"高质量交付物共同具备：一页结论、同一数据日、来源和口径、事实与判断分开、责任人和下一动作。","keys":["周报解释变化与机制","尽调矩阵连接发现和条件","交割清单驱动分钟级执行"],"trap":"做资料汇编，没有观点、状态和决策请求。","source":"附录 F.1—F.4","kind":"skill","difficulty":1,"q":[{"k":"mc","q":"航运周报最不应缺少？","o":["本周变化、驱动机制、下周监测与观点失效条件","大量无日期截图","所有新闻全文","不注明船型的指数"],"a":"本周变化、驱动机制、下周监测与观点失效条件","w":"周报的价值在更新判断，不是堆信息。","pre":"","id":"u16-l04-q01","source":"附录 F.1—F.4"},{"k":"mc","q":"尽调矩阵中‘收到文件’之后还应有？","o":["页数","文件颜色","下载次数","核验结果、影响、状态、Owner 和关闭条件"],"a":"核验结果、影响、状态、Owner 和关闭条件","w":"材料到达只是流程状态，不是风险结论。","pre":"","id":"u16-l04-q02","source":"附录 F.1—F.4"},{"k":"tf","q":"同一报告若混用不同日期的运价、船价和汇率，必须披露并调整口径。","o":["正确","错误"],"a":"正确","w":"日期错位会制造不可复现的估值与回报。","pre":"","id":"u16-l04-q03","source":"附录 F.1—F.4"},{"k":"multi","q":"决策备忘首页应让读者迅速看到？","o":["建议和请求决定","核心依据","重大风险和条件","关键数字及口径"],"a":["建议和请求决定","核心依据","重大风险和条件","关键数字及口径"],"w":"详情可下沉附录，第一页先支持决策。","pre":"","id":"u16-l04-q04","source":"附录 F.1—F.4"},{"k":"prod","q":"写一个高质量周报标题和副标题。","model":"标题：‘绕航吸收船天，但新增运力将在四季度压低弹性’；副标题：‘本周运价上涨来自航距与拥堵，若港口等待回落且交付按期，观点转为中性。’","a":"标题：‘绕航吸收船天，但新增运力将在四季度压低弹性’；副标题：‘本周运价上涨来自航距与拥堵，若港口等待回落且交付按期，观点转为中性。’","w":"标题本身要表达机制和条件，而非‘市场周报第 32 期’。","pre":"","id":"u16-l04-q05","source":"附录 F.1—F.4"}]},{"t":"毕业闯关：从小白到能交付","goal":"综合完成一项全链条航运判断","intro":"最后一关没有万能公式。你要从需求、船、合同、市场、技术、风险、融资和文件中找到真正支配决策的几条线。","keys":["先证据后观点","先可执行后收益","结论附条件和失效点"],"trap":"试图展示知道很多，而没有明确建议。","source":"白皮书 v2.1 全书综合","kind":"checkpoint","difficulty":4,"q":[{"k":"mc","q":"收到‘买一艘便宜老船跑高租金航线’提案，第一优先是？","o":["验证货流/租约、船况合规和全周期现金流是否同一情景","直接计算船价除日租","只看 IRR","先选船名"],"a":"验证货流/租约、船况合规和全周期现金流是否同一情景","w":"便宜、老船和高租金各带条件，必须用同一时间口径和可执行证据连接。","pre":"","id":"u16-l05-q01","source":"白皮书 v2.1 全书综合"},{"k":"mc","q":"项目收益很好，但交割账户异常且制裁穿透未完。结论应？","o":["提高收益率继续","让对方保证即可","拆分付款规避","暂停付款与交割，先关闭红线"],"a":"暂停付款与交割，先关闭红线","w":"欺诈和制裁属于可否决风险，不能由经济回报补偿。","pre":"","id":"u16-l05-q02","source":"白皮书 v2.1 全书综合"},{"k":"tf","q":"专业结论可以是‘目前证据不足，暂不建议推进’，前提是说明缺什么和如何解锁。","o":["正确","错误"],"a":"正确","w":"承认不确定性并给出关闭路径，比伪造确定性更专业。","pre":"","id":"u16-l05-q03","source":"白皮书 v2.1 全书综合"},{"k":"multi","q":"一份完整投资建议必须让哪些链条互相一致？","o":["船舶能力与技术状态","成本、融资与现金流","合规、文件与执行时间线","市场与租约收入"],"a":["市场与租约收入","船舶能力与技术状态","成本、融资与现金流","合规、文件与执行时间线"],"w":"四条链共同支撑可执行价值。","pre":"","id":"u16-l05-q04","source":"白皮书 v2.1 全书综合"},{"k":"order","q":"完成陌生项目的全栈分析顺序。","o":["定义目标与最低成功标准","建立主体、资产、合同和时间地图","收集并验证市场技术法律证据","建立基准与压力现金流","形成条件化建议、执行和监测计划"],"a":["定义目标与最低成功标准","建立主体、资产、合同和时间地图","收集并验证市场技术法律证据","建立基准与压力现金流","形成条件化建议、执行和监测计划"],"w":"从问题定义到证据、模型和行动，避免分析漂移。","pre":"","id":"u16-l05-q05","source":"白皮书 v2.1 全书综合"},{"k":"mc","q":"当数据互相冲突时，正确做法是？","o":["隐藏冲突","记录版本和来源，寻找权威证据并保留不确定性","选对项目最有利的","取平均后删掉原值"],"a":"记录版本和来源，寻找权威证据并保留不确定性","w":"冲突是需要解决的事实，不是排版问题。","pre":"","id":"u16-l05-q06","source":"白皮书 v2.1 全书综合"},{"k":"prod","q":"给出你的毕业版项目结论模板。","model":"建议/不建议在明确价格与条件下推进；依据是目标货流、可执行租约、经验证船况和风险调整现金流；当前三项关键未知及其最晚关闭日；若某监测阈值触发则重定价、暂停或退出；所有数字注明估值日和来源。","a":"建议/不建议在明确价格与条件下推进；依据是目标货流、可执行租约、经验证船况和风险调整现金流；当前三项关键未知及其最晚关闭日；若某监测阈值触发则重定价、暂停或退出；所有数字注明估值日和来源。","w":"模板必须能直接驱动决策和后续责任。","pre":"","id":"u16-l05-q07","source":"白皮书 v2.1 全书综合"},{"k":"mc","q":"真正的‘航运全栈’能力是什么？","o":["背下最多缩写","预测每次运价","永远不说不知道","把专业知识连接成可验证、可计算、可执行的判断"],"a":"把专业知识连接成可验证、可计算、可执行的判断","w":"课程终点不是答题，而是知道先问什么、用什么证据、怎么算、何时停。","pre":"","id":"u16-l05-q08","source":"白皮书 v2.1 全书综合"}]}]}];
